window.BraidData.sources["BraidCore"] = {"module":"BraidCore","files":[{"path":"Sources/BraidCore/Data/CorpusModels.swift","lines":187,"bytes":7186,"header":{"lines":[1,13],"what":[8,9],"pin":[10,12],"in":null,"out":null},"marks":[],"first":0,"scopes":[["S","Fact",null,"public",22,22,[22,63],67,[17,21],-1,0],["i","init",["id","kind","documentID","partitionIndex","subject","prompt","answer","sentence","sentenceStart","contextStart","answerStart","answerEnd","paraphrases","negativePrompt","questions","negativeQuestions"],"public",47,47,[49,121],66,null,0,0],["S","FactQuestion",null,"public",70,70,[70,57],78,[69,69],-1,0],["i","init",["text","stem"],"public",74,74,[74,44],77,null,2,0],["S","CorpusPartition",null,"public",80,80,[80,60],93,null,-1,0],["i","init",["index","text","textSHA256","url"],"public",87,87,[87,82],92,null,4,0],["S","CorpusDocument",null,"public",95,95,[95,73],116,null,-1,0],["i","init",["id","name","kind","subject","partitions","facts","textSHA256"],"public",105,105,[105,146],113,null,6,0],["v","text",null,"public",115,115,[115,28],115,null,6,8],["S","CorpusManifest",null,"public",118,118,[118,59],132,null,-1,0],["S","GeneratedCorpus",null,"public",134,134,[134,51],158,null,-1,0],["i","init",["manifest","documents"],"public",139,139,[139,71],142,null,10,0],["v","facts",null,"public",144,144,[144,29],144,null,10,8],["v","corpusEntries",null,"public",146,146,[146,56],150,null,10,0],["v","recomputedCorpusHash",null,"public",153,153,[153,44],157,[152,152],10,0],["S","SourceAddress",null,"public",162,162,[162,57],176,[160,161],-1,0],["i","init",["threadID","documentID","partitionIndex","tokenOffset","partitionURL"],"public",169,169,[169,129],175,null,15,0],["S","TokenPosition",null,"public",179,179,[179,57],187,[178,178],-1,0],["i","init",["row","offset"],"public",183,183,[183,39],186,null,17,0]],"text":"//\n//  CorpusModels.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: A corpus as a dataset node stores it and as Braid deposits it into a lane: documents,\n//        their partitions (the citation unit), and the facts each one states.\n//  PIN:  A partition's address is (documentID, partitionIndex), never Thread's partition id\n//        (which hashes the embedding). Kinds are plain strings: Braid reads RaoLM's datasets, it\n//        does not generate them, so it carries no generator vocabulary.\n//\n\nimport Foundation\n\n/// One fact a document states, located precisely inside its partition.\n///\n/// Offsets are UTF-8 byte offsets into the partition text. `answer` begins with the space that\n/// separates it from `prompt`, so the prompt/answer boundary is also a token boundary under a\n/// byte-level BPE.\npublic struct Fact: Codable, Sendable, Equatable, Identifiable {\n    public var id: String\n    public var kind: String\n    public var documentID: String\n    public var partitionIndex: Int\n    /// The entity the fact is about, as it appears in the text.\n    public var subject: String\n    public var prompt: String\n    public var answer: String\n    public var sentence: String\n    public var sentenceStart: Int\n    /// Start of the sentence before this one in the same partition (or `sentenceStart`).\n    public var contextStart: Int\n    /// Offset of the space before the answer value.\n    public var answerStart: Int\n    public var answerEnd: Int\n    /// Prompts for the same fact that do not occur anywhere in the corpus.\n    public var paraphrases: [String]\n    /// The same template about an entity that exists nowhere in the corpus.\n    public var negativePrompt: String\n    /// Natural questions about the fact, each with the corpus-style stem it should rewrite to.\n    /// Nil in datasets generated before questions.\n    public var questions: [FactQuestion]?\n    public var negativeQuestions: [FactQuestion]?\n\n    public init(id: String, kind: String, documentID: String, partitionIndex: Int, subject: String, prompt: String, answer: String,\n                sentence: String, sentenceStart: Int, contextStart: Int, answerStart: Int, answerEnd: Int, paraphrases: [String] = [],\n                negativePrompt: String = \"\", questions: [FactQuestion]? = nil, negativeQuestions: [FactQuestion]? = nil) {\n        self.id = id\n        self.kind = kind\n        self.documentID = documentID\n        self.partitionIndex = partitionIndex\n        self.subject = subject\n        self.prompt = prompt\n        self.answer = answer\n        self.sentence = sentence\n        self.sentenceStart = sentenceStart\n        self.contextStart = contextStart\n        self.answerStart = answerStart\n        self.answerEnd = answerEnd\n        self.paraphrases = paraphrases\n        self.negativePrompt = negativePrompt\n        self.questions = questions\n        self.negativeQuestions = negativeQuestions\n    }\n}\n\n/// A question about a fact and the stem the commons' adapter should rewrite it to.\npublic struct FactQuestion: Codable, Sendable, Equatable {\n    public var text: String\n    public var stem: String\n\n    public init(text: String, stem: String) {\n        self.text = text\n        self.stem = stem\n    }\n}\n\npublic struct CorpusPartition: Codable, Sendable, Equatable {\n    public var index: Int\n    public var text: String\n    public var textSHA256: String\n    /// The address the corpus supplies to a Thread for this partition.\n    public var url: String\n\n    public init(index: Int, text: String, textSHA256: String? = nil, url: String) {\n        self.index = index\n        self.text = text\n        self.textSHA256 = textSHA256 ?? ContentHash.sha256Hex(text)\n        self.url = url\n    }\n}\n\npublic struct CorpusDocument: Codable, Sendable, Equatable, Identifiable {\n    public var id: String\n    public var name: String\n    public var kind: String\n    public var subject: String\n    public var partitions: [CorpusPartition]\n    public var facts: [Fact]\n    /// SHA-256 of the partitions joined by a blank line (the document's canonical text).\n    public var textSHA256: String\n\n    public init(id: String, name: String, kind: String, subject: String, partitions: [CorpusPartition], facts: [Fact], textSHA256: String? = nil) {\n        self.id = id\n        self.name = name\n        self.kind = kind\n        self.subject = subject\n        self.partitions = partitions\n        self.facts = facts\n        self.textSHA256 = textSHA256 ?? ContentHash.sha256Hex(partitions.map(\\.text).joined(separator: \"\\n\\n\"))\n    }\n\n    public var text: String { partitions.map(\\.text).joined(separator: \"\\n\\n\") }\n}\n\npublic struct CorpusManifest: Codable, Sendable, Equatable {\n    public var schemaVersion: Int\n    public var slug: String\n    public var generator: String\n    public var generatorVersion: Int\n    public var seed: UInt64\n    public var documentCount: Int\n    public var partitionCount: Int\n    public var factCount: Int\n    public var chunkMaxChars: Int\n    public var chunkMinChars: Int\n    /// In generation order, which is the feeding order.\n    public var documentIDs: [String]\n    public var corpusHash: String\n}\n\npublic struct GeneratedCorpus: Sendable, Equatable {\n    public var manifest: CorpusManifest\n    /// In feeding order.\n    public var documents: [CorpusDocument]\n\n    public init(manifest: CorpusManifest, documents: [CorpusDocument]) {\n        self.manifest = manifest\n        self.documents = documents\n    }\n\n    public var facts: [Fact] { documents.flatMap(\\.facts) }\n\n    public var corpusEntries: [ContentHash.CorpusEntry] {\n        documents.flatMap { document in\n            document.partitions.map { ContentHash.CorpusEntry(documentID: document.id, partitionIndex: $0.index, textSHA256: $0.textSHA256) }\n        }\n    }\n\n    /// The corpus hash recomputed from the documents' texts (not the stored SHAs).\n    public var recomputedCorpusHash: String {\n        ContentHash.corpusHash(documents.flatMap { document in\n            document.partitions.map { ContentHash.CorpusEntry(documentID: document.id, partitionIndex: $0.index, textSHA256: ContentHash.sha256Hex($0.text)) }\n        })\n    }\n}\n\n/// Where a cited token lives: the Thread, the document, the partition inside it, and the token\n/// offset inside that partition's own tokenization.\npublic struct SourceAddress: Codable, Sendable, Hashable {\n    public var threadID: String?\n    public var documentID: String\n    public var partitionIndex: Int\n    public var tokenOffset: Int\n    public var partitionURL: String?\n\n    public init(threadID: String? = nil, documentID: String, partitionIndex: Int, tokenOffset: Int, partitionURL: String? = nil) {\n        self.threadID = threadID\n        self.documentID = documentID\n        self.partitionIndex = partitionIndex\n        self.tokenOffset = tokenOffset\n        self.partitionURL = partitionURL\n    }\n}\n\n/// A position in an index's partition table: the row and the token offset inside it.\npublic struct TokenPosition: Codable, Sendable, Hashable {\n    public var row: Int\n    public var offset: Int\n\n    public init(row: Int, offset: Int) {\n        self.row = row\n        self.offset = offset\n    }\n}\n"},{"path":"Sources/BraidCore/Data/CorpusSnapshot.swift","lines":165,"bytes":7475,"header":{"lines":[1,12],"what":[8,9],"pin":[10,11],"in":null,"out":null},"marks":[],"first":19,"scopes":[["S","SnapshotPartition",null,"public",16,16,[16,62],30,null,-1,0],["i","init",["index","text","url","threadPartitionID"],"public",23,23,[23,96],29,null,0,0],["S","SnapshotDocument",null,"public",32,32,[32,75],56,null,-1,0],["i","init",["id","name","ownerID","groupID","groupLabel","createdAt","mediaType","partitions"],"public",43,43,[44,49],53,null,2,0],["v","text",null,"public",55,55,[55,28],55,null,2,8],["S","CorpusSnapshot",null,"public",58,58,[58,59],143,null,-1,0],["i","init",["documents","slug","source","threadID","owner","group","documentIDPrefix","exportedAt"],"public",75,75,[76,69],92,null,5,0],["f","offline",["_","source","owner","group","createdAt"],"public static",95,95,[96,100],109,[94,94],5,0],["f","document",["id"],"public",111,111,[111,58],111,null,5,8],["f","changes",["since"],"public",115,115,[115,75],133,[113,114],5,0],["f","table",["_"],"",116,116,[116,68],122,null,9,4],["f","save",["to"],"public",137,137,[137,47],137,null,5,8],["f","load",["from"],"public static",139,139,[139,74],142,null,5,0],["S","SnapshotChange",null,"public",147,147,[147,59],165,[145,146],-1,0],["i","init",["added","removed","changed","addedDocuments","removedDocuments"],"public",154,154,[154,150],160,null,13,0],["v","isEmpty",null,"public",162,162,[162,29],162,null,13,8],["v","summary",null,"public",164,164,[164,31],164,[163,163],13,8]],"text":"//\n//  CorpusSnapshot.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: A corpus exactly as a source returned it: document ids, names, groups, partition texts\n//        in stored order, and the lane's own partition ids and urls.\n//  PIN:  Training and indexing only ever consume a snapshot, and the snapshot's corpus hash goes\n//        into every version and index manifest, so a Thread can prove which lane state it saw.\n//\n\nimport Foundation\n\npublic struct SnapshotPartition: Codable, Sendable, Equatable {\n    public var index: Int\n    public var text: String\n    public var textSHA256: String\n    public var url: String?\n    public var threadPartitionID: String?\n\n    public init(index: Int, text: String, url: String? = nil, threadPartitionID: String? = nil) {\n        self.index = index\n        self.text = text\n        self.textSHA256 = ContentHash.sha256Hex(text)\n        self.url = url\n        self.threadPartitionID = threadPartitionID\n    }\n}\n\npublic struct SnapshotDocument: Codable, Sendable, Equatable, Identifiable {\n    public var id: String\n    public var name: String\n    public var ownerID: String\n    public var groupID: String\n    public var groupLabel: String\n    /// Milliseconds since 1970, as the lane reports it; 0 when unknown.\n    public var createdAt: Int64\n    public var mediaType: String\n    public var partitions: [SnapshotPartition]\n\n    public init(id: String, name: String, ownerID: String, groupID: String, groupLabel: String, createdAt: Int64, mediaType: String,\n                partitions: [SnapshotPartition]) {\n        self.id = id\n        self.name = name\n        self.ownerID = ownerID\n        self.groupID = groupID\n        self.groupLabel = groupLabel\n        self.createdAt = createdAt\n        self.mediaType = mediaType\n        self.partitions = partitions\n    }\n\n    public var text: String { partitions.map(\\.text).joined(separator: \"\\n\\n\") }\n}\n\npublic struct CorpusSnapshot: Codable, Sendable, Equatable {\n    public var schemaVersion: Int\n    public var corpusHash: String\n    public var slug: String?\n    /// `aii:<aii>/<lane>`, `app:<aii>/<app>`, `dataset:<name>#<node>`, `dir:<path>`.\n    public var source: String\n    public var threadID: String?\n    public var owner: String\n    /// The group exported; empty for an app's records, which span every group of the app's owner.\n    public var group: String\n    public var documentIDPrefix: String\n    public var exportedAt: Date\n    public var documentCount: Int\n    public var partitionCount: Int\n    /// Sorted by document id (ExportCorpus order).\n    public var documents: [SnapshotDocument]\n\n    public init(documents: [SnapshotDocument], slug: String?, source: String, threadID: String?, owner: String, group: String,\n                documentIDPrefix: String, exportedAt: Date = Date()) {\n        let sorted = documents.sorted { $0.id < $1.id }\n        schemaVersion = 1\n        self.documents = sorted\n        self.slug = slug\n        self.source = source\n        self.threadID = threadID\n        self.owner = owner\n        self.group = group\n        self.documentIDPrefix = documentIDPrefix\n        self.exportedAt = exportedAt\n        documentCount = sorted.count\n        partitionCount = sorted.reduce(0) { $0 + $1.partitions.count }\n        corpusHash = ContentHash.corpusHash(sorted.flatMap { document in\n            document.partitions.map { ContentHash.CorpusEntry(documentID: document.id, partitionIndex: $0.index, textSHA256: $0.textSHA256) }\n        })\n    }\n\n    /// A snapshot built straight from a corpus, without a lane: dataset nodes and directories.\n    public static func offline(_ corpus: GeneratedCorpus, source: String, owner: String = \"offline\", group: String = \"offline\",\n                               createdAt: (CorpusDocument) -> Int64 = { _ in 0 }) -> CorpusSnapshot {\n        let documents = corpus.documents.map { document in\n            SnapshotDocument(id: document.id, name: document.name, ownerID: owner, groupID: group, groupLabel: group,\n                             createdAt: createdAt(document), mediaType: \"text\",\n                             partitions: document.partitions.map { SnapshotPartition(index: $0.index, text: $0.text, url: $0.url) })\n        }\n        let prefix = corpus.documents.first.map { id -> String in\n            // The ids' common `<scheme>-<slug>-` prefix, whatever generator wrote them.\n            let parts = id.id.split(separator: \"-\")\n            return parts.count >= 3 ? parts.dropLast().joined(separator: \"-\") + \"-\" : \"\"\n        } ?? \"\"\n        return CorpusSnapshot(documents: documents, slug: corpus.manifest.slug, source: source, threadID: nil, owner: owner, group: group,\n                              documentIDPrefix: prefix, exportedAt: Date(timeIntervalSince1970: 0))\n    }\n\n    public func document(id: String) -> SnapshotDocument? { documents.first { $0.id == id } }\n\n    /// What changed since `previous`, keyed by (document id, partition index, text SHA-256).\n    /// Nil `previous` means everything was added.\n    public func changes(since previous: CorpusSnapshot?) -> SnapshotChange {\n        func table(_ snapshot: CorpusSnapshot?) -> [String: String] {\n            var result: [String: String] = [:]\n            for document in snapshot?.documents ?? [] {\n                for partition in document.partitions { result[\"\\(document.id)#\\(partition.index)\"] = partition.textSHA256 }\n            }\n            return result\n        }\n        let now = table(self)\n        let before = table(previous)\n        let documentsNow = Set(documents.map(\\.id))\n        let documentsBefore = Set(previous?.documents.map(\\.id) ?? [])\n        return SnapshotChange(\n            added: now.keys.filter { before[$0] == nil }.sorted(),\n            removed: before.keys.filter { now[$0] == nil }.sorted(),\n            changed: now.keys.filter { before[$0] != nil && before[$0] != now[$0] }.sorted(),\n            addedDocuments: documentsNow.subtracting(documentsBefore).sorted(),\n            removedDocuments: documentsBefore.subtracting(documentsNow).sorted())\n    }\n\n    public static let fileName = \"snapshot.json\"\n\n    public func save(to directory: URL) throws { try JSONCoding.write(self, to: directory.appendingPathComponent(Self.fileName)) }\n\n    public static func load(from directory: URL) throws -> CorpusSnapshot {\n        let url = directory.lastPathComponent.hasSuffix(\".json\") ? directory : directory.appendingPathComponent(fileName)\n        return try JSONCoding.read(CorpusSnapshot.self, from: url)\n    }\n}\n\n/// The partitions (as `documentID#index`) and documents one snapshot adds, removes or changes\n/// relative to another.\npublic struct SnapshotChange: Codable, Sendable, Equatable {\n    public var added: [String]\n    public var removed: [String]\n    public var changed: [String]\n    public var addedDocuments: [String]\n    public var removedDocuments: [String]\n\n    public init(added: [String] = [], removed: [String] = [], changed: [String] = [], addedDocuments: [String] = [], removedDocuments: [String] = []) {\n        self.added = added\n        self.removed = removed\n        self.changed = changed\n        self.addedDocuments = addedDocuments\n        self.removedDocuments = removedDocuments\n    }\n\n    public var isEmpty: Bool { added.isEmpty && removed.isEmpty && changed.isEmpty }\n    /// `+8 −2 ~1` in partitions.\n    public var summary: String { \"+\\(added.count) −\\(removed.count) ~\\(changed.count)\" }\n}\n"},{"path":"Sources/BraidCore/Data/CorpusStore.swift","lines":40,"bytes":1586,"header":{"lines":[1,11],"what":[8,9],"pin":[10,10],"in":null,"out":null},"marks":[],"first":36,"scopes":[["E","CorpusStore",null,"public",15,15,[15,24],30,null,-1,0,[]],["f","load",["_"],"public static",16,16,[16,72],25,null,0,0],["f","exists",["at"],"public static",27,27,[27,57],29,null,0,0],["E","CorpusStoreError",null,"public",32,32,[32,72],40,null,-1,0,["notACorpus"]],["v","description",null,"public",35,35,[35,35],39,null,3,0]],"text":"//\n//  CorpusStore.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: Reads a corpus directory as RaoLM's dataset generator wrote it: manifest.json,\n//        facts.jsonl, documents/<id>.json (and .txt, which Braid does not read).\n//  PIN:  Read only. Braid does not write corpora of this shape; a dataset node is a source.\n//\n\nimport Foundation\n\npublic enum CorpusStore {\n    public static func load(_ directory: URL) throws -> GeneratedCorpus {\n        let manifestURL = directory.appendingPathComponent(\"manifest.json\")\n        guard FileManager.default.fileExists(atPath: manifestURL.path) else { throw CorpusStoreError.notACorpus(directory.path) }\n        let manifest = try JSONCoding.read(CorpusManifest.self, from: manifestURL)\n        let documentsDirectory = directory.appendingPathComponent(\"documents\", isDirectory: true)\n        let documents = try manifest.documentIDs.map { id in\n            try JSONCoding.read(CorpusDocument.self, from: documentsDirectory.appendingPathComponent(\"\\(id).json\"))\n        }\n        return GeneratedCorpus(manifest: manifest, documents: documents)\n    }\n\n    public static func exists(at directory: URL) -> Bool {\n        FileManager.default.fileExists(atPath: directory.appendingPathComponent(\"manifest.json\").path)\n    }\n}\n\npublic enum CorpusStoreError: Error, CustomStringConvertible, Equatable {\n    case notACorpus(String)\n\n    public var description: String {\n        switch self {\n        case .notACorpus(let path): return \"no corpus manifest.json in \\(path)\"\n        }\n    }\n}\n"},{"path":"Sources/BraidCore/Data/DatasetModel.swift","lines":159,"bytes":5903,"header":{"lines":[1,14],"what":[8,10],"pin":[11,13],"in":null,"out":null},"marks":[],"first":41,"scopes":[["E","CrossKind",null,"public",19,19,[19,63],21,[18,18],-1,0,["paraphrase","excerpt","summary","variant","homonym"]],["S","DatasetDocumentRef",null,"public",23,23,[23,62],31,null,-1,0],["i","init",["node","documentID"],"public",27,27,[27,50],30,null,1,0],["S","DatasetSharedFact",null,"public",34,34,[34,62],42,[33,33],-1,0],["v","agrees",null,"public",41,41,[41,28],41,null,3,8],["S","DatasetOverlap",null,"public",44,44,[44,59],49,null,-1,0],["S","DatasetCrosslink",null,"public",51,51,[51,61],65,null,-1,0],["v","agreeingFacts",null,"public",64,64,[64,50],64,[63,63],6,8],["S","DatasetDocumentMeta",null,"public",68,68,[68,64],82,[67,67],-1,0],["S","DatasetSpec",null,"public",84,84,[84,56],114,null,-1,0],["E","CodingKeys",null,"private",97,97,[97,47],97,null,9,8,[]],["i","init",["from"],"public",100,100,[100,46],113,[99,99],9,0],["S","DatasetNodeSummary",null,"public",116,116,[116,63],130,null,-1,0],["S","DatasetManifest",null,"public",132,132,[132,60],145,null,-1,0],["v","names",null,"public",144,144,[144,31],144,null,13,8],["E","DatasetError",null,"public",147,147,[147,68],159,null,-1,0,["notADataset","noSuchNode","noDatasetsRoot"]],["v","description",null,"public",152,152,[152,35],158,null,15,0]],"text":"//\n//  DatasetModel.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The records of a braid dataset as RaoLM's generator wrote them (the datasets on the\n//        T9): N Threads' corpora, each a persona writing about one world, the links where one\n//        Thread's entity is retold in another's words, and each document's place.\n//  PIN:  Read only, and open: kinds, voices and worlds are strings, so a dataset generated by\n//        any later RaoLM still loads. Only the link kinds are an enum, because the benches\n//        branch on them (a homonym shares a name, not facts).\n//\n\nimport Foundation\n\n/// How one Thread's entity reaches another Thread. None of them copies text.\npublic enum CrossKind: String, Codable, Sendable, CaseIterable {\n    case paraphrase, excerpt, summary, variant, homonym\n}\n\npublic struct DatasetDocumentRef: Codable, Sendable, Hashable {\n    public var node: String\n    public var documentID: String\n\n    public init(node: String, documentID: String) {\n        self.node = node\n        self.documentID = documentID\n    }\n}\n\n/// One fact both sides of a link state (the same kind; the same answer unless the link is a variant).\npublic struct DatasetSharedFact: Codable, Sendable, Equatable {\n    public var kind: String\n    public var sourceFact: String\n    public var targetFact: String\n    public var sourceAnswer: String\n    public var targetAnswer: String\n\n    public var agrees: Bool { sourceAnswer == targetAnswer }\n}\n\npublic struct DatasetOverlap: Codable, Sendable, Equatable {\n    public var sourceWords: Int\n    public var targetWords: Int\n    public var jaccard: Float\n    public var longestCommonRun: Int\n}\n\npublic struct DatasetCrosslink: Codable, Sendable, Equatable {\n    public var id: String\n    public var kind: CrossKind\n    public var subject: String\n    public var sourceType: String\n    public var targetType: String\n    public var source: DatasetDocumentRef\n    public var target: DatasetDocumentRef\n    /// Empty for a homonym.\n    public var facts: [DatasetSharedFact]\n    public var overlap: DatasetOverlap\n\n    /// Links whose two documents state the same facts with the same answers (told/source texts).\n    public var agreeingFacts: [DatasetSharedFact] { facts.filter(\\.agrees) }\n}\n\n/// One document's place in the dataset.\npublic struct DatasetDocumentMeta: Codable, Sendable, Equatable {\n    public var id: String\n    public var node: String\n    public var kind: String\n    public var entityType: String\n    public var subject: String\n    /// Whether the entity belongs to this Thread's own world (a homonym does).\n    public var home: Bool\n    /// The link this document is the target of, if any.\n    public var crosslink: String?\n    public var simulatedOrigin: String\n    public var synthetic: Bool\n    /// Where the document sits in feeding order, 0 to 1.\n    public var rank: Double\n}\n\npublic struct DatasetSpec: Codable, Sendable, Equatable {\n    public var name: String\n    public var seed: UInt64\n    public var perType: Int\n    public var paraphrase: Int\n    public var excerpt: Int\n    public var summary: Int\n    public var variant: Int\n    public var homonym: Int\n    public var nodes: Int\n    public var peers: Int\n    public var worlds: [String]?\n\n    private enum CodingKeys: String, CodingKey { case name, seed, perType, paraphrase, excerpt, summary, variant, homonym, nodes, peers, worlds }\n\n    /// Manifests written before v3 have no `nodes` or `peers`: three nodes, two peers.\n    public init(from decoder: Decoder) throws {\n        let c = try decoder.container(keyedBy: CodingKeys.self)\n        name = try c.decode(String.self, forKey: .name)\n        seed = try c.decode(UInt64.self, forKey: .seed)\n        perType = try c.decode(Int.self, forKey: .perType)\n        paraphrase = try c.decode(Int.self, forKey: .paraphrase)\n        excerpt = try c.decode(Int.self, forKey: .excerpt)\n        summary = try c.decode(Int.self, forKey: .summary)\n        variant = try c.decode(Int.self, forKey: .variant)\n        homonym = try c.decode(Int.self, forKey: .homonym)\n        nodes = try c.decodeIfPresent(Int.self, forKey: .nodes) ?? 3\n        peers = try c.decodeIfPresent(Int.self, forKey: .peers) ?? max(0, min(nodes - 1, 6))\n        worlds = try c.decodeIfPresent([String].self, forKey: .worlds)\n    }\n}\n\npublic struct DatasetNodeSummary: Codable, Sendable, Equatable {\n    public var name: String\n    public var documents: Int\n    public var home: Int\n    public var crossed: Int\n    public var homonyms: Int\n    public var partitions: Int\n    public var facts: Int\n    public var words: Int\n    public var corpusHash: String\n    public var origins: [String: Int]\n    public var persona: String?\n    public var world: String?\n    public var label: String?\n}\n\npublic struct DatasetManifest: Codable, Sendable, Equatable {\n    public var schemaVersion: Int\n    public var generator: String\n    public var generatorVersion: Int\n    public var spec: DatasetSpec\n    public var nodes: [DatasetNodeSummary]\n    /// Links per kind.\n    public var crosslinks: [String: Int]\n    /// SHA-256 over every node's corpus hash and every link, in order: names this dataset.\n    public var datasetHash: String\n\n    public static let fileName = \"manifest.json\"\n    public var names: [String] { nodes.map(\\.name) }\n}\n\npublic enum DatasetError: Error, CustomStringConvertible, Equatable {\n    case notADataset(String)\n    case noSuchNode(String, available: [String])\n    case noDatasetsRoot\n\n    public var description: String {\n        switch self {\n        case .notADataset(let path): return \"no dataset manifest.json in \\(path)\"\n        case .noSuchNode(let node, let available): return \"no node '\\(node)' in the dataset; it has \\(available.joined(separator: \", \"))\"\n        case .noDatasetsRoot: return \"no datasets root: set BRAID_DATASETS_DIR, or mount the T9\"\n        }\n    }\n}\n"},{"path":"Sources/BraidCore/Data/DatasetReader.swift","lines":91,"bytes":4812,"header":{"lines":[1,13],"what":[8,10],"pin":[11,12],"in":null,"out":null},"marks":[],"first":58,"scopes":[["S","BraidDataset",null,"public",17,17,[17,37],68,null,-1,0],["v","names",null,"public",25,25,[25,31],25,null,0,8],["f","corpus",["node"],"public",27,27,[27,63],30,null,0,0],["f","exists",["at"],"public static",32,32,[32,57],34,null,0,0],["f","nodeDirectory",["_","_"],"public static",36,36,[36,78],38,null,0,0],["f","load",["_"],"public static",40,40,[40,69],54,null,0,0],["f","hash",["corpusHashes","crosslinks"],"public static",57,57,[57,123],62,[56,56],0,0],["f","recomputedHash",[],"public",65,65,[65,50],67,[64,64],0,0],["E","DatasetsRoot",null,"public",72,72,[72,25],91,[70,71],-1,0,[]],["f","resolve",["environment","workArea","exists"],"public static",75,75,[76,116],83,null,8,0],["f","locate",["_","root"],"public static",86,86,[86,78],90,[85,85],8,0]],"text":"//\n//  DatasetReader.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: Loads a braid dataset directory: the manifest, every node's corpus in feeding order,\n//        each node's meta.jsonl and the crosslinks. Resolves a dataset by name in the datasets\n//        root, and a `dataset:<name or path>#<node>` source to one node's corpus.\n//  PIN:  The dataset hash is recomputed the way RaoLM defines it, so `verify` can tell a dataset\n//        that changed on disk from the one a Thread was fed.\n//\n\nimport Foundation\n\npublic struct BraidDataset: Sendable {\n    public var directory: URL\n    public var manifest: DatasetManifest\n    /// Per node, its corpus with documents in feeding order.\n    public var corpora: [String: GeneratedCorpus]\n    public var meta: [String: [DatasetDocumentMeta]]\n    public var crosslinks: [DatasetCrosslink]\n\n    public var names: [String] { manifest.names }\n\n    public func corpus(node: String) throws -> GeneratedCorpus {\n        guard let corpus = corpora[node] else { throw DatasetError.noSuchNode(node, available: names) }\n        return corpus\n    }\n\n    public static func exists(at directory: URL) -> Bool {\n        FileManager.default.fileExists(atPath: directory.appendingPathComponent(DatasetManifest.fileName).path)\n    }\n\n    public static func nodeDirectory(_ directory: URL, _ name: String) -> URL {\n        directory.appendingPathComponent(\"nodes\", isDirectory: true).appendingPathComponent(name, isDirectory: true)\n    }\n\n    public static func load(_ directory: URL) throws -> BraidDataset {\n        let manifestURL = directory.appendingPathComponent(DatasetManifest.fileName)\n        guard FileManager.default.fileExists(atPath: manifestURL.path) else { throw DatasetError.notADataset(directory.path) }\n        let manifest = try JSONCoding.read(DatasetManifest.self, from: manifestURL)\n        var corpora: [String: GeneratedCorpus] = [:]\n        var meta: [String: [DatasetDocumentMeta]] = [:]\n        for name in manifest.names {\n            let node = nodeDirectory(directory, name)\n            corpora[name] = try CorpusStore.load(node)\n            let metaURL = node.appendingPathComponent(\"meta.jsonl\")\n            meta[name] = FileManager.default.fileExists(atPath: metaURL.path) ? try JSONCoding.readLines(DatasetDocumentMeta.self, from: metaURL) : []\n        }\n        let links = try JSONCoding.readLines(DatasetCrosslink.self, from: directory.appendingPathComponent(\"crosslinks.jsonl\"))\n        return BraidDataset(directory: directory, manifest: manifest, corpora: corpora, meta: meta, crosslinks: links)\n    }\n\n    /// SHA-256 over every node's corpus hash and every link, in order (RaoLM's definition).\n    public static func hash(corpusHashes: [(name: String, hash: String)], crosslinks: [DatasetCrosslink]) throws -> String {\n        let encoder = JSONCoding.lineEncoder()\n        var lines = corpusHashes.map { \"\\($0.name)\\t\\($0.hash)\" }\n        for link in crosslinks { lines.append(String(decoding: try encoder.encode(link), as: UTF8.self)) }\n        return ContentHash.sha256Hex(lines.joined(separator: \"\\n\"))\n    }\n\n    /// The hash of the dataset as it is now on disk (its corpora recomputed from their documents).\n    public func recomputedHash() throws -> String {\n        try Self.hash(corpusHashes: names.map { ($0, corpora[$0]?.recomputedCorpusHash ?? \"\") }, crosslinks: crosslinks)\n    }\n}\n\n/// Where datasets live: `BRAID_DATASETS_DIR`, else the work area's `datasets/`, else RaoLM's\n/// datasets on the T9 (the ones the benches were designed on).\npublic enum DatasetsRoot {\n    public static let raolmDatasets = URL(fileURLWithPath: \"/Volumes/T9/rao/projects/raolm/datasets\", isDirectory: true)\n\n    public static func resolve(environment: [String: String] = ProcessInfo.processInfo.environment, workArea: URL?,\n                               exists: (URL) -> Bool = { FileManager.default.fileExists(atPath: $0.path) }) -> URL? {\n        if let override = environment[\"BRAID_DATASETS_DIR\"], !override.isEmpty { return URL(fileURLWithPath: override, isDirectory: true) }\n        if let workArea {\n            let own = workArea.appendingPathComponent(\"datasets\", isDirectory: true)\n            if exists(own) { return own }\n        }\n        return exists(raolmDatasets) ? raolmDatasets : nil\n    }\n\n    /// `braid-n3` → `<root>/braid-n3`; a path (containing `/`) is taken as it is.\n    public static func locate(_ nameOrPath: String, root: URL?) throws -> URL {\n        if nameOrPath.contains(\"/\") || nameOrPath.hasPrefix(\"~\") { return URL(fileURLWithPath: (nameOrPath as NSString).expandingTildeInPath, isDirectory: true) }\n        guard let root else { throw DatasetError.noDatasetsRoot }\n        return root.appendingPathComponent(nameOrPath, isDirectory: true)\n    }\n}\n"},{"path":"Sources/BraidCore/Mixture/Gate/Gate.swift","lines":208,"bytes":9948,"header":{"lines":[1,15],"what":[8,10],"pin":[11,14],"in":null,"out":null},"marks":[],"first":69,"scopes":[["S","GateState",null,"public",20,20,[20,54],52,[19,19],-1,0],["i","init",["strands","commons","prior"],"public",31,31,[31,72],42,null,0,0],["v","count",null,"public",44,44,[44,26],44,null,0,8],["v","leader",null,"public",47,47,[47,27],51,[46,46],0,0],["E","Gate",null,"public",54,54,[54,17],197,null,-1,0,[]],["f","floor",["_","strands"],"public static",57,57,[57,74],57,[55,56],4,8],["f","observe",["_","likelihoods","module","settings"],"public static",63,64,[64,141],110,[59,62],4,0],["f","weights",["_"],"public static",113,113,[113,63],113,[112,112],4,8],["f","shadowWeights",["_","traces","beta"],"public static",117,117,[117,101],124,[115,116],4,0],["f","open",["_","commons","floor"],"public static",128,128,[128,87],134,[126,127],4,0],["f","renormalised",["_","open"],"public static",137,137,[137,81],144,[136,136],4,0],["f","entropy",["_"],"public static",147,147,[147,62],151,[146,146],4,0],["f","attach",["_"],"public static",155,155,[155,56],176,[153,154],4,0],["f","detach",["_","at"],"public static",180,180,[180,71],196,[178,179],4,0],["X","GateState",null,"",199,199,[199,20],208,null,-1,0],["i","init",["memoryOnly","commons"],"",201,201,[201,53],207,[200,200],14,0]],"text":"//\n//  Gate.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The live gate: a memory over strands moved by bounded evidence at prompt positions,\n//        read as the gate weights; the open set; the renormalisation over open strands; attach\n//        and detach; and the shadow β4 counterfactual the owner asked to log beside it.\n//  PIN:  RaoLM's `observe`/`observeLift` arithmetic, exactly, in Double. One clamp: the module's\n//        evidence (step 7) enters the log-evidence before it, so nothing moves a token past\n//        ceiling/floor. Trace never enters the live gate; the shadow is computed from the same\n//        memory and the traces and is recorded, never applied.\n//\n\nimport Foundation\n\n/// What the gate remembers of a text: which strand has been predicting it, and how much.\npublic struct GateState: Codable, Sendable, Equatable {\n    /// Sums to 1.\n    public var memory: [Double]\n    /// Per strand, how much of the recent text it predicted (0 none, 1 all).\n    public var credibility: [Double]\n    public var seen: Int\n    public var predicted: [Int]\n    /// The commons strand's index, when the braid has one: the memory starts on it and every other\n    /// strand's evidence is its lift over it.\n    public var commons: Int?\n\n    public init(strands: Int, commons: Int? = nil, prior: Double = 0.9) {\n        let n = max(0, strands)\n        memory = [Double](repeating: n > 0 ? 1 / Double(n) : 0, count: n)\n        credibility = [Double](repeating: 0, count: n)\n        seen = 0\n        predicted = [Int](repeating: 0, count: n)\n        if let commons, (0..<n).contains(commons) {\n            self.commons = commons\n            let p = n > 1 ? min(max(prior, 0), 1) : 1\n            memory = (0..<n).map { $0 == commons ? p : (1 - p) / Double(n - 1) }\n        }\n    }\n\n    public var count: Int { memory.count }\n\n    /// The strand with the most memory; the first of equals.\n    public var leader: Int {\n        var best = 0\n        for t in memory.indices where memory[t] > memory[best] { best = t }\n        return best\n    }\n}\n\npublic enum Gate {\n    /// The floor a strand's gate must reach to be mixed in: `openFloor` is what two strands use,\n    /// and it shrinks as strands are added so an even gate stays above it.\n    public static func floor(_ openFloor: Double, strands: Int) -> Double { openFloor * 2 / Double(max(2, strands)) }\n\n    /// One prompt (or context) token was fixed; `likelihoods[t]` is what strand t alone gave it\n    /// (its retrieval lower bound when it was not asked). `module[t]` is the trajectory module's\n    /// e_t ∈ [−1, 1] for the strand, nil before step 7. Returns the bounded evidence ρ̃_t that\n    /// entered, for the record.\n    @discardableResult\n    public static func observe(_ state: inout GateState, likelihoods: [Double], module: [Double]? = nil, settings: GateSettings) -> [Double] {\n        let n = state.memory.count\n        guard n > 0, likelihoods.count == n else { return [] }\n        let floorValue = max(settings.evidenceFloor, 1e-6)\n        let reach = settings.reach\n        let span = log(reach)\n        let gains: [Double]\n        let losses: [Double]\n        let ratios: [Double]\n        if let c = state.commons, settings.evidence == .lift {\n            let base = max(likelihoods[c], 1e-12)\n            ratios = (0..<n).map { t -> Double in\n                guard t != c else { return 1 }\n                var evidence = log(max(likelihoods[t], 1e-300) / base)\n                // The module's e_t enters only when κ > 0 (it is logged whatever κ is).\n                if settings.moduleGain > 0, let module, module.indices.contains(t) { evidence += settings.moduleGain * min(max(module[t], -1), 1) * span }\n                return exp(min(max(evidence, -span), span))\n            }\n            gains = ratios.map { max(0, log($0)) / span }\n            losses = ratios.map { max(0, -log($0)) / span }\n        } else {\n            // Absolute evidence: the probability between the floor and the ceiling; 0 loss = predicted.\n            let ceiling = max(settings.evidenceCeiling, floorValue)\n            let hits = likelihoods.map { min(max($0, floorValue), ceiling) }\n            ratios = hits.map { $0 / ceiling }\n            losses = hits.map { span > 0 ? log(ceiling / $0) / span : 0 }\n            gains = losses.map { 1 - $0 }\n        }\n        state.seen += 1\n        for t in 0..<n where likelihoods[t] >= floorValue { state.predicted[t] += 1 }\n        let rate = min(max(settings.credibilityRate, 0), 1)\n        for t in 0..<n { state.credibility[t] = (1 - rate) * state.credibility[t] + rate * gains[t] }\n        guard n > 1 else {\n            state.memory = [1]\n            return ratios\n        }\n        let others = (0..<n).filter { $0 != state.commons }\n        let weight = (settings.evidence == .lift && state.commons != nil ? others : Array(0..<n)).map { state.credibility[$0] }.max() ?? 0\n        var updated = (0..<n).map { state.memory[$0] * pow(ratios[$0], weight) }\n        let total = updated.reduce(0, +)\n        updated = total > 0 ? updated.map { $0 / total } : state.memory\n        let alpha = min(max(settings.shareRate, 0), 1)\n        let given = (0..<n).map { updated[$0] * (1 - pow(1 - alpha, losses[$0])) }\n        let pool = given.reduce(0, +)\n        state.memory = (0..<n).map { updated[$0] - given[$0] + (pool - given[$0]) / Double(n - 1) }\n        return ratios\n    }\n\n    /// The live gate weights: the memory.\n    public static func weights(_ state: GateState) -> [Double] { state.memory }\n\n    /// The shadow β4 counterfactual: the memory multiplied by exp(β·(trace_t − mean trace)) and\n    /// renormalised. Logged beside the live gate; never applied.\n    public static func shadowWeights(_ state: GateState, traces: [Double], beta: Double) -> [Double] {\n        let memory = state.memory\n        guard !memory.isEmpty, traces.count == memory.count else { return memory }\n        let mean = traces.reduce(0, +) / Double(traces.count)\n        let gates = memory.indices.map { memory[$0] * exp(beta * (traces[$0] - mean)) }\n        let total = gates.reduce(0, +)\n        return total > 0 ? gates.map { $0 / total } : memory\n    }\n\n    /// Which strands are mixed in: those at the floor, the largest always, the commons always;\n    /// everyone when every gate is 0.\n    public static func open(_ gates: [Double], commons: Int?, floor: Double) -> [Bool] {\n        guard !gates.isEmpty else { return [] }\n        if gates.allSatisfy({ $0 <= 0 }) { return gates.map { _ in true } }\n        var best = 0\n        for t in gates.indices where gates[t] > gates[best] { best = t }\n        return gates.indices.map { t in t == best || t == commons || (gates[t] >= floor && gates[t] > 0) }\n    }\n\n    /// w′_t = g_t/Σ_open g; 0 when closed; even over the open strands when their gates sum to 0.\n    public static func renormalised(_ gates: [Double], open: [Bool]) -> [Double] {\n        let total = gates.indices.reduce(0.0) { $0 + (open[$1] ? gates[$1] : 0) }\n        let count = Double(open.filter { $0 }.count)\n        return gates.indices.map { t in\n            guard open[t] else { return 0 }\n            return total > 0 ? gates[t] / total : 1 / max(count, 1)\n        }\n    }\n\n    /// Entropy of a weight vector (the gate's entropy is a derived view).\n    public static func entropy(_ weights: [Double]) -> Double {\n        var h = 0.0\n        for w in weights where w > 0 { h -= w * log(w) }\n        return h\n    }\n\n    /// A strand joins at the end: it takes 1/(k+1) of the Threads' memory mass, pro-rata from\n    /// each Thread (the commons keeps its own), with no credibility yet. Σ memory stays 1.\n    public static func attach(_ state: inout GateState) {\n        let n = state.count\n        let threads = (0..<n).filter { $0 != state.commons }\n        let threadMass = threads.reduce(0.0) { $0 + state.memory[$1] }\n        let k = Double(threads.count)\n        var memory = state.memory\n        let newcomer: Double\n        if k > 0 {\n            newcomer = threadMass / (k + 1)\n            for t in threads { memory[t] *= k / (k + 1) }\n        } else if let c = state.commons {\n            // Only the commons so far: the newcomer takes what a Thread would start with.\n            newcomer = min(max(1 - 0.9, 0), memory[c])\n            memory[c] -= newcomer\n        } else {\n            newcomer = 1\n        }\n        memory.append(newcomer)\n        state.memory = memory\n        state.credibility.append(0)\n        state.predicted.append(0)\n    }\n\n    /// A strand leaves: its memory goes pro-rata to the remaining Threads (to the commons when\n    /// none remain). Indices above it shift down.\n    public static func detach(_ state: inout GateState, at index: Int) {\n        guard state.memory.indices.contains(index), index != state.commons else { return }\n        let leaving = state.memory[index]\n        state.memory.remove(at: index)\n        state.credibility.remove(at: index)\n        state.predicted.remove(at: index)\n        if let c = state.commons, c > index { state.commons = c - 1 }\n        let threads = state.memory.indices.filter { $0 != state.commons }\n        let threadMass = threads.reduce(0.0) { $0 + state.memory[$1] }\n        if threadMass > 0 {\n            for t in threads { state.memory[t] += leaving * state.memory[t] / threadMass }\n        } else if let c = state.commons {\n            state.memory[c] += leaving\n        } else if !threads.isEmpty {\n            for t in threads { state.memory[t] += leaving / Double(threads.count) }\n        }\n    }\n}\n\nextension GateState {\n    /// A state holding only a memory (for recomputing views from a logged memory).\n    init(memoryOnly memory: [Double], commons: Int?) {\n        self.memory = memory\n        credibility = [Double](repeating: 0, count: memory.count)\n        seen = 0\n        predicted = [Int](repeating: 0, count: memory.count)\n        self.commons = commons\n    }\n}\n"},{"path":"Sources/BraidCore/Mixture/Gate/GateSettings.swift","lines":49,"bytes":2044,"header":{"lines":[1,17],"what":[8,14],"pin":[15,16],"in":null,"out":null},"marks":[],"first":85,"scopes":[["S","GateSettings",null,"public",21,21,[21,57],49,null,-1,0],["E","Evidence",null,"public",22,22,[22,52],27,null,0,0,["lift","absolute"]],["i","init",[],"public",39,39,[39,18],39,null,0,8],["v","reach",null,"public",42,42,[42,29],42,[41,41],0,8],["v","fingerprint",null,"public",45,45,[45,35],48,[44,44],0,0]],"text":"//\n//  GateSettings.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The gate's constants, carried from RaoLM's braided gate: evidence bounded between the\n//        floor and the ceiling (one token moves the memory by at most ceiling/floor = 10 to 1),\n//        credibility that fades at 0.3 a token, a tenth given up on a token predicted worse than\n//        the commons, the memory starting 0.9 on the commons, an open floor of 0.05 for two\n//        strands that shrinks as strands are added. `moduleGain` κ is the trajectory module's\n//        entry (0 until step 7); `shadowBeta` is the β of the counterfactual trace gate, logged\n//        and never applied.\n//  PIN:  The fingerprint names the settings in every session header and generation id, so a log\n//        says which gate made it.\n//\n\nimport Foundation\n\npublic struct GateSettings: Codable, Sendable, Equatable {\n    public enum Evidence: String, Codable, Sendable {\n        /// A strand's evidence for a token is its probability over the commons' (the default).\n        case lift\n        /// Without a commons: the probability itself, clamped (RaoLM's gate before the commons).\n        case absolute\n    }\n\n    public var evidenceFloor: Double = 0.05\n    public var evidenceCeiling: Double = 0.5\n    public var shareRate: Double = 0.1\n    public var credibilityRate: Double = 0.3\n    public var commonsPrior: Double = 0.9\n    public var openFloor: Double = 0.05\n    public var moduleGain: Double = 0\n    public var shadowBeta: Double = 4\n    public var evidence: Evidence = .lift\n\n    public init() {}\n\n    /// ceiling/floor: how far one token can move the memory.\n    public var reach: Double { max(evidenceCeiling / max(evidenceFloor, 1e-6), 1 + 1e-6) }\n\n    /// The first 8 hex of the SHA-256 of the sorted-key JSON: the settings' name.\n    public var fingerprint: String {\n        let data = (try? JSONCoding.lineEncoder().encode(self)) ?? Data()\n        return String(ContentHash.sha256Hex(data).prefix(8))\n    }\n}\n"},{"path":"Sources/BraidCore/Mixture/Mixer/Mixer.swift","lines":221,"bytes":10778,"header":{"lines":[1,14],"what":[8,10],"pin":[11,13],"in":null,"out":null},"marks":[],"first":90,"scopes":[["S","Expert",null,"public",19,19,[19,31],55,[18,18],-1,0],["i","init",["hits","tau","logits","lambda"],"public",29,29,[29,76],37,null,0,0],["f","probability",["of"],"public",40,40,[40,54],43,[39,39],0,0],["f","lowerBound",["of"],"public",46,46,[46,52],46,[45,45],0,8],["v","bestScore",null,"public",48,48,[48,33],48,null,0,8],["v","knnEntropy",null,"public",51,51,[51,34],51,[50,50],0,8],["v","lmEntropy",null,"public",54,54,[54,34],54,[53,53],0,8],["S","Mixture",null,"public",58,58,[58,32],67,[57,57],-1,0],["E","Mixer",null,"public",69,69,[69,18],221,null,-1,0,[]],["f","weights",["_","tau"],"public static",71,71,[71,76],77,[70,70],8,0],["f","softmax",["_","temperature"],"public static",80,80,[80,87],91,[79,79],8,0],["f","entropy",["_"],"public static",93,93,[93,100],97,null,8,0],["f","mix",["experts","gates","open","vocabulary"],"public static",101,101,[101,105],123,[99,100],8,0],["f","argmax",["_"],"public static",128,128,[128,57],132,null,8,0],["f","choose",["_","age"],"public static",137,137,[137,79],148,[134,136],8,0],["f","citedAge",["_","experts","mixture","createdAt"],"public static",152,152,[152,128],161,[150,151],8,0],["f","sample",["_","topK","rng"],"public static",164,164,[164,91],178,[163,163],8,0],["f","shares",["_","experts","token"],"public static",181,181,[181,93],188,[180,180],8,0],["f","candidates",["_","experts","count"],"public static",191,191,[191,138],206,[190,190],8,0],["f","mixtureEntropyBounds",["reedWeights","knnWeights","lambda","hlm","hknn"],"public static",211,211,[211,171],220,[208,210],8,0]],"text":"//\n//  Mixer.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: Each strand as its own kNN-LM at one position (softmax(score/τ_t) over its own hits, its\n//        reed's distribution), the mixture over the open strands, the choice (the near-tie rule),\n//        the exact shares, the candidates, and the retrieval entropy.\n//  PIN:  Every number that chooses a token or sets a share is Double on the CPU, as RaoLM's are;\n//        no score is ever compared across two strands' key spaces. share_t = w′_t·p_t(y)/p(y);\n//        a token's shares sum to 1.\n//\n\nimport Foundation\n\n/// One strand's own kNN-LM at one position.\npublic struct Expert: Sendable {\n    public var hits: [Hit]\n    /// softmax(score/τ_t) over this strand's own hits.\n    public var weights: [Double]\n    public var knn: [Int: Double]\n    /// The reed's distribution from this strand's normed state; nil when it was not asked.\n    public var plm: [Double]?\n    /// λ_t: the request's λ scaled by the strand's own; 0 for the commons.\n    public var lambda: Double\n\n    public init(hits: [Hit], tau: Double, logits: [Float]?, lambda: Double) {\n        self.hits = hits\n        weights = Mixer.weights(hits.map { Double($0.score) }, tau: tau)\n        var knn: [Int: Double] = [:]\n        for (i, hit) in hits.enumerated() { knn[Int(hit.value), default: 0] += weights[i] }\n        self.knn = knn\n        plm = logits.map { Mixer.softmax($0) }\n        self.lambda = min(max(lambda, 0), 1)\n    }\n\n    /// p_t(y) = λ_t·p_knn,t(y) + (1−λ_t)·p_lm,t(y); nil without the reed.\n    public func probability(of token: Int) -> Double? {\n        guard let plm else { return nil }\n        return lambda * (knn[token] ?? 0) + (1 - lambda) * (token < plm.count ? plm[token] : 0)\n    }\n\n    /// What retrieval alone guarantees of p_t(y), for a strand whose reed was not asked.\n    public func lowerBound(of token: Int) -> Double { lambda * (knn[token] ?? 0) }\n\n    public var bestScore: Float? { hits.map(\\.score).max() }\n\n    /// H(p_knn,t): the entropy of the strand's retrieval distribution over tokens (≤ ln k).\n    public var knnEntropy: Double { Mixer.entropy(knn.values) }\n\n    /// H(p_lm,t) on the CPU; nil when not asked. The GPU path (BraidKit) may supply it instead.\n    public var lmEntropy: Double? { plm.map { Mixer.entropy($0) } }\n}\n\n/// The mixture at one position.\npublic struct Mixture: Sendable {\n    /// w′: the gate renormalised over the open, asked strands (0 elsewhere).\n    public var weights: [Double]\n    public var open: [Bool]\n    public var mixed: [Double]\n    /// Σ_t w′_t·λ_t.\n    public var lambda: Double\n    public var reedWeights: [Double]\n    public var knnWeights: [Double]\n}\n\npublic enum Mixer {\n    /// softmax(score/τ) over a strand's hits, τ floored at 1e-4.\n    public static func weights(_ scores: [Double], tau: Double) -> [Double] {\n        guard let top = scores.max() else { return [] }\n        let t = max(tau, 1e-4)\n        let exps = scores.map { exp(($0 - top) / t) }\n        let total = exps.reduce(0, +)\n        return exps.map { $0 / total }\n    }\n\n    /// Numerically stable softmax of logits / temperature (temperature ≤ 0 means 1), in Double.\n    public static func softmax(_ logits: [Float], temperature: Double = 1) -> [Double] {\n        let t = temperature > 0 ? temperature : 1\n        guard let top = logits.max() else { return [] }\n        var exps = [Double](repeating: 0, count: logits.count)\n        var total = 0.0\n        for i in logits.indices {\n            let e = exp((Double(logits[i]) - Double(top)) / t)\n            exps[i] = e\n            total += e\n        }\n        return exps.map { $0 / total }\n    }\n\n    public static func entropy<S: Sequence>(_ probabilities: S) -> Double where S.Element == Double {\n        var h = 0.0\n        for p in probabilities where p > 0 { h -= p * log(p) }\n        return h\n    }\n\n    /// p = Σ_t w′_t·(λ_t·p_knn,t + (1−λ_t)·p_lm,t) over the open strands with a reed, w′ the gate\n    /// renormalised over them. Written as (1−λ̄)·Σ reedW·p_lm + λ̄·Σ knnW·p_knn, which is the same sum.\n    public static func mix(experts: [Expert], gates: [Double], open: [Bool], vocabulary: Int) -> Mixture {\n        let usable = experts.indices.map { open[$0] && experts[$0].plm != nil }\n        let weights = Gate.renormalised(gates, open: usable)\n        let active = experts.indices.filter { weights[$0] > 0 }\n        var l = 0.0\n        var reedWeights = weights\n        var knnWeights = weights\n        if let first = active.first, active.allSatisfy({ experts[$0].lambda == experts[first].lambda }) {\n            l = experts[first].lambda\n        } else if !active.isEmpty {\n            l = min(max(active.reduce(0.0) { $0 + weights[$1] * experts[$1].lambda }, 0), 1)\n            reedWeights = experts.indices.map { t in l < 1 && weights[t] > 0 ? weights[t] * (1 - experts[t].lambda) / (1 - l) : 0 }\n            knnWeights = experts.indices.map { t in l > 0 && weights[t] > 0 ? weights[t] * experts[t].lambda / l : 0 }\n        }\n        var mixed = [Double](repeating: 0, count: vocabulary)\n        for t in active {\n            let h = reedWeights[t] * (1 - l)\n            if h > 0, let p = experts[t].plm { for i in 0..<min(p.count, vocabulary) { mixed[i] += h * p[i] } }\n            let q = knnWeights[t] * l\n            if q > 0 { for (token, value) in experts[t].knn where token >= 0 && token < vocabulary { mixed[token] += q * value } }\n        }\n        return Mixture(weights: weights, open: usable, mixed: mixed, lambda: l, reedWeights: reedWeights, knnWeights: knnWeights)\n    }\n\n    /// Two tokens whose probabilities are within this fraction of the larger are tied.\n    public static let tieBand = 1e-6\n\n    public static func argmax(_ values: [Double]) -> Int {\n        var best = 0\n        for i in values.indices where values[i] > values[best] { best = i }\n        return best\n    }\n\n    /// The likeliest token, except at a near-tie: among the tokens within `tieBand` of the\n    /// likeliest, the one whose cited text is oldest wins (`age`: smaller is older; nil counts as\n    /// newest), then the lower token id. With no near-tie this is `argmax`, exactly.\n    public static func choose(_ values: [Double], age: (Int) -> Int64?) -> Int {\n        let top = argmax(values)\n        guard top < values.count, values[top] > 0 else { return top }\n        let floor = values[top] - values[top] * tieBand\n        var tied: [Int] = []\n        for (token, value) in values.enumerated() where value >= floor { tied.append(token) }\n        guard tied.count > 1 else { return top }\n        return tied.min { a, b in\n            let (ageA, ageB) = (age(a) ?? .max, age(b) ?? .max)\n            return ageA != ageB ? ageA < ageB : a < b\n        } ?? top\n    }\n\n    /// The creation time of the text a token would be cited to: of the hits that predicted it,\n    /// the heaviest one's partition.\n    public static func citedAge(_ token: Int, experts: [Expert], mixture: Mixture, createdAt: (Int, Int32) -> Int64?) -> Int64? {\n        var best: (weight: Double, strand: Int, row: Int32)?\n        for t in experts.indices where mixture.weights[t] > 0 {\n            for (i, hit) in experts[t].hits.enumerated() where Int(hit.value) == token {\n                let weight = mixture.weights[t] * experts[t].weights[i]\n                if best == nil || weight > best!.weight { best = (weight, t, hit.row) }\n            }\n        }\n        return best.flatMap { createdAt($0.strand, $0.row) }\n    }\n\n    /// A sample from a tempered distribution, top-k (0 = all), with the shared generator.\n    public static func sample(_ values: [Double], topK: Int, rng: inout SplitMix64) -> Int {\n        var candidates = values.indices.filter { values[$0] > 0 }\n        if topK > 0, candidates.count > topK {\n            candidates.sort { values[$0] > values[$1] }\n            candidates = Array(candidates.prefix(topK))\n        }\n        let total = candidates.reduce(0.0) { $0 + values[$1] }\n        guard total > 0, let last = candidates.last else { return argmax(values) }\n        var draw = Double(rng.next() >> 11) / Double(1 << 53) * total\n        for token in candidates {\n            draw -= values[token]\n            if draw <= 0 { return token }\n        }\n        return last\n    }\n\n    /// share_t(y) = w′_t·p_t(y)/p(y): what each strand supplied to the token. Sums to 1.\n    public static func shares(_ mixture: Mixture, experts: [Expert], token: Int) -> [Double] {\n        let total = token < mixture.mixed.count ? mixture.mixed[token] : 0\n        let parts = experts.indices.map { t -> Double in\n            guard mixture.weights[t] > 0, let p = experts[t].probability(of: token) else { return 0 }\n            return mixture.weights[t] * p\n        }\n        return experts.indices.map { t in total > 0 ? parts[t] / total : mixture.weights[t] }\n    }\n\n    /// The mixture's `count` likeliest tokens, each split by strand as a chosen token is.\n    public static func candidates(_ mixture: Mixture, experts: [Expert], count: Int = 3) -> [(token: Int, prob: Double, parts: [Double])] {\n        var top: [(token: Int, prob: Double)] = []\n        for (token, prob) in mixture.mixed.enumerated() where prob > 0 {\n            guard top.count < count || prob > (top.last?.prob ?? 0) else { continue }\n            let at = top.firstIndex { prob > $0.prob } ?? top.count\n            top.insert((token, prob), at: at)\n            if top.count > count { top.removeLast() }\n        }\n        return top.map { candidate in\n            let parts = experts.indices.map { t -> Double in\n                guard mixture.weights[t] > 0, let p = experts[t].probability(of: candidate.token) else { return 0 }\n                return mixture.weights[t] * p / candidate.prob\n            }\n            return (candidate.token, candidate.prob, parts)\n        }\n    }\n\n    /// Bounds on the mixture's entropy from the two stored entropies and the weights: a derived\n    /// view, exact only on replay. lower = λ̄·Σ knnW·H_knn + (1−λ̄)·Σ reedW·H_lm;\n    /// upper = lower + λ̄·H(knnW) + (1−λ̄)·H(reedW) + H_b(λ̄).\n    public static func mixtureEntropyBounds(reedWeights: [Double], knnWeights: [Double], lambda: Double, hlm: [Double?], hknn: [Double]) -> (lower: Double, upper: Double) {\n        var lower = 0.0\n        for t in reedWeights.indices {\n            if let h = hlm[t] { lower += (1 - lambda) * reedWeights[t] * h }\n            lower += lambda * knnWeights[t] * hknn[t]\n        }\n        let hb = lambda > 0 && lambda < 1 ? -(lambda * log(lambda) + (1 - lambda) * log(1 - lambda)) : 0\n        let upper = lower + lambda * entropy(knnWeights) + (1 - lambda) * entropy(reedWeights) + hb\n        return (lower, upper)\n    }\n}\n"},{"path":"Sources/BraidCore/Mixture/Trace/TraceAudit.swift","lines":36,"bytes":1536,"header":{"lines":[1,10],"what":[8,9],"pin":null,"in":null,"out":null},"marks":[],"first":110,"scopes":[["E","TraceAudit",null,"public",15,15,[15,23],36,[14,14],-1,0,[]],["f","wireLengths",["tokens","hits","documentOfRow"],"public static",19,19,[19,108],35,[16,18],0,0]],"text":"//\n//  TraceAudit.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: What can be checked of a trace from the log alone: per position, the longest chain of\n//        logged hits that follow one another through one document. The trace bench reads it.\n//\n\nimport Foundation\n\n/// What can be checked from the log alone.\npublic enum TraceAudit {\n    /// Per position, the longest chain of hits that follow one another through one document:\n    /// entry e at one position, e + 1 at the next, each expecting the token that came. Not a bound\n    /// on a node's chain either way (it follows hits of any rank and never bridges).\n    public static func wireLengths(tokens: [Int32], hits: [[Hit]], documentOfRow: [Int32: String]) -> [Int] {\n        var lengths: [Int] = []\n        var chains: [Int32: Int] = [:]\n        for j in hits.indices {\n            var next: [Int32: Int] = [:]\n            if j > 0 {\n                for hit in hits[j - 1] where hit.value == tokens[j] {\n                    let before = hits.indices.contains(j - 2) ? hits[j - 2].first { $0.entry == hit.entry - 1 } : nil\n                    let same = before.map { documentOfRow[$0.row] != nil && documentOfRow[$0.row] == documentOfRow[hit.row] } ?? false\n                    next[hit.entry] = max(next[hit.entry] ?? 0, (same ? chains[hit.entry - 1] ?? 0 : 0) + 1)\n                }\n            }\n            chains = next\n            lengths.append(chains.values.max() ?? 0)\n        }\n        return lengths\n    }\n}\n"},{"path":"Sources/BraidCore/Mixture/Trace/TraceCorpus.swift","lines":76,"bytes":3569,"header":{"lines":[1,12],"what":[8,10],"pin":[11,11],"in":null,"out":null},"marks":[],"first":112,"scopes":[["S","TraceCorpus",null,"public",16,16,[16,36],76,null,-1,0],["i","init",["values","keyRow","keyOffset","partitions","breakLength"],"public",29,29,[29,120],61,null,0,0],["v","count",null,"public",63,63,[63,26],63,null,0,8],["f","successor",["of"],"public",66,66,[66,49],70,[65,65],0,0],["f","position",["of"],"public",72,72,[72,57],72,null,0,8],["f","samePartition",["_","_"],"public",75,75,[75,58],75,[74,74],0,8]],"text":"//\n//  TraceCorpus.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: Where each index entry sits in its document: what the tracker needs of a node's index.\n//        Built from the index's values, key rows and offsets and its partition table, with the\n//        break tokens between partitions counted so positions run on across a break.\n//  PIN:  Pure: no tensors. The successor of an entry is the next position of the same document.\n//\n\nimport Foundation\n\npublic struct TraceCorpus: Sendable {\n    /// Per entry: the token that followed its context (the index's value), where its context sits.\n    public let values: [Int32]\n    public let keyRow: [Int32]\n    public let keyOffset: [Int32]\n    /// Per entry: its document's ordinal and its context's token index in that document.\n    public let documents: [Int32]\n    public let positions: [Int32]\n    /// Per document ordinal: its tokens, the sum of its partitions' token counts and the breaks between.\n    public let lengths: [Int32]\n    /// Per row: the partition's own token count (a position past it is a break token).\n    public let rowTokenCount: [Int: Int]\n\n    public init(values: [Int32], keyRow: [Int32], keyOffset: [Int32], partitions: [PartitionRef], breakLength: Int = 0) {\n        precondition(values.count == keyRow.count && values.count == keyOffset.count)\n        var ordinal: [String: Int32] = [:]\n        var byDocument: [String: [PartitionRef]] = [:]\n        for partition in partitions {\n            if ordinal[partition.documentID] == nil { ordinal[partition.documentID] = Int32(ordinal.count) }\n            byDocument[partition.documentID, default: []].append(partition)\n        }\n        var rowDocument: [Int: Int32] = [:]\n        var rowStart: [Int: Int32] = [:]\n        var rowTokenCount: [Int: Int] = [:]\n        var lengths = [Int32](repeating: 0, count: ordinal.count)\n        for (documentID, rows) in byDocument {\n            let document = ordinal[documentID]!\n            var start: Int32 = 0\n            let ordered = rows.sorted { $0.partitionIndex < $1.partitionIndex }\n            for (n, partition) in ordered.enumerated() {\n                rowDocument[partition.row] = document\n                rowStart[partition.row] = start\n                rowTokenCount[partition.row] = partition.tokenCount\n                start += Int32(partition.tokenCount)\n                if n < ordered.count - 1 { start += Int32(breakLength) }\n            }\n            lengths[Int(document)] = start\n        }\n        self.values = values\n        self.keyRow = keyRow\n        self.keyOffset = keyOffset\n        documents = keyRow.map { rowDocument[Int($0)] ?? -1 }\n        positions = zip(keyRow, keyOffset).map { row, offset in (rowStart[Int(row)] ?? 0) + offset }\n        self.lengths = lengths\n        self.rowTokenCount = rowTokenCount\n    }\n\n    public var count: Int { values.count }\n\n    /// The entry of the next position of the same document, if the index holds it.\n    public func successor(of entry: Int) -> Int? {\n        let next = entry + 1\n        guard entry >= 0, next < count, documents[next] == documents[entry], documents[entry] >= 0, positions[next] == positions[entry] + 1 else { return nil }\n        return next\n    }\n\n    public func position(of entry: Int) -> TokenPosition { TokenPosition(row: Int(keyRow[entry]), offset: Int(keyOffset[entry])) }\n\n    /// Whether two entries sit in the same partition (the partition-bounded run).\n    public func samePartition(_ a: Int, _ b: Int) -> Bool { keyRow[a] == keyRow[b] }\n}\n"},{"path":"Sources/BraidCore/Mixture/Trace/TraceRule.swift","lines":32,"bytes":1022,"header":{"lines":[1,12],"what":[8,11],"pin":null,"in":null,"out":null},"marks":[],"first":118,"scopes":[["S","TraceRule",null,"public",16,16,[16,54],32,null,-1,0],["i","init",[],"public",23,23,[23,18],23,null,0,8],["f","trace",["length"],"public",28,28,[28,44],31,[27,27],0,0]],"text":"//\n//  TraceRule.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The trace's constants, in tokens or steps: a chain of `phrase` tokens or fewer traces 0\n//        (longer than 95% of the datasets' sentences), a chain of `arc` traces 1 (about half a\n//        document), a bridge skips at most `bridge` tokens, `heads` chains are kept and `seeds`\n//        hits may start one at each step. RaoLM's numbers, fixed before any numbers.\n//\n\nimport Foundation\n\npublic struct TraceRule: Codable, Sendable, Equatable {\n    public var phrase = 24\n    public var arc = 96\n    public var bridge = 8\n    public var heads = 8\n    public var seeds = 4\n\n    public init() {}\n\n    public static let standard = TraceRule()\n\n    /// clamp((length − phrase) / (arc − phrase), 0, 1).\n    public func trace(length: Int) -> Float {\n        guard arc > phrase else { return length > phrase ? 1 : 0 }\n        return min(max(Float(length - phrase) / Float(arc - phrase), 0), 1)\n    }\n}\n"},{"path":"Sources/BraidCore/Mixture/Trace/TraceState.swift","lines":40,"bytes":1585,"header":{"lines":[1,11],"what":[8,10],"pin":null,"in":null,"out":null},"marks":[],"first":121,"scopes":[["S","TraceState",null,"public",16,16,[16,55],40,[15,15],-1,0],["i","init",["length","trace","entry","row","offset","next","partitionRun"],"public",29,29,[29,148],37,null,0,0],["E","CodingKeys",null,"",39,39,[39,39],39,null,0,8,[]]],"text":"//\n//  TraceState.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: A node's trace at one position, as the tracker reports it and the session log records\n//        it: the longest live chain's length and trace, the entry it sits on, the token it\n//        expects, and the longest run inside one partition.\n//\n\nimport Foundation\n\n/// A node's trace at one position: the longest live chain and where it sits.\npublic struct TraceState: Codable, Sendable, Equatable {\n    /// Tokens the longest live chain has followed through one document, bridged runs included.\n    public var length: Int\n    public var trace: Float\n    /// The chain's entry now (it expects the next token), the position of that entry's context,\n    /// and the token it expects. Nil without a chain.\n    public var entry: Int32?\n    public var row: Int32?\n    public var offset: Int32?\n    public var next: Int32?\n    /// The longest run that stayed inside one partition (reported beside the document-bounded chain).\n    public var partitionRun: Int\n\n    public init(length: Int, trace: Float, entry: Int32? = nil, row: Int32? = nil, offset: Int32? = nil, next: Int32? = nil, partitionRun: Int = 0) {\n        self.length = length\n        self.trace = trace\n        self.entry = entry\n        self.row = row\n        self.offset = offset\n        self.next = next\n        self.partitionRun = partitionRun\n    }\n\n    enum CodingKeys: String, CodingKey { case length = \"L\", trace = \"tr\", entry = \"e\", row = \"row\", offset = \"off\", next = \"nx\", partitionRun = \"pr\" }\n}\n"},{"path":"Sources/BraidCore/Mixture/Trace/TraceTracker.swift","lines":114,"bytes":5481,"header":{"lines":[1,19],"what":[8,12],"pin":[13,18],"in":null,"out":null},"marks":[],"first":124,"scopes":[["S","TraceTracker",null,"public",23,23,[23,37],114,null,-1,0],["S","Head",null,"",24,24,[24,16],36,null,0,0],["i","init",["corpus","rule"],"public",45,45,[45,66],48,null,0,0],["f","step",["token","hits"],"public mutating",52,52,[52,71],101,[50,51],0,0],["f","bridge",["_"],"private mutating",103,103,[103,53],113,null,0,0]],"text":"//\n//  TraceTracker.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: Follows one text through one node's corpus, a position at a time: whether the text\n//        follows one document the node holds, in order, for longer than a sentence. Retrieval only\n//        seeds a chain; a chain advances only when the token that arrives is the corpus's next\n//        token, so no score from one node's key space enters it. Manner is gone; the trace is\n//        instrumentation that the log can replay exactly.\n//  PIN:  RaoLM's tracker, step for step (the 0.938 was measured with it): heads extend on the\n//        arrived token and move to the successor; a run of `bridge` tokens inherits a dormant\n//        chain of the same document that ended at most `bridge` tokens before, in the text and in\n//        the corpus; the top `seeds` hits start chains; `heads` live chains are kept; dormant\n//        chains expire after 2·bridge steps. Chains are document-bounded (they run across the\n//        break tokens between partitions); the longest run inside one partition is reported too.\n//\n\nimport Foundation\n\npublic struct TraceTracker: Sendable {\n    struct Head {\n        var entry: Int\n        var document: Int32\n        var mass: Int\n        var run: Int\n        var start: Int\n        var startPosition: Int32\n        var ended = 0\n        var endPosition: Int32 = 0\n        /// Tokens matched without leaving the partition the run began in.\n        var partitionRun: Int = 0\n        var partitionRow: Int32\n    }\n\n    public let corpus: TraceCorpus\n    public let rule: TraceRule\n    private var live: [Head] = []\n    private var fresh: [Head] = []\n    private var dormant: [Head] = []\n    private var steps = 0\n\n    public init(corpus: TraceCorpus, rule: TraceRule = .standard) {\n        self.corpus = corpus\n        self.rule = rule\n    }\n\n    /// One position: `token` is the token at this position (the one the previous position's hits\n    /// expected), `hits` what this position's key retrieved (they expect the next token).\n    public mutating func step(token: Int32, hits: [Hit]) -> TraceState {\n        let step = steps\n        steps += 1\n        var moved: [Head] = []\n        var finished: [Head] = []\n        for var head in live + fresh {\n            guard head.entry < corpus.count else { continue }\n            if corpus.values[head.entry] == token {\n                head.mass += 1\n                head.run += 1\n                head.partitionRun = corpus.keyRow[head.entry] == head.partitionRow ? head.partitionRun + 1 : 1\n                if corpus.keyRow[head.entry] != head.partitionRow { head.partitionRow = corpus.keyRow[head.entry] }\n                if head.run == rule.bridge { bridge(&head) }\n                if let next = corpus.successor(of: head.entry) {\n                    head.entry = next\n                    moved.append(head)\n                } else {\n                    head.ended = step + 1\n                    head.endPosition = corpus.positions[head.entry] + 1\n                    dormant.append(head)\n                    finished.append(head)\n                }\n            } else if head.run > 0 {\n                head.ended = step\n                head.endPosition = corpus.positions[head.entry]\n                dormant.append(head)\n            }\n        }\n        var byEntry: [Int: Head] = [:]\n        for head in moved where (byEntry[head.entry]?.mass ?? -1) < head.mass { byEntry[head.entry] = head }\n        live = Array(byEntry.values.sorted { $0.mass != $1.mass ? $0.mass > $1.mass : $0.entry < $1.entry }.prefix(rule.heads))\n\n        let sitting = Set(live.map(\\.entry))\n        fresh = hits.prefix(rule.seeds).compactMap { hit in\n            let entry = Int(hit.entry)\n            guard entry >= 0, entry < corpus.count, !sitting.contains(entry) else { return nil }\n            return Head(entry: entry, document: corpus.documents[entry], mass: 0, run: 0, start: step + 1, startPosition: corpus.positions[entry],\n                        partitionRow: corpus.keyRow[entry])\n        }\n        dormant = Array(dormant.filter { step - $0.ended <= 2 * rule.bridge }\n            .sorted { $0.mass != $1.mass ? $0.mass > $1.mass : $0.entry < $1.entry }.prefix(2 * rule.heads))\n\n        let best = live.first\n        let length = max(best?.mass ?? 0, finished.map(\\.mass).max() ?? 0)\n        let chain = best.flatMap { $0.mass == length ? $0 : nil }\n        let partitionRun = max(live.map(\\.partitionRun).max() ?? 0, finished.map(\\.partitionRun).max() ?? 0)\n        return TraceState(length: length, trace: rule.trace(length: length), entry: chain.map { Int32($0.entry) },\n                          row: chain.map { corpus.keyRow[$0.entry] }, offset: chain.map { corpus.keyOffset[$0.entry] },\n                          next: chain.map { corpus.values[$0.entry] }, partitionRun: partitionRun)\n    }\n\n    private mutating func bridge(_ head: inout Head) {\n        let candidates = dormant.indices.filter { i in\n            let d = dormant[i]\n            let text = head.start - d.ended\n            let corpus = Int(head.startPosition - d.endPosition)\n            return d.document == head.document && d.run >= rule.bridge && (0...rule.bridge).contains(text) && (0...rule.bridge).contains(corpus)\n        }\n        guard let pick = candidates.max(by: { dormant[$0].mass < dormant[$1].mass }) else { return }\n        head.mass += dormant[pick].mass\n        dormant.remove(at: pick)\n    }\n}\n"},{"path":"Sources/BraidCore/Mixture/Trajectory/LiveModule.swift","lines":68,"bytes":3252,"header":{"lines":[1,11],"what":[8,10],"pin":null,"in":null,"out":null},"marks":[],"first":129,"scopes":[["S","LiveModule",null,"public",16,16,[16,35],68,[15,15],-1,0],["i","init",["strands","commons","settings"],"public",21,21,[21,90],25,null,0,0],["f","push",["_"],"public mutating",28,28,[28,56],43,[27,27],0,0],["f","pushContext",["_","strand"],"public mutating",47,47,[47,76],55,[45,46],0,0],["f","evidence",["strand"],"public",58,58,[58,50],61,[57,57],0,0],["f","evidence",[],"public",64,64,[64,39],64,[63,63],0,8],["f","detach",["at"],"public mutating",66,66,[66,47],66,null,0,8],["f","attach",[],"public mutating",67,67,[67,34],67,null,0,8]],"text":"//\n//  LiveModule.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The trajectory module inside a session: fed every step, it hands the gate the next\n//        observation's evidence e_t per strand. It reads the same numbers the offline module\n//        reads from a log.\n//\n\nimport Foundation\n\n/// The module in a session: fed every step, it hands the gate the next observation's e_t per strand.\npublic struct LiveModule: Sendable {\n    public var settings: ModuleSettings\n    public var commons: Int?\n    private var series: [ThreadSeries] = []\n\n    public init(strands: Int, commons: Int?, settings: ModuleSettings = ModuleSettings()) {\n        self.settings = settings\n        self.commons = commons\n        series = (0..<strands).map { _ in ThreadSeries(hlm: [], hknn: [], lift: [], trace: [], commonsHLM: []) }\n    }\n\n    /// Records the step and returns each strand's e_t for the gate's next observation.\n    public mutating func push(_ step: Step) -> [Double] {\n        guard let threads = step.threads else { return series.map { _ in 0 } }\n        while series.count < threads.count { series.append(ThreadSeries(hlm: [], hknn: [], lift: [], trace: [], commonsHLM: [])) }\n        for t in threads.indices {\n            series[t].hlm.append(threads[t].hlm.map(Double.init))\n            series[t].hknn.append(Double(threads[t].hknn))\n            series[t].trace.append(threads[t].trace?.trace ?? 0)\n            if let c = commons, t != c, let own = threads[t].plm, let base = threads[c].plm {\n                series[t].lift.append(log(Double(max(own, 1e-30))) - log(Double(max(base, 1e-30))))\n            } else {\n                series[t].lift.append(nil)\n            }\n            series[t].commonsHLM.append(commons.flatMap { threads[$0].hlm.map(Double.init) })\n        }\n        return evidence()\n    }\n\n    /// A strand's own context position (the question path's sentence before the stem): its series\n    /// gains the record's entropies and trace, with no lift, since the commons does not read it.\n    public mutating func pushContext(_ record: ThreadRecord, strand t: Int) {\n        guard t >= 0 else { return }\n        while series.count <= t { series.append(ThreadSeries(hlm: [], hknn: [], lift: [], trace: [], commonsHLM: [])) }\n        series[t].hlm.append(record.hlm.map(Double.init))\n        series[t].hknn.append(Double(record.hknn))\n        series[t].trace.append(record.trace?.trace ?? 0)\n        series[t].lift.append(nil)\n        series[t].commonsHLM.append(nil)\n    }\n\n    /// The e_t strand t's next observation carries: the reading at its last position (0 before any).\n    public func evidence(strand t: Int) -> Double {\n        guard series.indices.contains(t), series[t].count > 0 else { return 0 }\n        return TrajectoryModule.read(series[t], at: series[t].count - 1, settings: settings).evidence\n    }\n\n    /// Every strand's e_t now.\n    public func evidence() -> [Double] { series.indices.map { evidence(strand: $0) } }\n\n    public mutating func detach(at index: Int) { if series.indices.contains(index) { series.remove(at: index) } }\n    public mutating func attach() { series.append(ThreadSeries(hlm: [], hknn: [], lift: [], trace: [], commonsHLM: [])) }\n}\n"},{"path":"Sources/BraidCore/Mixture/Trajectory/TrajectoryModule.swift","lines":196,"bytes":9487,"header":{"lines":[1,17],"what":[8,12],"pin":[13,16],"in":null,"out":null},"marks":[],"first":137,"scopes":[["S","ModuleSettings",null,"public",21,21,[21,59],42,null,-1,0],["i","init",[],"public",38,38,[38,18],38,null,0,8],["v","referenceSlope",null,"public",41,41,[41,38],41,[40,40],0,8],["E","ModuleLabel",null,"public",44,44,[44,51],55,null,-1,0,["retrieval","stitched","unknown","commons","silent"]],["S","ModuleReading",null,"public",57,57,[57,58],66,null,-1,0],["S","ThreadSeries",null,"public",69,69,[69,48],86,[68,68],-1,0],["i","init",["hlm","hknn","lift","trace","commonsHLM"],"public",77,77,[77,104],83,null,5,0],["v","count",null,"public",85,85,[85,26],85,null,5,8],["E","TrajectoryModule",null,"public",88,88,[88,29],196,null,-1,0,[]],["f","series",["_","commons"],"public static",92,92,[92,80],108,[89,91],8,0],["f","contextCount",["_","strand"],"public static",111,111,[111,75],113,[110,110],8,0],["f","read",["_","at","settings"],"public static",116,116,[116,120],148,[115,115],8,0],["f","readAll",["_","settings"],"public static",152,152,[152,114],156,[150,151],8,0],["f","markRuns",["_","settings"],"static",158,158,[158,86],167,null,8,0],["f","runs",["_","atLeast"],"static",170,170,[170,62],181,[169,169],8,0],["f","detectorScore",["_","from"],"public static",184,184,[184,92],188,[183,183],8,0],["f","coherentFraction",["_","from"],"public static",191,191,[191,95],195,[190,190],8,0]],"text":"//\n//  TrajectoryModule.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The entropy path. Per strand, over its recorded series of (H_lm, H_knn, trace, lift):\n//        the slope of H_knn over a window, a short-horizon forecast, the lift evidence e_t that\n//        steers (step 7, through the gate's one clamp), and the stitched signature — H_lm collapsed\n//        while H_knn does not concentrate and the lift over the commons is high: knowledge the\n//        delta absorbed parametrically that the index does not support.\n//  PIN:  Pure and causal: a reading at j uses positions ≤ j only, so the offline module over a log\n//        and the live module in a session read the same numbers. Trace never feeds the evidence;\n//        it is the ground truth the entropy path is benched against. Directional rules are\n//        hypotheses the benches test, not axioms.\n//\n\nimport Foundation\n\npublic struct ModuleSettings: Codable, Sendable, Equatable {\n    /// Positions of H_knn the slope is fitted over, and how many must be defined.\n    public var window = 8\n    public var minimumPoints = 4\n    /// Positions ahead the forecast reaches.\n    public var horizon = 4\n    /// The retrieval k: H_knn ≤ ln k.\n    public var k = 16\n    /// The stitched signature: H_lm,t ≤ thetaLM·H_lm,c; H_knn,t ≥ thetaKNN·ln k; lift ≥ thetaLift; for ≥ span positions.\n    public var thetaLM = 0.5\n    public var thetaKNN = 0.5\n    public var thetaLift = log(2.0)\n    public var span = 8\n    /// A \"coherent run\": H_knn ≤ coherent for ≥ coherentRun positions (the entropy path's call that trace verifies).\n    public var coherent = log(2.0)\n    public var coherentRun = 24\n\n    public init() {}\n\n    /// The slope that counts as a full collapse or divergence: ln k over a window.\n    public var referenceSlope: Double { log(Double(k)) / Double(window) }\n}\n\npublic enum ModuleLabel: String, Codable, Sendable {\n    /// H_lm collapsed and H_knn concentrates: ordinary retrieval.\n    case retrieval\n    /// H_lm collapsed, H_knn not concentrating, lift high: parametric leakage.\n    case stitched\n    /// H_lm high, H_knn not concentrating: the strand does not know.\n    case unknown\n    /// The commons predicts the token at least as well (lift ≤ 0).\n    case commons\n    /// Too few points, or not asked.\n    case silent\n}\n\npublic struct ModuleReading: Codable, Sendable, Equatable {\n    public var slope: Double?\n    public var forecast: Double?\n    /// e_t ∈ [−1, 1]: collapse → up, divergence above the commons while privately unsure → down.\n    public var evidence: Double\n    public var label: ModuleLabel\n    /// Whether this position is inside a stitched run of ≥ `span` positions.\n    public var stitched: Bool\n    public var coherent: Bool\n}\n\n/// One strand's recorded series over a generation.\npublic struct ThreadSeries: Sendable, Equatable {\n    public var hlm: [Double?]\n    public var hknn: [Double]\n    public var lift: [Double?]\n    public var trace: [Float]\n    /// The commons' H_lm at the same positions (nil without a commons).\n    public var commonsHLM: [Double?]\n\n    public init(hlm: [Double?], hknn: [Double], lift: [Double?], trace: [Float], commonsHLM: [Double?]) {\n        self.hlm = hlm\n        self.hknn = hknn\n        self.lift = lift\n        self.trace = trace\n        self.commonsHLM = commonsHLM\n    }\n\n    public var count: Int { hknn.count }\n}\n\npublic enum TrajectoryModule {\n    /// The series of every strand from a generation's steps, read the way the live module reads them:\n    /// a strand's own context positions first (its ctx lines: no lift, no commons H_lm), then every\n    /// prompt and generated position with strands. Assumes no attach or detach inside the generation.\n    public static func series(_ steps: [Step], commons: Int?) -> [ThreadSeries] {\n        let positions = steps.filter { $0.source != .ctx && $0.threads != nil }\n        guard let first = positions.first?.threads else { return [] }\n        let shared = positions.filter { $0.threads!.count == first.count }\n        return first.indices.map { t in\n            let own = steps.filter { $0.source == .ctx && $0.owner == t }.compactMap { $0.threads?.first }\n            return ThreadSeries(\n                hlm: own.map { $0.hlm.map(Double.init) } + shared.map { $0.threads![t].hlm.map(Double.init) },\n                hknn: own.map { Double($0.hknn) } + shared.map { Double($0.threads![t].hknn) },\n                lift: own.map { _ in nil } + shared.map { step in\n                    guard let c = commons, t != c, let own = step.threads![t].plm, let base = step.threads![c].plm else { return nil }\n                    return log(Double(max(own, 1e-30))) - log(Double(max(base, 1e-30)))\n                },\n                trace: own.map { $0.trace?.trace ?? 0 } + shared.map { $0.threads![t].trace?.trace ?? 0 },\n                commonsHLM: own.map { _ in nil } + shared.map { step in commons.flatMap { step.threads![$0].hlm.map(Double.init) } })\n        }\n    }\n\n    /// How many context positions strand t's series opens with (the offset of the shared positions).\n    public static func contextCount(_ steps: [Step], strand t: Int) -> Int {\n        steps.filter { $0.source == .ctx && $0.owner == t && $0.threads != nil }.count\n    }\n\n    /// The reading at position j, from positions ≤ j only.\n    public static func read(_ s: ThreadSeries, at j: Int, settings: ModuleSettings = ModuleSettings()) -> ModuleReading {\n        let start = max(0, j - settings.window + 1)\n        let window = Array(s.hknn[start...j])\n        var slope: Double?\n        var forecast: Double?\n        var evidence = 0.0\n        if window.count >= settings.minimumPoints, let fitted = Stats.slope(window) {\n            slope = fitted\n            forecast = min(max(s.hknn[j] + Double(settings.horizon) * fitted, 0), log(Double(settings.k)))\n            let collapse = min(max(-fitted / settings.referenceSlope, 0), 1)\n            var divergence = min(max(fitted / settings.referenceSlope, 0), 1)\n            if let own = s.hlm[j], let base = s.commonsHLM[j] {\n                if !(s.hknn[j] > base && own > base) { divergence = 0 }\n            } else {\n                divergence = 0\n            }\n            evidence = collapse - divergence\n        }\n        let lnk = log(Double(settings.k))\n        var label = ModuleLabel.silent\n        if let own = s.hlm[j], let lift = s.lift[j] {\n            let base = s.commonsHLM[j] ?? lnk\n            let collapsed = own <= settings.thetaLM * base\n            let unsupported = s.hknn[j] >= settings.thetaKNN * lnk\n            if lift <= 0 { label = .commons }\n            else if collapsed && unsupported && lift >= settings.thetaLift { label = .stitched }\n            else if collapsed && !unsupported { label = .retrieval }\n            else if !collapsed && unsupported { label = .unknown }\n            else { label = .retrieval }\n        }\n        return ModuleReading(slope: slope, forecast: forecast, evidence: evidence, label: label, stitched: false,\n                             coherent: s.hknn[j] <= settings.coherent)\n    }\n\n    /// Every position's reading, with stitched runs (≥ span consecutive stitched labels) and\n    /// coherent runs (≥ coherentRun consecutive low H_knn) marked.\n    public static func readAll(_ s: ThreadSeries, settings: ModuleSettings = ModuleSettings()) -> [ModuleReading] {\n        var readings = (0..<s.count).map { read(s, at: $0, settings: settings) }\n        markRuns(&readings, settings: settings)\n        return readings\n    }\n\n    static func markRuns(_ readings: inout [ModuleReading], settings: ModuleSettings) {\n        // Stitched: inside any run of ≥ span consecutive stitched labels.\n        let stitched = runs(readings.map { $0.label == .stitched }, atLeast: settings.span)\n        // Coherent: inside any run of ≥ coherentRun consecutive positions with H_knn ≤ coherent.\n        let coherent = runs(readings.map(\\.coherent), atLeast: settings.coherentRun)\n        for j in readings.indices {\n            readings[j].stitched = stitched[j]\n            readings[j].coherent = coherent[j]\n        }\n    }\n\n    /// Marks every position inside a maximal run of `true` of length ≥ `atLeast`.\n    static func runs(_ flags: [Bool], atLeast: Int) -> [Bool] {\n        var marked = [Bool](repeating: false, count: flags.count)\n        var start = 0\n        while start < flags.count {\n            guard flags[start] else { start += 1; continue }\n            var end = start\n            while end < flags.count, flags[end] { end += 1 }\n            if end - start >= atLeast { for k in start..<end { marked[k] = true } }\n            start = end\n        }\n        return marked\n    }\n\n    /// The detector's score for a text: the share of positions from `from` inside a stitched run.\n    public static func detectorScore(_ readings: [ModuleReading], from: Int = 24) -> Double {\n        let tail = readings.dropFirst(from)\n        guard !tail.isEmpty else { return 0 }\n        return Double(tail.filter(\\.stitched).count) / Double(tail.count)\n    }\n\n    /// The share of positions from `from` inside a coherent run (the entropy path's \"coherent run\" call).\n    public static func coherentFraction(_ readings: [ModuleReading], from: Int = 24) -> Double {\n        let tail = readings.dropFirst(from)\n        guard !tail.isEmpty else { return 0 }\n        return Double(tail.filter(\\.coherent).count) / Double(tail.count)\n    }\n}\n"},{"path":"Sources/BraidCore/Port/RaoLMCheck.swift","lines":393,"bytes":20822,"header":{"lines":[1,21],"what":[8,15],"pin":[16,20],"in":null,"out":null},"marks":[[29,"(a) Shares"],[125,"The mapping onto each node's index"],[187,"(b) Trace replay"],[331,"What phase A reads of a record"]],"first":154,"scopes":[["E","RaoLMCheck",null,"public",25,25,[25,23],393,null,-1,0,[]],["S","ShareWorst",null,"public",31,31,[31,59],37,null,0,0],["S","Shares",null,"public",39,39,[39,55],78,null,0,0],["i","init",[],"public",60,60,[60,22],60,null,2,8],["v","maxError",null,"public",62,62,[62,36],62,null,2,8],["v","passes",null,"public",63,63,[63,32],63,null,2,8],["f","add",["_"],"public mutating",65,65,[65,50],77,null,2,0],["f","shares",["_","file","ranges"],"public static",80,80,[80,98],123,null,0,0],["S","Mapping",null,"public",127,127,[127,56],157,null,0,0],["i","init",[],"public",143,143,[143,22],143,null,8,8],["v","passes",null,"public",145,145,[145,32],145,null,8,8],["f","add",["_"],"public mutating",147,147,[147,51],156,null,8,0],["f","mapping",["_","layouts","ranges","rule"],"public static",159,159,[159,135],185,null,0,0],["S","Replay",null,"public",192,192,[192,35],198,[189,191],0,0],["f","replay",["_","corpora","ranges","rule"],"public static",200,200,[200,133],226,null,0,0],["S","StrandReplay",null,"public",228,228,[228,61],253,null,0,0],["i","init",[],"public",242,242,[242,22],242,null,15,8],["f","add",["_"],"public mutating",244,244,[244,56],252,null,15,0],["S","TraceMismatch",null,"public",255,255,[255,62],268,null,0,0],["S","Traces",null,"public",270,270,[270,55],287,null,0,0],["i","init",[],"public",275,275,[275,22],275,null,19,8],["v","positions",null,"public",277,277,[277,34],277,null,19,8],["v","passes",null,"public",278,278,[278,32],280,null,19,0],["f","add",["_"],"public mutating",282,282,[282,50],286,null,19,0],["f","traces",["_","replay","set","file","rule"],"public static",290,290,[290,122],329,[289,289],0,0],["S","ScoredText",null,"public",334,334,[334,39],357,[333,333],0,0],["f","scoredText",["_","file","replay","imported","documentOfRow"],"public static",359,359,[360,90],392,null,0,0]],"text":"//\n//  RaoLMCheck.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The port validation's two record-level checks. (a) Shares: Braid's arithmetic over what\n//        RaoLM logged — w′ the gate renormalised over the open strands, share_t = w′_t·p_t(y)/p(y)\n//        with p_t RaoLM's `alone` — must equal RaoLM's logged share within 1e-5; the plan's form\n//        from the gate, open, p_lm and RaoLM's `knn` (which is w′_t·p_knn,t, not p_knn) is checked\n//        beside it. (b) Trace: Braid's TraceTracker, fed RaoLM's tokens and each strand's own hits\n//        over the node's index layout, must reproduce RaoLM's trajectory length and next token at\n//        every position. Plus the mapping itself: every pooled hit lands on its node's index at the\n//        value and key position RaoLM logged.\n//  PIN:  A Thread strand's hits are missing from a record where RaoLM gave its retrieval no weight;\n//        the tracker cannot seed chains there, so a mismatch after such a position is counted\n//        apart (and called explained only when the chain's window holds one); a mismatch with every\n//        earlier hit present is a failure. The final position (after the text's last token) is\n//        replayed with no hits: hits there seed only chains for a token that never comes.\n//\n\nimport Foundation\n\npublic enum RaoLMCheck {\n    /// The plan's tolerance on recomputed shares.\n    public static let shareTolerance = 1e-5\n\n    // MARK: - (a) Shares\n\n    public struct ShareWorst: Codable, Sendable, Equatable {\n        public var file: String\n        public var index: Int\n        public var strand: String\n        public var recomputed: Double\n        public var logged: Float\n    }\n\n    public struct Shares: Codable, Sendable, Equatable {\n        public var records = 0\n        public var positions = 0\n        /// Strand shares compared: every strand at every position.\n        public var values = 0\n        /// share_t = w′_t·alone_t / Σ_s w′_s·alone_s against the logged share.\n        public var maxErrorAlone = 0.0\n        /// The same from the gate, open, p_lm and RaoLM's knn: (λ_t·knn_t + (1−λ_t)·w′_t·p_lm,t) / Σ.\n        public var maxErrorLogged = 0.0\n        public var worst: ShareWorst?\n        /// |Σ_t w′_t·alone_t − mixedProb| / mixedProb.\n        public var maxRelativeP = 0.0\n        /// |Σ_t w′_t·λ_t − the trace's λ|.\n        public var maxLambdaError = 0.0\n        /// |Σ_t share_t − 1| as logged.\n        public var maxShareSumError = 0.0\n        /// Where a strand was asked and its hits are in the record: |λ_t·p_knn,t(y) + (1−λ_t)·p_lm,t(y) − alone|,\n        /// p_knn from its hits at τ: the hits, τ and λ_t the import uses reproduce RaoLM's own p_t.\n        public var aloneFromHits = 0\n        public var maxAloneFromHitsError = 0.0\n\n        public init() {}\n\n        public var maxError: Double { max(maxErrorAlone, maxErrorLogged) }\n        public var passes: Bool { values > 0 && maxError <= RaoLMCheck.shareTolerance }\n\n        public mutating func add(_ other: Shares) {\n            records += other.records\n            positions += other.positions\n            values += other.values\n            if other.maxErrorAlone > maxErrorAlone { worst = other.worst }\n            maxErrorAlone = max(maxErrorAlone, other.maxErrorAlone)\n            maxErrorLogged = max(maxErrorLogged, other.maxErrorLogged)\n            maxRelativeP = max(maxRelativeP, other.maxRelativeP)\n            maxLambdaError = max(maxLambdaError, other.maxLambdaError)\n            maxShareSumError = max(maxShareSumError, other.maxShareSumError)\n            aloneFromHits += other.aloneFromHits\n            maxAloneFromHitsError = max(maxAloneFromHitsError, other.maxAloneFromHitsError)\n        }\n    }\n\n    public static func shares(_ g: RaoLMGeneration, file: String, ranges: [Range<Int>]) -> Shares {\n        var result = Shares()\n        guard let braid = g.braid else { return result }\n        result.records = 1\n        let lambdas = RaoLMImport.lambdas(g, braid: braid)\n        let tau = Double(g.params.tau)\n        for trace in g.traces {\n            guard let strands = trace.strands, strands.count == braid.strands.count else { continue }\n            result.positions += 1\n            let open = strands.map(\\.open)\n            let weights = Gate.renormalised(strands.map { Double($0.gate) }, open: open)\n            let parts = strands.indices.map { t -> Double in open[t] ? weights[t] * Double(strands[t].alone ?? 0) : 0 }\n            let logged = strands.indices.map { t -> Double in\n                open[t] ? lambdas[t] * Double(strands[t].knn) + (1 - lambdas[t]) * weights[t] * Double(strands[t].lmProb ?? 0) : 0\n            }\n            let p = parts.reduce(0, +)\n            let pLogged = logged.reduce(0, +)\n            for t in strands.indices {\n                let fromAlone = p > 0 ? parts[t] / p : weights[t]\n                let fromLogged = pLogged > 0 ? logged[t] / pLogged : weights[t]\n                let error = abs(fromAlone - Double(strands[t].share))\n                if result.worst == nil || error > result.maxErrorAlone {\n                    result.worst = ShareWorst(file: file, index: trace.index, strand: strands[t].strand, recomputed: fromAlone, logged: strands[t].share)\n                    result.maxErrorAlone = error\n                }\n                result.maxErrorLogged = max(result.maxErrorLogged, abs(fromLogged - Double(strands[t].share)))\n                result.values += 1\n            }\n            if trace.mixedProb > 0 { result.maxRelativeP = max(result.maxRelativeP, abs(p - Double(trace.mixedProb)) / Double(trace.mixedProb)) }\n            let lambda = strands.indices.reduce(0.0) { $0 + weights[$1] * lambdas[$1] }\n            result.maxLambdaError = max(result.maxLambdaError, abs(lambda - Double(trace.lambda)))\n            result.maxShareSumError = max(result.maxShareSumError, abs(strands.reduce(0.0) { $0 + Double($1.share) } - 1))\n            let hits = RaoLMImport.hits(trace, braid: braid, ranges: ranges)\n            for t in strands.indices where !braid.strands[t].isCommons {\n                guard let own = hits[t], let alone = strands[t].alone, let plm = strands[t].lmProb else { continue }\n                let w = Mixer.weights(own.map { Double($0.score) }, tau: tau)\n                let pknn = own.indices.reduce(0.0) { $0 + (own[$1].value == Int32(trace.token) ? w[$1] : 0) }\n                let p = lambdas[t] * pknn + (1 - lambdas[t]) * Double(plm)\n                result.aloneFromHits += 1\n                result.maxAloneFromHitsError = max(result.maxAloneFromHitsError, abs(p - Double(alone)))\n            }\n        }\n        return result\n    }\n\n    // MARK: - The mapping onto each node's index\n\n    public struct Mapping: Codable, Sendable, Equatable {\n        /// Pooled hits mapped back to a node.\n        public var hits = 0\n        /// Hits in no Thread strand's range, or past its node's index.\n        public var outside = 0\n        /// The node's value at the hit's entry differs from the hit's value.\n        public var valueMismatches = 0\n        /// The node's key row and offset at the entry differ from the hit's key, less the strand's row offset.\n        public var keyMismatches = 0\n        /// Logged chains checked against the node: the entry's value is `next`, its key position is `at`.\n        public var chains = 0\n        public var chainMismatches = 0\n        /// Logged node traces that differ from the rule's trace of the logged length.\n        public var traces = 0\n        public var traceMismatches = 0\n\n        public init() {}\n\n        public var passes: Bool { outside == 0 && valueMismatches == 0 && keyMismatches == 0 && chainMismatches == 0 && traceMismatches == 0 }\n\n        public mutating func add(_ other: Mapping) {\n            hits += other.hits\n            outside += other.outside\n            valueMismatches += other.valueMismatches\n            keyMismatches += other.keyMismatches\n            chains += other.chains\n            chainMismatches += other.chainMismatches\n            traces += other.traces\n            traceMismatches += other.traceMismatches\n        }\n    }\n\n    public static func mapping(_ g: RaoLMGeneration, layouts: [String: IndexLayout], ranges: [Range<Int>], rule: TraceRule) -> Mapping {\n        var result = Mapping()\n        guard let braid = g.braid else { return result }\n        for trace in g.traces {\n            for neighbour in trace.neighbours {\n                result.hits += 1\n                guard let t = ranges.firstIndex(where: { $0.contains(neighbour.entry) }), !braid.strands[t].isCommons,\n                      let layout = layouts[braid.strands[t].name] else { result.outside += 1; continue }\n                let strand = braid.strands[t]\n                let entry = neighbour.entry - strand.entryOffset\n                guard entry >= 0, entry < layout.values.count else { result.outside += 1; continue }\n                if Int(layout.values[entry]) != neighbour.value { result.valueMismatches += 1 }\n                if Int(layout.keyRow[entry]) != neighbour.key.row - strand.rowOffset || Int(layout.keyOffset[entry]) != neighbour.key.offset { result.keyMismatches += 1 }\n            }\n            for (t, share) in (trace.strands ?? []).enumerated() where t < braid.strands.count {\n                guard let trajectory = share.trajectory else { continue }\n                result.traces += 1\n                if trajectory.trace != rule.trace(length: trajectory.length) { result.traceMismatches += 1 }\n                guard let entry = trajectory.entry, let layout = layouts[braid.strands[t].name] else { continue }\n                result.chains += 1\n                let fits = entry >= 0 && entry < layout.values.count && trajectory.next == Int(layout.values[entry])\n                    && trajectory.at == RaoLMPosition(row: Int(layout.keyRow[entry]), offset: Int(layout.keyOffset[entry]))\n                if !fits { result.chainMismatches += 1 }\n            }\n        }\n        return result\n    }\n\n    // MARK: - (b) Trace replay\n\n    /// One record replayed: per strand (nil for the commons or a strand without a layout) the\n    /// tracker's state at every trace, and after the text's last token; and where the record lacks\n    /// the strand's hits.\n    public struct Replay: Sendable {\n        public var states: [[TraceState]?]\n        public var final: [TraceState?]\n        public var missing: [[Bool]]\n        /// Per strand, per trace: its hits (empty where missing), for the readings.\n        public var hits: [[[Hit]]]\n    }\n\n    public static func replay(_ g: RaoLMGeneration, corpora: [String: TraceCorpus], ranges: [Range<Int>], rule: TraceRule) -> Replay {\n        guard let braid = g.braid else { return Replay(states: [], final: [], missing: [], hits: []) }\n        let tokens = (g.prompt.tokens + g.tokens).map { Int32($0) }\n        let n = braid.strands.count\n        var trackers: [TraceTracker?] = braid.strands.map { $0.isCommons ? nil : corpora[$0.name].map { TraceTracker(corpus: $0, rule: rule) } }\n        var states: [[TraceState]?] = trackers.map { $0 == nil ? nil : [] }\n        var missing = [[Bool]](repeating: [], count: n)\n        var hitsByStrand = [[[Hit]]](repeating: [], count: n)\n        for trace in g.traces {\n            let hits = RaoLMImport.hits(trace, braid: braid, ranges: ranges)\n            let token = trace.index >= 1 && trace.index - 1 < tokens.count ? tokens[trace.index - 1] : -1\n            for t in 0..<n {\n                missing[t].append(hits[t] == nil && !braid.strands[t].isCommons)\n                hitsByStrand[t].append(hits[t] ?? [])\n                guard var tracker = trackers[t] else { continue }\n                states[t]?.append(tracker.step(token: token, hits: hits[t] ?? []))\n                trackers[t] = tracker\n            }\n        }\n        var final: [TraceState?] = []\n        for t in 0..<n {\n            guard var tracker = trackers[t], let last = tokens.last else { final.append(nil); continue }\n            final.append(tracker.step(token: last, hits: []))\n            trackers[t] = tracker\n        }\n        return Replay(states: states, final: final, missing: missing, hits: hitsByStrand)\n    }\n\n    public struct StrandReplay: Codable, Sendable, Equatable {\n        public var positions = 0\n        public var matched = 0\n        /// Positions where the record lacks the strand's hits.\n        public var missingHits = 0\n        /// Positions compared after the first one whose hits the record lacks.\n        public var afterMissing = 0\n        /// Mismatches with every earlier hit in the record: failures.\n        public var mismatches = 0\n        /// Mismatches after a position whose hits the record lacks.\n        public var mismatchesAfterMissing = 0\n        /// Of those, the ones whose chain window (back by the longer chain and two bridges) holds such a position.\n        public var explained = 0\n\n        public init() {}\n\n        public mutating func add(_ other: StrandReplay) {\n            positions += other.positions\n            matched += other.matched\n            missingHits += other.missingHits\n            afterMissing += other.afterMissing\n            mismatches += other.mismatches\n            mismatchesAfterMissing += other.mismatchesAfterMissing\n            explained += other.explained\n        }\n    }\n\n    public struct TraceMismatch: Codable, Sendable, Equatable {\n        public var set: String\n        public var file: String\n        public var strand: String\n        public var index: Int\n        public var loggedLength: Int\n        public var loggedNext: Int?\n        public var replayedLength: Int\n        public var replayedNext: Int?\n        public var afterMissingHits: Bool\n        public var explained: Bool\n        /// Trace indices in the chain's window where the record lacks the strand's hits.\n        public var missingNear: [Int]\n    }\n\n    public struct Traces: Codable, Sendable, Equatable {\n        public var records = 0\n        public var strands: [String: StrandReplay] = [:]\n        public var mismatches: [TraceMismatch] = []\n\n        public init() {}\n\n        public var positions: Int { strands.values.reduce(0) { $0 + $1.positions } }\n        public var passes: Bool {\n            positions > 0 && strands.values.allSatisfy { $0.mismatches == 0 && $0.explained == $0.mismatchesAfterMissing }\n        }\n\n        public mutating func add(_ other: Traces) {\n            records += other.records\n            for (name, tally) in other.strands { strands[name, default: StrandReplay()].add(tally) }\n            mismatches += other.mismatches.prefix(max(0, 200 - mismatches.count))\n        }\n    }\n\n    /// Compares a record's logged trajectories with its replay.\n    public static func traces(_ g: RaoLMGeneration, replay: Replay, set: String, file: String, rule: TraceRule) -> Traces {\n        var result = Traces()\n        guard let braid = g.braid else { return result }\n        result.records = 1\n        for (t, strand) in braid.strands.enumerated() {\n            guard let states = replay.states[t] else { continue }\n            var tally = StrandReplay()\n            var missingSeen = false\n            for (i, trace) in g.traces.enumerated() where i < states.count {\n                // Hits seed chains for later tokens: a lack at i leaves the states after i unknown.\n                defer { if replay.missing[t][i] { tally.missingHits += 1; missingSeen = true } }\n                guard let shares = trace.strands, t < shares.count else { continue }\n                let logged = shares[t].trajectory\n                let loggedLength = logged?.length ?? 0\n                let loggedNext = logged?.next\n                let state = states[i]\n                tally.positions += 1\n                if missingSeen { tally.afterMissing += 1 }\n                if loggedLength == state.length && loggedNext == state.next.map(Int.init) {\n                    tally.matched += 1\n                    continue\n                }\n                let reach = max(loggedLength, state.length) + 2 * rule.bridge + 1\n                let near = (max(0, i - reach)..<i).filter { replay.missing[t][$0] }.map { g.traces[$0].index }\n                if missingSeen {\n                    tally.mismatchesAfterMissing += 1\n                    if !near.isEmpty { tally.explained += 1 }\n                } else {\n                    tally.mismatches += 1\n                }\n                if result.mismatches.count < 200 {\n                    result.mismatches.append(TraceMismatch(set: set, file: file, strand: strand.name, index: trace.index, loggedLength: loggedLength,\n                                                           loggedNext: loggedNext, replayedLength: state.length, replayedNext: state.next.map(Int.init),\n                                                           afterMissingHits: missingSeen, explained: missingSeen && !near.isEmpty, missingNear: near))\n                }\n            }\n            result.strands[strand.name] = tally\n        }\n        return result\n    }\n\n    // MARK: - What phase A reads of a record\n\n    /// A scored text as phase A reads it, kept from the check's single pass so no record is decoded twice.\n    public struct ScoredText: Sendable {\n        public var file: String\n        public var strands: [String]\n        public var commons: Int?\n        public var tokens: [Int32]\n        /// Per trace: its index (the text position whose token it predicts).\n        public var traceIndex: [Int]\n        /// Per strand (nil for the commons): the chain length after each of the text's tokens, step j\n        /// after token j for j in 0..<n: the record's trajectories, the last from Braid's tracker.\n        public var lengths: [[Int]?]\n        /// Per strand: the replay's longest partition-bounded run.\n        public var partitionRuns: [Int]\n        /// Per strand: the longest chain the record's hits alone show (TraceAudit, RaoLM's convention).\n        public var wireLongest: [Int]\n        /// Per strand, per trace: p_knn,t of the token (from the hits; from `alone` where they are missing).\n        public var pknn: [[Float]]\n        /// Per strand, per trace: the best score among its hits (nil where they are missing).\n        public var best: [[Float?]]\n        /// Per trace, per strand: what RaoLM logged.\n        public var alone: [[Float?]]\n        public var memory: [[Float]]\n        public var share: [[Float]]\n        public var open: [[Bool]]\n    }\n\n    public static func scoredText(_ g: RaoLMGeneration, file: String, replay: Replay, imported: ImportedSession,\n                                  documentOfRow: [String: [Int32: String]]) -> ScoredText {\n        let braid = g.braid\n        let names = braid?.strands.map(\\.name) ?? []\n        let tokens = (g.prompt.tokens + g.tokens).map { Int32($0) }\n        var lengths: [[Int]?] = []\n        var wire: [Int] = []\n        var runs: [Int] = []\n        for (t, name) in names.enumerated() {\n            guard braid?.strands[t].isCommons == false, let final = replay.final[t] else {\n                lengths.append(nil); wire.append(0); runs.append(0); continue\n            }\n            var steps = [Int](repeating: 0, count: tokens.count)\n            for trace in g.traces where trace.index >= 1 && trace.index - 1 < steps.count {\n                steps[trace.index - 1] = trace.strands?[t].trajectory?.length ?? 0\n            }\n            if !steps.isEmpty { steps[steps.count - 1] = final.length }\n            lengths.append(steps)\n            var hits = [[Hit]](repeating: [], count: tokens.count)\n            for (i, trace) in g.traces.enumerated() where trace.index >= 1 && trace.index - 1 < hits.count { hits[trace.index - 1] = replay.hits[t][i] }\n            wire.append(TraceAudit.wireLengths(tokens: tokens, hits: hits, documentOfRow: documentOfRow[name] ?? [:]).max() ?? 0)\n            runs.append(max((replay.states[t] ?? []).map(\\.partitionRun).max() ?? 0, final.partitionRun))\n        }\n        let records = imported.steps.compactMap(\\.threads)\n        return ScoredText(\n            file: file, strands: names, commons: braid?.strands.firstIndex(where: \\.isCommons), tokens: tokens, traceIndex: g.traces.map(\\.index),\n            lengths: lengths, partitionRuns: runs, wireLongest: wire,\n            pknn: names.indices.map { t in records.map { $0[t].pknn } },\n            best: names.indices.map { t in g.traces.indices.map { i in replay.missing[t][i] ? nil : replay.hits[t][i].first?.score } },\n            alone: g.traces.map { $0.strands?.map(\\.alone) ?? [] },\n            memory: g.traces.map { $0.strands?.map { $0.memory ?? $0.gate } ?? [] },\n            share: g.traces.map { $0.strands?.map(\\.share) ?? [] },\n            open: g.traces.map { $0.strands?.map(\\.open) ?? [] })\n    }\n}\n"},{"path":"Sources/BraidCore/Port/RaoLMImport.swift","lines":337,"bytes":24917,"header":{"lines":[1,21],"what":[8,14],"pin":[15,20],"in":null,"out":null},"marks":[[77,"Strands and hits"],[128,"The session"],[268,"What maps where"]],"first":181,"scopes":[["S","ImportedSession",null,"public",26,26,[26,40],60,[25,25],-1,0],["f","bodyLines",[],"public",38,38,[38,47],38,[37,37],0,8],["f","endLine",["bodySHA256"],"",40,40,[40,48],43,null,0,0],["f","logged",[],"public",46,46,[46,49],50,[45,45],0,0],["f","write",["to"],"public",52,52,[52,42],59,null,0,0],["E","RaoLMImport",null,"public",62,62,[62,24],337,null,-1,0,[]],["E","Failure",null,"public",65,65,[65,56],75,null,5,0,["notBraided","strands"]],["v","description",null,"public",69,69,[69,39],74,null,6,0],["f","entryRanges",["_","counts"],"public static",81,81,[81,101],88,[79,80],5,0],["f","hits",["_","braid","ranges"],"public static",94,94,[94,102],111,[90,93],5,0],["f","traceState",["_","rule"],"public static",116,116,[116,110],121,[113,115],5,0],["f","lambdas",["_","braid"],"public static",124,124,[124,84],126,[123,123],5,0],["f","pack",["_","dataRoot"],"public static",133,133,[133,82],150,[130,132],5,0],["S","Vocabulary",null,"",134,134,[134,37],134,null,12,12],["S","PackRecord",null,"",135,135,[135,37],135,null,12,12],["f","gateSettings",["_"],"public static",156,156,[156,73],168,[152,155],5,0],["f","decimal",["_"],"static",172,172,[172,50],172,[170,171],5,8],["f","threads",["_","braid","pack"],"public static",175,175,[175,111],188,[174,174],5,0],["f","sessionID",["set","file","generationID"],"public static",191,191,[191,92],193,[190,190],5,0],["f","session",["_","sessionID","pack","ranges","rule"],"public static",196,196,[197,86],266,[195,195],5,0],["S","FieldNote",null,"public",270,270,[270,58],276,null,5,0]],"text":"//\n//  RaoLMImport.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: One RaoLM generation record becomes one Braid session log (`source: raolm`): the header\n//        names RaoLM's strands and pack, the generation line its prompt and parameters, and every\n//        trace becomes a `tok` line whose per-strand records carry RaoLM's memory, gate, open set,\n//        p_lm, H_lm, share and trajectory, with each strand's own hits taken from the pooled\n//        neighbours (global entries mapped back to the node's). What RaoLM never logged is derived\n//        here and said so (`fieldNotes`): w′ from the gate and the open set, p_knn and H_knn from\n//        the strand's hits and τ, the shadow β4 from the memory and the trace.\n//  PIN:  Pure: no model. RaoLM scores a text with no eos opener, so step 0 is the text's first token\n//        (no strands) and step i is RaoLM's trace i, whose hits predicted token i and whose chain\n//        state followed tokens 0..<i. A Thread strand's hits are missing from a record wherever\n//        RaoLM's mixture gave its retrieval no weight (its gate underflowed to 0, or it was not\n//        asked); such a record logs no hits for it, and p_knn from what the strand alone gave the\n//        token instead.\n//\n\nimport Foundation\n\n/// One RaoLM record as a Braid session, before or after it is written.\npublic struct ImportedSession: Sendable {\n    public var header: SessionHeader\n    public var gen: GenerationLine\n    public var steps: [Step]\n    public var partitions: [PartitionRef]\n    public var text: String\n    public var generated: Int\n    public var stoppedOn: StopReason?\n    /// Thread strand-positions whose hits the record lacks.\n    public var missingHits: Int\n\n    /// The generation's body lines as SessionWriter writes them, and the end line's hash of them.\n    public func bodyLines() throws -> [String] { try [JSONCoding.line(gen)] + steps.map { try JSONCoding.line($0) } }\n\n    func endLine(bodySHA256: String) -> EndLine {\n        EndLine(generationID: gen.generationID, tokens: gen.prompt.tokens.count + generated, generated: generated, stoppedOn: stoppedOn, text: text,\n                partitions: partitions, bodySHA256: bodySHA256)\n    }\n\n    /// The session as SessionReader reads it back from the file `write` makes.\n    public func logged() throws -> LoggedSession {\n        let hash = ContentHash.sha256Hex(try bodyLines().map { $0 + \"\\n\" }.joined())\n        let generation = LoggedGeneration(gen: gen, steps: steps, end: endLine(bodySHA256: hash), membership: [], bodySHA256: hash)\n        return LoggedSession(header: header, generations: [generation], membership: [])\n    }\n\n    public func write(to url: URL) throws {\n        let writer = try SessionWriter(url: url, header: header)\n        defer { writer.close() }\n        try writer.begin(gen)\n        for step in steps { try writer.append(step) }\n        try writer.end(generationID: gen.generationID, tokens: gen.prompt.tokens.count + generated, generated: generated, stoppedOn: stoppedOn, text: text,\n                       partitions: partitions)\n    }\n}\n\npublic enum RaoLMImport {\n    public static let source = \"raolm\"\n\n    public enum Failure: Error, CustomStringConvertible {\n        case notBraided(String)\n        case strands(String)\n\n        public var description: String {\n            switch self {\n            case .notBraided(let id): return \"\\(id) is not a braided RaoLM generation (no braid, or a gating other than braided)\"\n            case .strands(let detail): return \"RaoLM record: \\(detail)\"\n            }\n        }\n    }\n\n    // MARK: - Strands and hits\n\n    /// Per strand, its global entries: from its entryOffset to the next strand's (the last to the end\n    /// of `counts` when known). The commons retrieves nothing, so its range holds no neighbour.\n    public static func entryRanges(_ braid: RaoLMBraid, counts: [String: Int] = [:]) -> [Range<Int>] {\n        braid.strands.map { strand in\n            if strand.isCommons { return strand.entryOffset..<strand.entryOffset }\n            if let count = counts[strand.name] { return strand.entryOffset..<(strand.entryOffset + count) }\n            let next = braid.strands.map(\\.entryOffset).filter { $0 > strand.entryOffset }.min() ?? Int.max\n            return strand.entryOffset..<next\n        }\n    }\n\n    /// Per strand, the hits RaoLM pooled at this trace, node-local (entry and cited row less the\n    /// strand's offsets) and in the node's own order (score descending, then entry ascending, as\n    /// RaoLM's index query sorts them). Nil for a Thread strand the record holds none of; empty for\n    /// the commons.\n    public static func hits(_ trace: RaoLMTrace, braid: RaoLMBraid, ranges: [Range<Int>]) -> [[Hit]?] {\n        var byStrand = [[RaoLMNeighbour]](repeating: [], count: braid.strands.count)\n        for neighbour in trace.neighbours {\n            guard let t = ranges.firstIndex(where: { $0.contains(neighbour.entry) }) else { continue }\n            byStrand[t].append(neighbour)\n        }\n        return braid.strands.indices.map { t -> [Hit]? in\n            let strand = braid.strands[t]\n            if strand.isCommons { return [] }\n            guard !byStrand[t].isEmpty else { return nil }\n            return byStrand[t]\n                .sorted { $0.score != $1.score ? $0.score > $1.score : $0.entry < $1.entry }\n                .map { n in\n                    Hit(entry: Int32(n.entry - strand.entryOffset), score: n.score, value: Int32(n.value), row: Int32(n.cited.row - strand.rowOffset),\n                        offset: Int32(n.cited.offset), loss: n.sourceLoss)\n                }\n        }\n    }\n\n    /// RaoLM's trajectory as Braid's trace state: the length and where the chain sits; the trace\n    /// re-read from the length by `rule` (RaoLM's umbrella did the same); no partition-bounded run\n    /// (RaoLM kept none).\n    public static func traceState(_ trajectory: RaoLMTrajectory?, rule: TraceRule = .standard) -> TraceState? {\n        guard let trajectory else { return nil }\n        return TraceState(length: trajectory.length, trace: rule.trace(length: trajectory.length), entry: trajectory.entry.map { Int32($0) },\n                          row: trajectory.at.map { Int32($0.row) }, offset: trajectory.at.map { Int32($0.offset) }, next: trajectory.next.map { Int32($0) },\n                          partitionRun: 0)\n    }\n\n    /// λ_t: the request's λ for a Thread, 0 for the commons (RaoLM's lambdaScale; no calibration rides in a record).\n    public static func lambdas(_ g: RaoLMGeneration, braid: RaoLMBraid) -> [Double] {\n        braid.strands.map { $0.isCommons ? 0 : Double(g.params.lambda) }\n    }\n\n    // MARK: - The session\n\n    /// The pack a RaoLM braid ran: its umbrella pack's sha, vocabulary and tokenizer, and, when the\n    /// data root holds the umbrella (`umbrella/<sha12>/vocabulary.json`, `pack.json`), its name,\n    /// hidden size and vocabulary size (0 when it does not).\n    public static func pack(_ g: RaoLMGeneration, dataRoot: URL?) -> PackIdentity {\n        struct Vocabulary: Decodable { var hiddenSize: Int; var vocabSize: Int }\n        struct PackRecord: Decodable { var name: String }\n        let braid = g.braid\n        let sha = braid?.packSHA256\n        var hidden = 0, vocabulary = 0\n        var name: String?\n        if let dataRoot, let sha {\n            let directory = dataRoot.appendingPathComponent(\"umbrella\", isDirectory: true).appendingPathComponent(String(sha.prefix(12)), isDirectory: true)\n            if let v = try? JSONCoding.read(Vocabulary.self, from: directory.appendingPathComponent(\"vocabulary.json\")) {\n                hidden = v.hiddenSize\n                vocabulary = v.vocabSize\n            }\n            name = (try? JSONCoding.read(PackRecord.self, from: directory.appendingPathComponent(\"pack.json\")))?.name\n        }\n        return PackIdentity(sha256: sha, name: name, vocabularySHA256: braid?.vocabularySHA256 ?? \"\", tokenizerSHA256: g.manifest.tokenizerSHA256,\n                            hiddenSize: hidden, vocabulary: vocabulary)\n    }\n\n    /// RaoLM's braided gate in Braid's settings: the evidence floor and ceiling, the share and\n    /// credibility rates, the commons prior and the open floor carry over; agreement, the trajectory\n    /// term, asking by manner, generated evidence and the share mode have no Braid setting (the\n    /// import report lists them per arm).\n    public static func gateSettings(_ braid: RaoLMBraid) -> GateSettings {\n        var settings = GateSettings()\n        if let gate = braid.gate {\n            settings.evidenceFloor = decimal(gate.evidenceFloor)\n            settings.evidenceCeiling = decimal(gate.evidenceCeiling)\n            settings.shareRate = decimal(gate.shareRate)\n            settings.credibilityRate = decimal(gate.credibilityRate)\n            settings.commonsPrior = gate.commonsPrior.map(decimal) ?? 0.9\n        }\n        settings.openFloor = decimal(braid.gateFloor)\n        settings.evidence = braid.strands.contains(where: \\.isCommons) ? .lift : .absolute\n        return settings\n    }\n\n    /// A RaoLM Float setting as the decimal it was written as (0.3, not 0.30000001192092896), so a\n    /// constant RaoLM and Braid share reads as the same number and names the same gate fingerprint.\n    static func decimal(_ value: Float) -> Double { Double(\"\\(value)\") ?? Double(value) }\n\n    /// The strands as the session header names them.\n    public static func threads(_ g: RaoLMGeneration, braid: RaoLMBraid, pack: PackIdentity) -> [SessionThread] {\n        let lambdas = lambdas(g, braid: braid)\n        return braid.strands.enumerated().map { t, strand in\n            let nonEmpty: (String) -> String? = { $0.isEmpty ? nil : $0 }\n            let address = strand.address.map { $0.hasPrefix(\"urn:rao:thread:\") ? String($0.dropFirst(\"urn:rao:thread:\".count)) : $0 }\n            let descriptor = NodeDescriptor(\n                name: strand.name, label: strand.label, kind: strand.isCommons ? .commons : .thread, vocabularySHA256: braid.vocabularySHA256,\n                packSHA256: strand.isCommons ? nil : braid.packSHA256, hiddenSize: pack.hiddenSize, tokenizerSHA256: strand.manifest.tokenizerSHA256,\n                indexSHA256: strand.isCommons ? nil : nonEmpty(strand.manifest.indexSHA256), checkpointsSHA256: nil, versionSHA256: address,\n                corpusHash: nonEmpty(strand.manifest.corpusHash), threadID: strand.threadID, lane: nil, lambdaScale: strand.isCommons ? 0 : 1,\n                tau: g.params.tau)\n            return SessionThread(descriptor: descriptor, lambda: Float(lambdas[t]), rowOffset: strand.rowOffset, rowCount: strand.rowCount)\n        }\n    }\n\n    /// A session id that names the record: the same record imports to the same id.\n    public static func sessionID(set: String, file: String, generationID: String) -> String {\n        String(ContentHash.sha256Hex(\"raolm-import|\\(set)|\\(file)|\\(generationID)\").prefix(32))\n    }\n\n    /// The whole record as a session. `rule` is the trace rule the log names (RaoLM's standard).\n    public static func session(_ g: RaoLMGeneration, sessionID: String, pack: PackIdentity, ranges: [Range<Int>]? = nil,\n                               rule: TraceRule = .standard) throws -> ImportedSession {\n        guard let braid = g.braid, braid.gating == nil || braid.gating == \"braided\" else { throw Failure.notBraided(g.generationID) }\n        guard !braid.strands.isEmpty else { throw Failure.strands(\"\\(g.generationID) names no strands\") }\n        let commonsIndex = braid.strands.firstIndex(where: \\.isCommons)\n        let ranges = ranges ?? entryRanges(braid)\n        let gate = gateSettings(braid)\n        let threads = threads(g, braid: braid, pack: pack)\n        let header = SessionHeader(sessionID: sessionID, createdAt: g.createdAt, source: source, pack: pack, gate: gate, trace: rule, module: nil,\n                                   hitsLogged: g.params.k, threads: threads)\n        var params = GenerationParameters()\n        params.lambda = g.params.lambda\n        params.tau = g.params.tau\n        params.k = g.params.k\n        params.temperature = g.params.temperature\n        params.topK = g.params.topK\n        params.seed = g.params.seed\n        params.maxTokens = g.params.maxTokens\n        let prompt = GenerationPrompt(text: g.prompt.text, tokens: g.prompt.tokens.map { Int32($0) })\n        let gen = GenerationLine(generationID: g.generationID, prompt: prompt, context: nil, params: params, strands: braid.strands.map(\\.name))\n        let lambdas = lambdas(g, braid: braid)\n        let taus = threads.map { Double($0.tau) }\n\n        var steps: [Step] = []\n        if let first = (g.prompt.tokens + g.tokens).first {\n            steps.append(Step(index: 0, token: Int32(first), text: g.prompt.tokenTexts?.first ?? \"\", source: .prompt, prob: 1, lambda: g.params.lambda, threads: nil))\n        }\n        var missing = 0\n        for trace in g.traces {\n            guard let shares = trace.strands, shares.count == braid.strands.count else {\n                throw Failure.strands(\"trace \\(trace.index) of \\(g.generationID) has \\(trace.strands?.count ?? 0) strands for \\(braid.strands.count)\")\n            }\n            let y = trace.token\n            let gates = shares.map { Double($0.gate) }\n            let open = shares.map(\\.open)\n            let weights = Gate.renormalised(gates, open: open)\n            let hits = hits(trace, braid: braid, ranges: ranges)\n            let states = shares.map { traceState($0.trajectory, rule: rule) }\n            // The shadow β4 Braid logs beside its live gate, here over RaoLM's memory and trace.\n            let memory = shares.map { Double($0.memory ?? $0.gate) }\n            let shadowGates = Gate.shadowWeights(GateState(memoryOnly: memory, commons: commonsIndex), traces: states.map { Double($0?.trace ?? 0) },\n                                                 beta: gate.shadowBeta)\n            let shadowWeights = Gate.renormalised(shadowGates, open: open)\n            let alone = shares.map { $0.alone.map(Double.init) }\n            let shadowP = shares.indices.reduce(0.0) { $0 + (open[$1] ? shadowWeights[$1] * (alone[$1] ?? 0) : 0) }\n            var records: [ThreadRecord] = []\n            for t in shares.indices {\n                let share = shares[t]\n                let own = hits[t]\n                if own == nil { missing += 1 }\n                let knnWeights = Mixer.weights((own ?? []).map { Double($0.score) }, tau: taus[t])\n                var knn: [Int32: Double] = [:]\n                for (i, hit) in (own ?? []).enumerated() { knn[hit.value, default: 0] += knnWeights[i] }\n                var pknn = knn[Int32(y)] ?? 0\n                if own == nil, lambdas[t] > 0, let p = share.alone, let plm = share.lmProb {\n                    pknn = min(max((Double(p) - (1 - lambdas[t]) * Double(plm)) / lambdas[t], 0), 1)\n                }\n                let shadowShare = shadowP > 0 && open[t] ? shadowWeights[t] * (alone[t] ?? 0) / shadowP : 0\n                records.append(ThreadRecord(\n                    memory: Float(memory[t]), weight: Float(weights[t]), open: share.open, plm: share.lmProb, pknn: Float(pknn), share: share.share,\n                    hlm: share.lmEntropy, hknn: Float(Mixer.entropy(knn.values)), shadowGate: Float(shadowGates[t]), shadowShare: Float(shadowShare),\n                    hits: Array((own ?? []).prefix(g.params.k)), trace: states[t], gate: share.gate))\n            }\n            let candidates = (trace.candidates ?? []).map { Candidate(token: Int32($0.token), text: $0.text, prob: $0.prob, parts: $0.parts) }\n            steps.append(Step(index: trace.index, token: Int32(y), text: trace.text, source: trace.isPrompt ? .prompt : .gen, prob: trace.mixedProb,\n                              lambda: trace.lambda, threads: records, candidates: candidates))\n        }\n        let stoppedOn: StopReason? = g.stoppedOnEOS ? .eos : (g.params.maxTokens > 0 && g.tokens.count >= g.params.maxTokens ? .max : nil)\n        return ImportedSession(header: header, gen: gen, steps: steps, partitions: g.partitions.map(\\.partitionRef), text: g.text, generated: g.tokens.count,\n                               stoppedOn: stoppedOn, missingHits: missing)\n    }\n\n    // MARK: - What maps where\n\n    public struct FieldNote: Codable, Sendable, Equatable {\n        /// RaoLM's field, as its record names it.\n        public var raolm: String\n        /// The Braid field it becomes, or nil when it has none.\n        public var braid: String?\n        public var note: String\n    }\n\n    /// Every RaoLM field of a record and what the import does with it; then every Braid field RaoLM\n    /// never logged and how the import fills it.\n    public static let fieldNotes: [FieldNote] = [\n        // The record.\n        FieldNote(raolm: \"generationID\", braid: \"gen.generationID\", note: \"kept: RaoLM's id\"),\n        FieldNote(raolm: \"createdAt\", braid: \"header.createdAt\", note: \"kept\"),\n        FieldNote(raolm: \"version\", braid: nil, note: \"RaoLM's record version (1); the log is session schema \\(BraidVersion.sessionSchema)\"),\n        FieldNote(raolm: \"manifest\", braid: nil, note: \"the braid's combined manifest (runID braid:…, a combined index and corpus hash): no Braid field; each strand's own manifest maps per strand\"),\n        FieldNote(raolm: \"prompt.text, prompt.tokens\", braid: \"gen.prompt\", note: \"kept; RaoLM scored the text with no eos opener, so step 0 is its first token\"),\n        FieldNote(raolm: \"prompt.tokenTexts\", braid: \"tok.txt\", note: \"the first token's text goes on step 0; the rest ride on their traces\"),\n        FieldNote(raolm: \"prompt.source, prompt.question\", braid: nil, note: \"not decoded: the trajectory bench sets neither\"),\n        FieldNote(raolm: \"params.lambda, tau, k, temperature, topK, seed, maxTokens\", braid: \"gen.params\", note: \"kept\"),\n        FieldNote(raolm: \"params.rankThreshold, minSpanLength\", braid: nil, note: \"RaoLM's span settings: Braid's spans are a derived view with its own settings\"),\n        FieldNote(raolm: \"params.tapLayer, alpha\", braid: nil, note: \"RaoLM's key (tap layer and its mix with the final norm): Braid's key is the Mamba residual\"),\n        FieldNote(raolm: \"tokens, text, stoppedOnEOS\", braid: \"end.generated, end.text, end.stoppedOn\", note: \"kept (the trajectory bench generates nothing)\"),\n        FieldNote(raolm: \"partitions\", braid: \"end.partitions\", note: \"kept: the global rows the traces touch (thread partition id dropped: Braid has none)\"),\n        FieldNote(raolm: \"spans, summary\", braid: nil, note: \"not decoded: spans, citations and the summary are derived views in Braid (Spans.annotate)\"),\n        // The braid.\n        FieldNote(raolm: \"braid.strands[].name, label, threadID, rowOffset, rowCount, commons\", braid: \"header.threads[]\", note: \"kept\"),\n        FieldNote(raolm: \"braid.strands[].entryOffset\", braid: nil, note: \"used to map pooled global entries back to the node's own; not logged (Braid's hits are node-local)\"),\n        FieldNote(raolm: \"braid.strands[].manifest.indexSHA256, corpusHash, tokenizerSHA256\", braid: \"header.threads[].indexSHA256, corpusHash; pack.tokenizerSHA256\", note: \"kept (the commons' empty ones as nil)\"),\n        FieldNote(raolm: \"braid.strands[].address\", braid: \"header.threads[].versionSHA256\", note: \"the hex of urn:rao:thread:<sha256 of the version's manifest body>\"),\n        FieldNote(raolm: \"braid.strands[].manifest.checkpointSHA256, runID, epoch, ledgerSHA256; version; ownerKey\", braid: nil, note: \"listed per node in the import report: Braid's checkpointSHA256 names an index's state checkpoints, not a Thread's weights; epoch and version locate the RaoLM index\"),\n        FieldNote(raolm: \"braid.vocabularySHA256, packSHA256\", braid: \"header.pack\", note: \"kept; the pack's name, hidden size and vocabulary come from <dataRoot>/umbrella/<sha12>/ when present\"),\n        FieldNote(raolm: \"braid.gate.evidenceFloor, evidenceCeiling, shareRate, credibilityRate, commonsPrior; braid.gateFloor\", braid: \"header.gate\", note: \"kept (gateFloor as openFloor); evidence is lift with a commons\"),\n        FieldNote(raolm: \"braid.gate.agreement, credibility, share, generatedEvidence, trajectory, trajectoryBeta, ask, askFloor, thoughtAgreement; braid.gating\", braid: nil, note: \"RaoLM's gate switches (which arm made the record): no Braid setting; listed per set in the import report. Braid's gate fingerprint therefore does not tell RaoLM's arms apart\"),\n        // A trace.\n        FieldNote(raolm: \"traces[].index, token, text, isPrompt\", braid: \"tok.i, tok, txt, src\", note: \"kept: step i is trace i\"),\n        FieldNote(raolm: \"traces[].mixedProb\", braid: \"tok.p\", note: \"kept\"),\n        FieldNote(raolm: \"traces[].lambda\", braid: \"tok.lam\", note: \"kept: Σ w′_t·λ_t\"),\n        FieldNote(raolm: \"traces[].candidates\", braid: \"tok.cand\", note: \"kept\"),\n        FieldNote(raolm: \"traces[].lmEntropy, mixedEntropy, knnEntropy, sourceEntropy, threadEntropy, agreement\", braid: nil, note: \"mixture-level views (the mixture's reed and retrieval entropies, its p_knn of the token, the gate's spread): derived in Braid, not stored\"),\n        FieldNote(raolm: \"traces[].citations, uncited, confidence, spanIndex, role, bits, followed\", braid: nil, note: \"citations, spans, token roles and followed credit are derived views in Braid (Spans, TokenRoles, FollowedCredit)\"),\n        FieldNote(raolm: \"traces[].neighbours[]\", braid: \"tok.thr[t].hits\", note: \"split by strand by global entry; entry and cited row less the strand's offsets; ordered score desc, entry asc; sourceLoss as the hit's loss\"),\n        FieldNote(raolm: \"traces[].neighbours[].rank, weight, matches, key, sourceEntropy\", braid: nil, note: \"the pooled rank and weight, the match flag and the key position are derivable (the key from the node's index); the eval entropy has no Braid field\"),\n        // A strand at a trace.\n        FieldNote(raolm: \"strands[].memory\", braid: \"thr.mem\", note: \"kept: the braided gate's memory\"),\n        FieldNote(raolm: \"strands[].gate\", braid: \"thr.g\", note: \"kept: the gate the mixture renormalised (memory lifted by agreement, times the trace term in the β arms)\"),\n        FieldNote(raolm: \"strands[].open\", braid: \"thr.open\", note: \"kept: asked and mixed\"),\n        FieldNote(raolm: \"strands[].lmProb, lmEntropy\", braid: \"thr.plm, Hlm\", note: \"kept\"),\n        FieldNote(raolm: \"strands[].share\", braid: \"thr.share\", note: \"kept\"),\n        FieldNote(raolm: \"strands[].knn\", braid: nil, note: \"w′_t·p_knn,t(y), not p_knn: derivable as w′·p_knn\"),\n        FieldNote(raolm: \"strands[].alone\", braid: nil, note: \"p_t(y) = λ_t·p_knn + (1−λ_t)·p_lm: Braid recomputes it from plm, pknn and λ_t; used for p_knn where the hits are missing\"),\n        FieldNote(raolm: \"strands[].trajectory.length, entry, at, next\", braid: \"thr.tr.L, e, row, off, nx\", note: \"kept (node-local); tr.tr re-read from the length by the standard rule, as RaoLM's umbrella did\"),\n        FieldNote(raolm: \"strands[].trajectory.trace\", braid: nil, note: \"the node's own trace: equal to the rule's on the length (counted by --check)\"),\n        FieldNote(raolm: \"strands[].trajectory.phase, fit, arc, manner\", braid: nil, note: \"manner: deleted in Braid\"),\n        FieldNote(raolm: \"strands[].backs, thought\", braid: nil, note: \"RaoLM's agreement and thought lifts: inside thr.g, no Braid field\"),\n        FieldNote(raolm: \"strands[].lift\", braid: nil, note: \"log p_t − log p_commons: derived in Braid\"),\n        FieldNote(raolm: \"strands[].credit\", braid: nil, note: \"RaoLM's token-role credit: a derived view in Braid (Credit.assign)\"),\n        FieldNote(raolm: \"strands[].bestScore, threadID, strand\", braid: nil, note: \"the best score is the first hit's; the name and thread id are the header's\"),\n        // Braid fields RaoLM never logged.\n        FieldNote(raolm: \"—\", braid: \"thr.w\", note: \"derived: the gate renormalised over the open strands\"),\n        FieldNote(raolm: \"—\", braid: \"thr.pknn\", note: \"derived: softmax(score/τ) mass of the strand's own hits on the token; where the record lacks the hits, (alone − (1−λ)·plm)/λ\"),\n        FieldNote(raolm: \"—\", braid: \"thr.Hknn\", note: \"derived: the entropy of the strand's own retrieval distribution from its hits and τ; 0 where the record lacks the hits\"),\n        FieldNote(raolm: \"—\", braid: \"thr.sg, thr.ss\", note: \"derived: Braid's shadow β4 (memory·exp(β·(trace − mean)), renormalised over the open strands) over RaoLM's memory and trace; RaoLM ran no shadow\"),\n        FieldNote(raolm: \"—\", braid: \"thr.ev, thr.mod\", note: \"nil: RaoLM logged no bounded evidence and had no trajectory module\"),\n        FieldNote(raolm: \"—\", braid: \"thr.tr.pr\", note: \"0: RaoLM kept no partition-bounded run\"),\n        FieldNote(raolm: \"—\", braid: \"header.hitsLogged\", note: \"params.k: RaoLM pooled every hit of an open strand\"),\n    ]\n}\n"},{"path":"Sources/BraidCore/Port/RaoLMIndex.swift","lines":109,"bytes":6281,"header":{"lines":[1,16],"what":[8,13],"pin":[14,15],"in":null,"out":null},"marks":[],"first":202,"scopes":[["S","RaoLMIndex",null,"public",20,20,[20,35],109,null,-1,0],["E","Failure",null,"public",21,21,[21,56],34,null,0,0,["missing","sha256","shape"]],["v","description",null,"public",26,26,[26,39],33,null,1,0],["S","Info",null,"",37,37,[37,27],42,[36,36],0,0],["v","count",null,"public",49,49,[49,26],49,null,0,8],["f","directory",["dataRoot","node","version","epoch"],"public static",52,52,[52,95],56,[51,51],0,0],["f","load",["directory","node","expectedSHA256"],"public static",59,59,[59,110],76,[58,58],0,0],["f","load",["strand","dataRoot"],"public static",80,80,[80,88],83,[78,79],0,0],["f","find",["dataRoot","node","sha256"],"public static",87,87,[87,95],103,[85,86],0,0],["v","documentOfRow",null,"public",106,106,[106,46],108,[105,105],0,0]],"text":"//\n//  RaoLMIndex.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: A RaoLM node's provenance index as the trace needs it, read with no MLX: the values, key\n//        rows and key offsets from index.safetensors, the node's partition table from\n//        partitions.json and the paragraph break from index.json (what RaoLM's TrajectoryCorpus\n//        reads; its tracker reads nothing else — shared n-grams and the keys serve spans and\n//        retrieval only). Found under a RaoLM data root as RaoLM lays a version out:\n//        nodes/<name>/versions/v<NNNN>/provenance/epoch-<E>/.\n//  PIN:  The file's SHA-256 is RaoLM's index sha256 (its manifest's `indexSHA256`); a layout is\n//        used only when they agree.\n//\n\nimport Foundation\n\npublic struct RaoLMIndex: Sendable {\n    public enum Failure: Error, CustomStringConvertible {\n        case missing(String)\n        case sha256(directory: String, expected: String, found: String)\n        case shape(String)\n\n        public var description: String {\n            switch self {\n            case .missing(let what): return \"RaoLM index: \\(what)\"\n            case .sha256(let directory, let expected, let found):\n                return \"RaoLM index at \\(directory) hashes to \\(found.prefix(12)), the record names \\(expected.prefix(12))\"\n            case .shape(let detail): return \"RaoLM index: \\(detail)\"\n            }\n        }\n    }\n\n    /// RaoLM's index.json, as far as the trace reads it.\n    struct Info: Decodable {\n        var count: Int?\n        var epoch: Int?\n        var paragraphBreak: [Int]?\n        var tokenizerSHA256: String?\n    }\n\n    public var node: String\n    public var directory: URL\n    public var sha256: String\n    public var layout: IndexLayout\n\n    public var count: Int { layout.values.count }\n\n    /// `<dataRoot>/nodes/<node>/versions/v<NNNN>/provenance/epoch-<epoch>/`.\n    public static func directory(dataRoot: URL, node: String, version: Int, epoch: Int) -> URL {\n        dataRoot.appendingPathComponent(\"nodes\", isDirectory: true).appendingPathComponent(node, isDirectory: true)\n            .appendingPathComponent(\"versions\", isDirectory: true).appendingPathComponent(String(format: \"v%04d\", version), isDirectory: true)\n            .appendingPathComponent(\"provenance\", isDirectory: true).appendingPathComponent(\"epoch-\\(epoch)\", isDirectory: true)\n    }\n\n    /// Loads one index directory; refuses it when `expectedSHA256` is given and the file's differs.\n    public static func load(directory: URL, node: String, expectedSHA256: String? = nil) throws -> RaoLMIndex {\n        let file = directory.appendingPathComponent(\"index.safetensors\")\n        guard FileManager.default.fileExists(atPath: file.path) else { throw Failure.missing(\"no index.safetensors in \\(directory.path)\") }\n        let tensors = try SafetensorsFile(url: file)\n        let sha256 = tensors.sha256\n        if let expectedSHA256, expectedSHA256 != sha256 { throw Failure.sha256(directory: directory.path, expected: expectedSHA256, found: sha256) }\n        let values = try tensors.int32(\"values\")\n        let keyRow = try tensors.int32(\"key_row\")\n        let keyOffset = try tensors.int32(\"key_offset\")\n        guard values.count == keyRow.count, values.count == keyOffset.count else {\n            throw Failure.shape(\"\\(values.count) values, \\(keyRow.count) key rows, \\(keyOffset.count) key offsets\")\n        }\n        let info = try JSONCoding.read(Info.self, from: directory.appendingPathComponent(\"index.json\"))\n        if let count = info.count, count != values.count { throw Failure.shape(\"index.json counts \\(count) entries, the arrays hold \\(values.count)\") }\n        let partitions = try JSONCoding.read([RaoLMPartition].self, from: directory.appendingPathComponent(\"partitions.json\")).map(\\.partitionRef)\n        let layout = IndexLayout(values: values, keyRow: keyRow, keyOffset: keyOffset, partitions: partitions, breakLength: info.paragraphBreak?.count ?? 0)\n        return RaoLMIndex(node: node, directory: directory, sha256: sha256, layout: layout)\n    }\n\n    /// The index a strand of a RaoLM record names: its version and epoch under `dataRoot`, checked\n    /// against the record's index sha256.\n    public static func load(strand: RaoLMStrandRef, dataRoot: URL) throws -> RaoLMIndex {\n        let directory = directory(dataRoot: dataRoot, node: strand.name, version: strand.version, epoch: strand.manifest.epoch)\n        return try load(directory: directory, node: strand.name, expectedSHA256: strand.manifest.indexSHA256)\n    }\n\n    /// Scans every version and epoch of `node` under `dataRoot` for the index whose SHA-256 is\n    /// `sha256` (a session header names the sha, not the epoch). Nil when none is.\n    public static func find(dataRoot: URL, node: String, sha256: String) throws -> RaoLMIndex? {\n        let versions = dataRoot.appendingPathComponent(\"nodes\", isDirectory: true).appendingPathComponent(node, isDirectory: true)\n            .appendingPathComponent(\"versions\", isDirectory: true)\n        let manager = FileManager.default\n        guard let names = try? manager.contentsOfDirectory(atPath: versions.path) else { return nil }\n        for version in names.sorted() where version.hasPrefix(\"v\") && !version.hasPrefix(\"._\") {\n            let provenance = versions.appendingPathComponent(version, isDirectory: true).appendingPathComponent(\"provenance\", isDirectory: true)\n            guard let epochs = try? manager.contentsOfDirectory(atPath: provenance.path) else { continue }\n            for epoch in epochs.sorted() where epoch.hasPrefix(\"epoch-\") {\n                let directory = provenance.appendingPathComponent(epoch, isDirectory: true)\n                let file = directory.appendingPathComponent(\"index.safetensors\")\n                guard manager.fileExists(atPath: file.path), (try? ContentHash.sha256Hex(fileAt: file)) == sha256 else { continue }\n                return try load(directory: directory, node: node, expectedSHA256: sha256)\n            }\n        }\n        return nil\n    }\n\n    /// Row → document id, for the wire audit.\n    public var documentOfRow: [Int32: String] {\n        Dictionary(layout.partitions.map { (Int32($0.row), $0.documentID) }, uniquingKeysWith: { first, _ in first })\n    }\n}\n"},{"path":"Sources/BraidCore/Port/RaoLMPort.swift","lines":369,"bytes":18355,"header":{"lines":[1,19],"what":[8,13],"pin":[17,18],"in":null,"out":[14,16]},"marks":[[82,"The nodes"],[122,"One pass"],[235,"Reports"]],"first":212,"scopes":[["E","RaoLMPort",null,"public",23,23,[23,22],360,null,-1,0,[]],["E","Failure",null,"public",24,24,[24,56],36,null,0,0,["noSet","noRecords","mixedIndexes"]],["v","description",null,"public",29,29,[29,39],35,null,1,0],["S","RecordSet",null,"public",39,39,[39,49],52,[38,38],0,0],["v","complete",null,"public",49,49,[49,34],49,null,3,8],["v","outputDirectory",null,"public",51,51,[51,43],51,[50,50],3,8],["f","sets",["dump","index"],"public static",56,56,[56,77],71,[54,55],0,0],["f","missing",["_","_"],"",58,58,[58,80],64,null,6,4],["f","select",["_","only"],"public static",75,75,[75,88],80,[73,74],0,0],["S","NodeIndex",null,"public",85,85,[85,58],103,[84,84],0,0],["f","indexes",["of","dataRoot"],"public static",106,106,[106,99],110,[105,105],0,0],["f","nodeRecords",["_","indexes"],"public static",112,112,[112,102],120,null,0,0],["S","Outcome",null,"public",125,125,[125,36],138,[124,124],0,0],["S","VerifyTally",null,"public",141,141,[141,60],159,[140,140],0,0],["i","init",[],"public",149,149,[149,22],149,null,13,8],["f","add",["_"],"public mutating",151,151,[151,55],158,null,13,0],["E","Mode",null,"public",161,161,[161,31],166,null,0,0,["write","check"]],["f","parallel",["_","jobs","_"],"static",169,169,[169,110],185,[168,168],0,0],["f","run",["set","dump","indexes","dataRoot","mode","rule","jobs","progress"],"public static",188,188,[189,102],233,[187,187],0,0],["S","SetReport",null,"public",238,238,[238,47],274,[237,237],0,0],["i","init",["set","outcomes"],"public",253,253,[253,57],273,null,19,0],["S","ImportReport",null,"public",291,291,[291,50],343,[290,290],0,0],["S","SetSummary",null,"public",301,301,[301,52],319,null,21,0],["i","init",["_"],"public",310,310,[310,45],318,null,22,0],["i","init",["createdAt","dump","dataRoot","nodes","sets"],"public",321,321,[321,109],329,null,21,0],["f","find",["near"],"public static",334,334,[334,71],342,[333,333],21,0],["f","layouts",["for","report"],"public static",347,347,[347,113],359,[345,346],0,0],["C","ParallelResults",null,"final",363,363,[363,62],369,[362,362],-1,0],["i","init",["_"],"",368,368,[368,23],368,null,27,8]],"text":"//\n//  RaoLMPort.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The port validation's runner over a RaoLM trajectory-bench dump: its sets (the base pass\n//        and each gate arm whose files are complete), the RaoLM node indexes its records name, and\n//        one pass over every record that either writes it as a Braid session log (`import`) or\n//        checks it (`check`: the shares, the mapping onto each node's index, the trace replay, and\n//        `braid verify`'s arithmetic and trace replay on the imported session, keeping what phase A\n//        reads of each record).\n//  OUT:  Under the output directory: `base/<record>.jsonl`, `arms/<slug>/<record>.jsonl` and\n//        `import.json` (what was imported from where, the field notes, which verify checks apply);\n//        or the check's report.\n//  PIN:  Pure Swift and Foundation: no model, no GPU. Records are decoded `jobs` at a time and\n//        dropped once read; nothing is written outside the output directory.\n//\n\nimport Foundation\n\npublic enum RaoLMPort {\n    public enum Failure: Error, CustomStringConvertible {\n        case noSet(String, known: [String])\n        case noRecords(String)\n        case mixedIndexes(String)\n\n        public var description: String {\n            switch self {\n            case .noSet(let name, let known): return \"the dump has no set \\(name) (known: \\(known.joined(separator: \", \")))\"\n            case .noRecords(let detail): return \"no records: \\(detail)\"\n            case .mixedIndexes(let detail): return \"the records do not name one index per node: \\(detail)\"\n            }\n        }\n    }\n\n    /// One set of records: the base pass or one gate arm.\n    public struct RecordSet: Sendable, Equatable {\n        /// \"base\", or the arm's name as RaoLM wrote it (\"both β4\").\n        public var name: String\n        /// Relative to the dump (\"\" for the base pass, \"arms/both-beta4\").\n        public var directory: String\n        /// The texts it should hold.\n        public var texts: [RaoLMDumpText]\n        /// Expected files not there (or empty): a set is used only when none is missing.\n        public var missing: [String]\n\n        public var complete: Bool { missing.isEmpty }\n        /// Where its logs go under the output directory.\n        public var outputDirectory: String { directory.isEmpty ? \"base\" : directory }\n    }\n\n    /// The base pass and every arm, with what each is missing. An arm holds RaoLM's told and source\n    /// texts with answers (the texts its arm loop scored).\n    public static func sets(dump: URL, index: RaoLMDumpIndex) -> [RecordSet] {\n        let manager = FileManager.default\n        func missing(_ directory: String, _ texts: [RaoLMDumpText]) -> [String] {\n            texts.compactMap { text in\n                let url = dump.appendingPathComponent(directory, isDirectory: true).appendingPathComponent(text.file)\n                let size = (try? manager.attributesOfItem(atPath: url.path)[.size] as? NSNumber)?.intValue ?? 0\n                return size > 0 ? nil : text.file\n            }\n        }\n        var sets = [RecordSet(name: \"base\", directory: \"\", texts: index.texts, missing: missing(\"\", index.texts))]\n        let retold = index.texts.filter { ($0.kind == \"told\" || $0.kind == \"source\") && !$0.answers.isEmpty }\n        for (name, directory) in index.arms.sorted(by: { $0.key < $1.key }) {\n            sets.append(RecordSet(name: name, directory: directory, texts: retold, missing: missing(directory, retold)))\n        }\n        return sets\n    }\n\n    /// The sets `only` names (\"base\", an arm's name, or its directory's last component), or every\n    /// complete set when nil.\n    public static func select(_ sets: [RecordSet], only: String?) throws -> [RecordSet] {\n        guard let only else { return sets.filter(\\.complete) }\n        let wanted = sets.filter { $0.name == only || $0.directory == only || ($0.directory as NSString).lastPathComponent == only }\n        guard let set = wanted.first else { throw Failure.noSet(only, known: sets.map(\\.name)) }\n        return [set]\n    }\n\n    // MARK: - The nodes\n\n    /// One RaoLM node index the records name, as the import report and `braid verify` find it.\n    public struct NodeIndex: Codable, Sendable, Equatable {\n        public var name: String\n        public var label: String\n        public var version: Int\n        public var epoch: Int\n        public var directory: String\n        public var sha256: String\n        public var entries: Int\n        public var entryOffset: Int\n        public var rowOffset: Int\n        public var rowCount: Int\n        /// RaoLM's own record of the version, with no Braid field (Braid's checkpointSHA256 names an\n        /// index's state checkpoints, not a Thread's weights).\n        public var runID: String\n        public var checkpointSHA256: String\n        public var ledgerSHA256: String?\n        public var address: String?\n        public var ownerKey: String?\n    }\n\n    /// The RaoLM indexes of a record's Thread strands under `dataRoot`, each checked against its sha.\n    public static func indexes(of braid: RaoLMBraid, dataRoot: URL) throws -> [String: RaoLMIndex] {\n        var result: [String: RaoLMIndex] = [:]\n        for strand in braid.strands where !strand.isCommons { result[strand.name] = try RaoLMIndex.load(strand: strand, dataRoot: dataRoot) }\n        return result\n    }\n\n    public static func nodeRecords(_ braid: RaoLMBraid, indexes: [String: RaoLMIndex]) -> [NodeIndex] {\n        braid.strands.filter { !$0.isCommons }.compactMap { strand in\n            guard let index = indexes[strand.name] else { return nil }\n            return NodeIndex(name: strand.name, label: strand.label, version: strand.version, epoch: strand.manifest.epoch, directory: index.directory.path,\n                             sha256: index.sha256, entries: index.count, entryOffset: strand.entryOffset, rowOffset: strand.rowOffset, rowCount: strand.rowCount,\n                             runID: strand.manifest.runID, checkpointSHA256: strand.manifest.checkpointSHA256, ledgerSHA256: strand.manifest.ledgerSHA256,\n                             address: strand.address, ownerKey: strand.ownerKey)\n        }\n    }\n\n    // MARK: - One pass\n\n    /// What one record gave the check.\n    public struct Outcome: Sendable {\n        public var set: String\n        public var text: RaoLMDumpText\n        public var steps = 0\n        public var missingHits = 0\n        public var shares = RaoLMCheck.Shares()\n        public var mapping = RaoLMCheck.Mapping()\n        public var traces = RaoLMCheck.Traces()\n        public var verify = VerifyTally()\n        public var scored: RaoLMCheck.ScoredText?\n        public var gate: RaoLMGate?\n        public var indexSHA256: [String: String] = [:]\n        public var error: String?\n    }\n\n    /// `braid verify` on the imported sessions, spans aside (RaoLM's partitions are in no Braid snapshot).\n    public struct VerifyTally: Codable, Sendable, Equatable {\n        public var logs = 0\n        public var issues = 0\n        public var traceMismatches = 0\n        public var traceUnreplayable = 0\n        public var firstIssues: [String] = []\n        public var skipped: [String] = []\n\n        public init() {}\n\n        public mutating func add(_ other: VerifyTally) {\n            logs += other.logs\n            issues += other.issues\n            traceMismatches += other.traceMismatches\n            traceUnreplayable += other.traceUnreplayable\n            firstIssues += other.firstIssues.prefix(max(0, 20 - firstIssues.count))\n            for skip in other.skipped where !skipped.contains(skip) { skipped.append(skip) }\n        }\n    }\n\n    public enum Mode: Sendable {\n        /// Write every record as a session log under the directory.\n        case write(URL)\n        /// Check every record.\n        case check\n    }\n\n    /// Runs `body` over 0..<count with at most `jobs` at a time, results in order.\n    static func parallel<T: Sendable>(_ count: Int, jobs: Int, _ body: @escaping @Sendable (Int) -> T) -> [T] {\n        let box = ParallelResults<T>(count)\n        DispatchQueue.concurrentPerform(iterations: max(1, min(jobs, count))) { _ in\n            while true {\n                box.lock.lock()\n                let i = box.next\n                box.next += 1\n                box.lock.unlock()\n                guard i < count else { return }\n                let value = body(i)\n                box.lock.lock()\n                box.results[i] = value\n                box.lock.unlock()\n            }\n        }\n        return box.results.map { $0! }\n    }\n\n    /// One pass over a set: each record decoded, imported, and written or checked.\n    public static func run(set: RecordSet, dump: URL, indexes: [String: RaoLMIndex], dataRoot: URL, mode: Mode, rule: TraceRule = .standard,\n                           jobs: Int = 4, progress: (@Sendable (String) -> Void)? = nil) -> [Outcome] {\n        let layouts = indexes.mapValues(\\.layout)\n        let corpora = layouts.mapValues(\\.corpus)\n        let documents = indexes.mapValues(\\.documentOfRow)\n        let counts = indexes.mapValues(\\.count)\n        let texts = set.texts\n        let base = dump.appendingPathComponent(set.directory, isDirectory: true)\n        return parallel(texts.count, jobs: jobs) { i -> Outcome in\n            let text = texts[i]\n            var outcome = Outcome(set: set.name, text: text)\n            do {\n                let g = try RaoLMGeneration.load(from: base.appendingPathComponent(text.file))\n                guard let braid = g.braid else { throw RaoLMImport.Failure.notBraided(g.generationID) }\n                outcome.gate = braid.gate\n                for strand in braid.strands where !strand.isCommons { outcome.indexSHA256[strand.name] = strand.manifest.indexSHA256 }\n                let ranges = RaoLMImport.entryRanges(braid, counts: counts)\n                let id = RaoLMImport.sessionID(set: set.outputDirectory, file: text.file, generationID: g.generationID)\n                let imported = try RaoLMImport.session(g, sessionID: id, pack: RaoLMImport.pack(g, dataRoot: dataRoot), ranges: ranges, rule: rule)\n                outcome.steps = imported.steps.count\n                outcome.missingHits = imported.missingHits\n                switch mode {\n                case .write(let out):\n                    let stem = (text.file as NSString).deletingPathExtension\n                    try imported.write(to: out.appendingPathComponent(set.outputDirectory, isDirectory: true).appendingPathComponent(stem + \".jsonl\"))\n                case .check:\n                    outcome.shares = RaoLMCheck.shares(g, file: text.file, ranges: ranges)\n                    outcome.mapping = RaoLMCheck.mapping(g, layouts: layouts, ranges: ranges, rule: rule)\n                    let replay = RaoLMCheck.replay(g, corpora: corpora, ranges: ranges, rule: rule)\n                    outcome.traces = RaoLMCheck.traces(g, replay: replay, set: set.name, file: text.file, rule: rule)\n                    outcome.scored = RaoLMCheck.scoredText(g, file: text.file, replay: replay, imported: imported, documentOfRow: documents)\n                    let report = Verifier.verify(session: try imported.logged(), name: text.file, layouts: { layouts[$0] }, reader: nil, tokenizer: nil)\n                    outcome.verify.logs = 1\n                    outcome.verify.issues = report.issues.count\n                    outcome.verify.firstIssues = report.issues.prefix(3).map { \"\\(text.file): \\($0)\" }\n                    outcome.verify.traceMismatches = report.traces.reduce(0) { $0 + $1.mismatches }\n                    outcome.verify.traceUnreplayable = report.traces.reduce(0) { $0 + $1.unreplayable }\n                    outcome.verify.skipped = report.skipped\n                }\n            } catch {\n                outcome.error = \"\\(text.file): \\(error)\"\n            }\n            if i % 50 == 49 { progress?(\"\\(set.name): \\(i + 1)/\\(texts.count)\") }\n            return outcome\n        }\n    }\n\n    // MARK: - Reports\n\n    /// A set's totals.\n    public struct SetReport: Codable, Sendable {\n        public var name: String\n        public var directory: String\n        public var expected: Int\n        public var records: Int\n        public var steps: Int\n        public var missingHits: Int\n        public var errors: [String]\n        /// RaoLM's gate for the set (its arm's switches), as the first record names it.\n        public var gate: RaoLMGate?\n        public var shares: RaoLMCheck.Shares\n        public var mapping: RaoLMCheck.Mapping\n        public var traces: RaoLMCheck.Traces\n        public var verify: VerifyTally\n\n        public init(set: RecordSet, outcomes: [Outcome]) {\n            name = set.name\n            directory = set.outputDirectory\n            expected = set.texts.count\n            records = outcomes.filter { $0.error == nil }.count\n            steps = outcomes.reduce(0) { $0 + $1.steps }\n            missingHits = outcomes.reduce(0) { $0 + $1.missingHits }\n            errors = outcomes.compactMap(\\.error) + set.missing.map { \"missing \\($0)\" }\n            gate = outcomes.lazy.compactMap(\\.gate).first\n            var shares = RaoLMCheck.Shares(), mapping = RaoLMCheck.Mapping(), traces = RaoLMCheck.Traces(), verify = VerifyTally()\n            for outcome in outcomes {\n                shares.add(outcome.shares)\n                mapping.add(outcome.mapping)\n                traces.add(outcome.traces)\n                verify.add(outcome.verify)\n            }\n            self.shares = shares\n            self.mapping = mapping\n            self.traces = traces\n            self.verify = verify\n        }\n    }\n\n    /// Which of `braid verify`'s checks an imported log takes, in words, for the reports.\n    public static let verifyChecks: [String: String] = [\n        \"body\": \"applies: the importer writes the end line's hash like any log\",\n        \"shares sum to 1\": \"applies\",\n        \"weights\": \"applies: w′ from the logged gate (thr.g, RaoLM's gate) and the open set\",\n        \"p and shares\": \"applies: from w′ and each strand's p_lm, p_knn and λ\",\n        \"H_knn\": \"applies: from each strand's hits and τ (0 where the record lacks its hits)\",\n        \"trace\": \"applies over RaoLM's index layout; a mismatch after a position whose hits the record lacks is counted unreplayable, not failed\",\n        \"memory recursion\": \"skipped: it replays Braid's live gate, and RaoLM's memory was moved by RaoLM's gate code (in Float, under switches Braid has not); `import-raolm --check` measures Braid's Gate.observe against it instead (phase A)\",\n        \"shadow β4\": \"skipped: RaoLM ran no shadow; the importer derived sg/ss from RaoLM's memory and trace\",\n        \"spans\": \"skipped: RaoLM's partitions are in no Braid snapshot or lane, and the tokenizer is RaoLM's\",\n        \"keys\": \"refused: a RaoLM key cannot be recomputed from a Mamba checkpoint\",\n    ]\n\n    /// `import.json`: what an import wrote, from where, and how to read it.\n    public struct ImportReport: Codable, Sendable {\n        public var source = RaoLMImport.source\n        public var createdAt: Date\n        public var dump: String\n        public var dataRoot: String\n        public var nodes: [NodeIndex]\n        public var sets: [SetSummary]\n        public var verifyChecks: [String: String]\n        public var fieldNotes: [RaoLMImport.FieldNote]\n\n        public struct SetSummary: Codable, Sendable {\n            public var name: String\n            public var directory: String\n            public var records: Int\n            public var steps: Int\n            public var missingHits: Int\n            public var errors: [String]\n            public var gate: RaoLMGate?\n\n            public init(_ report: SetReport) {\n                name = report.name\n                directory = report.directory\n                records = report.records\n                steps = report.steps\n                missingHits = report.missingHits\n                errors = report.errors\n                gate = report.gate\n            }\n        }\n\n        public init(createdAt: Date, dump: String, dataRoot: String, nodes: [NodeIndex], sets: [SetSummary]) {\n            self.createdAt = createdAt\n            self.dump = dump\n            self.dataRoot = dataRoot\n            self.nodes = nodes\n            self.sets = sets\n            verifyChecks = RaoLMPort.verifyChecks\n            fieldNotes = RaoLMImport.fieldNotes\n        }\n\n        public static let fileName = \"import.json\"\n\n        /// The import report beside a log: in its directory or up to three above it.\n        public static func find(near log: URL) -> (ImportReport, URL)? {\n            var directory = log.deletingLastPathComponent()\n            for _ in 0..<4 {\n                let url = directory.appendingPathComponent(fileName)\n                if let report = try? JSONCoding.read(ImportReport.self, from: url), report.source == RaoLMImport.source { return (report, url) }\n                directory.deleteLastPathComponent()\n            }\n            return nil\n        }\n    }\n\n    /// The layouts `braid verify` replays an imported log's traces over: each Thread strand's RaoLM\n    /// index, found by its sha under the import's data root (the node records first).\n    public static func layouts(for session: LoggedSession, report: ImportReport) throws -> [String: IndexLayout] {\n        var layouts: [String: IndexLayout] = [:]\n        for thread in session.header.threads where !thread.commons {\n            guard let sha = thread.indexSHA256 else { continue }\n            if let node = report.nodes.first(where: { $0.sha256 == sha }),\n               let index = try? RaoLMIndex.load(directory: URL(fileURLWithPath: node.directory, isDirectory: true), node: thread.name, expectedSHA256: sha) {\n                layouts[thread.name] = index.layout\n            } else if let index = try RaoLMIndex.find(dataRoot: URL(fileURLWithPath: report.dataRoot, isDirectory: true), node: thread.name, sha256: sha) {\n                layouts[thread.name] = index.layout\n            }\n        }\n        return layouts\n    }\n}\n\n/// The shared cursor and results of `RaoLMPort.parallel`, under one lock.\nfinal class ParallelResults<T: Sendable>: @unchecked Sendable {\n    let lock = NSLock()\n    var next = 0\n    var results: [T?]\n\n    init(_ count: Int) { results = [T?](repeating: nil, count: count) }\n}\n"},{"path":"Sources/BraidCore/Port/RaoLMRecords.swift","lines":349,"bytes":12081,"header":{"lines":[1,18],"what":[8,13],"pin":[14,17],"in":null,"out":null},"marks":[[227,"The dump and RaoLM's report"]],"first":241,"scopes":[["S","RaoLMPosition",null,"public",22,22,[22,58],25,null,-1,0],["S","RaoLMManifest",null,"public",27,27,[27,58],36,null,-1,0],["S","RaoLMPartition",null,"public",38,38,[38,59],56,null,-1,0],["v","partitionRef",null,"public",52,52,[52,42],55,[51,51],2,0],["S","RaoLMPrompt",null,"public",58,58,[58,56],62,null,-1,0],["S","RaoLMParameters",null,"public",64,64,[64,60],76,null,-1,0],["S","RaoLMNeighbour",null,"public",79,79,[79,59],94,[78,78],-1,0],["S","RaoLMTrajectory",null,"public",97,97,[97,60],108,[96,96],-1,0],["S","RaoLMStrandShare",null,"public",111,111,[111,61],132,[110,110],-1,0],["S","RaoLMCandidate",null,"public",134,134,[134,59],139,null,-1,0],["S","RaoLMTrace",null,"public",142,142,[142,55],164,[141,141],-1,0],["S","RaoLMGate",null,"public",167,167,[167,54],182,[166,166],-1,0],["S","RaoLMStrandRef",null,"public",184,184,[184,59],198,null,-1,0],["v","isCommons",null,"public",197,197,[197,31],197,null,12,8],["S","RaoLMBraid",null,"public",200,200,[200,55],207,null,-1,0],["S","RaoLMGeneration",null,"public",210,210,[210,60],225,[209,209],-1,0],["f","load",["from"],"public static",224,224,[224,69],224,null,15,8],["S","RaoLMAnswer",null,"public",229,229,[229,56],233,null,-1,0],["S","RaoLMDumpText",null,"public",236,236,[236,58],257,[235,235],-1,0],["v","answerPositions",null,"public",249,249,[249,38],256,[247,248],18,0],["S","RaoLMDumpIndex",null,"public",260,260,[260,59],269,[259,259],-1,0],["f","load",["from"],"public static",268,268,[268,69],268,null,20,8],["S","RaoLMTrajectoryReport",null,"public",272,272,[272,55],349,[271,271],-1,0],["S","Reading",null,"public",273,273,[273,56],284,null,22,0],["S","Text",null,"public",286,286,[286,53],293,null,22,0],["S","Arm",null,"public",295,295,[295,52],304,null,22,0],["S","Rule",null,"public",306,306,[306,53],310,null,22,0],["S","Evaluation",null,"public",312,312,[312,48],318,null,22,0],["S","Constants",null,"public",320,320,[320,58],326,null,22,0],["f","load",["from"],"public static",337,337,[337,75],337,null,22,8],["v","traceRule",null,"public",340,340,[340,36],348,[339,339],22,0]],"text":"//\n//  RaoLMRecords.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: RaoLM's records as its trajectory bench dumped them, decoded as written: a scored text's\n//        CitedGeneration (RaoLM/Sources/RaoLMCore/Citation/CitationModels.swift and Braid/\n//        BraidModels.swift), the dump's index.json, and RaoLM's trajectory report. Only what the\n//        import, the port validation and phase A read is declared; everything else in a record\n//        (citations, spans, summary, a trace's span index, a prompt's source and question) is\n//        skipped by the decoder and listed in the import report.\n//  PIN:  Field names are RaoLM's. Optional wherever RaoLM's own type is optional or a later RaoLM\n//        added the field, so a record from either decodes. Entries and rows in a record are global\n//        (a strand's entryOffset and rowOffset added); a trajectory's entry and position are the\n//        node's own.\n//\n\nimport Foundation\n\npublic struct RaoLMPosition: Codable, Sendable, Equatable {\n    public var row: Int\n    public var offset: Int\n}\n\npublic struct RaoLMManifest: Codable, Sendable, Equatable {\n    public var runID: String\n    public var epoch: Int\n    public var checkpointSHA256: String\n    public var indexSHA256: String\n    public var corpusHash: String\n    public var tokenizerSHA256: String\n    public var ledgerSHA256: String?\n    public var threadID: String?\n}\n\npublic struct RaoLMPartition: Codable, Sendable, Equatable {\n    public var row: Int\n    public var documentID: String\n    public var documentName: String\n    public var partitionIndex: Int\n    public var partitionURL: String?\n    public var threadPartitionID: String?\n    public var textSHA256: String\n    public var tokenCount: Int\n    public var memorisedAtEpoch: Int?\n    public var threadID: String?\n    public var createdAt: Int64?\n\n    /// Braid's partition row (RaoLM's thread partition id has no Braid field).\n    public var partitionRef: PartitionRef {\n        PartitionRef(row: row, documentID: documentID, documentName: documentName, partitionIndex: partitionIndex, partitionURL: partitionURL,\n                     textSHA256: textSHA256, tokenCount: tokenCount, memorisedAtEpoch: memorisedAtEpoch, threadID: threadID, createdAt: createdAt)\n    }\n}\n\npublic struct RaoLMPrompt: Codable, Sendable, Equatable {\n    public var text: String\n    public var tokens: [Int]\n    public var tokenTexts: [String]?\n}\n\npublic struct RaoLMParameters: Codable, Sendable, Equatable {\n    public var lambda: Float\n    public var tau: Float\n    public var k: Int\n    public var rankThreshold: Int\n    public var minSpanLength: Int\n    public var temperature: Float\n    public var topK: Int\n    public var seed: UInt64\n    public var maxTokens: Int\n    public var tapLayer: Int\n    public var alpha: Float\n}\n\n/// One retrieved corpus position for one token, as RaoLM pooled it across Threads.\npublic struct RaoLMNeighbour: Codable, Sendable, Equatable {\n    /// 1-based rank in the pool (by pooled weight).\n    public var rank: Int\n    /// Global entry: the strand's entryOffset plus its own entry.\n    public var entry: Int\n    public var score: Float\n    /// The pooled weight: the strand's retrieval weight times softmax(score/τ) within the strand.\n    public var weight: Float\n    public var value: Int\n    public var matches: Bool\n    /// Global rows.\n    public var key: RaoLMPosition\n    public var cited: RaoLMPosition\n    public var sourceLoss: Float\n    public var sourceEntropy: Float\n}\n\n/// A Thread's retrieval trajectory at the position that predicts the token (node-local entry and row).\npublic struct RaoLMTrajectory: Codable, Sendable, Equatable {\n    public var length: Int\n    public var trace: Float\n    public var entry: Int?\n    public var at: RaoLMPosition?\n    public var next: Int?\n    /// Manner's readings: Braid deleted manner.\n    public var phase: Float?\n    public var fit: Float?\n    public var arc: Float?\n    public var manner: Float?\n}\n\n/// What one strand supplied to one token (RaoLM's StrandShare).\npublic struct RaoLMStrandShare: Codable, Sendable, Equatable {\n    public var strand: String\n    public var threadID: String?\n    /// The gate before renormalising over the open strands: the memory lifted by agreement (and, in\n    /// the trajectory arms, times its trace term).\n    public var gate: Float\n    public var open: Bool\n    public var bestScore: Float?\n    public var lmProb: Float?\n    public var lmEntropy: Float?\n    /// w′_t·p_knn,t(y): the strand's renormalised weight times its own retrieval mass on the token.\n    public var knn: Float\n    public var share: Float\n    public var memory: Float?\n    public var backs: Float?\n    /// p_t(y) = λ_t·p_knn,t(y) + (1−λ_t)·p_lm,t(y); nil when the strand was not asked.\n    public var alone: Float?\n    public var trajectory: RaoLMTrajectory?\n    public var lift: Float?\n    public var thought: Float?\n    public var credit: Float?\n}\n\npublic struct RaoLMCandidate: Codable, Sendable, Equatable {\n    public var token: Int\n    public var text: String\n    public var prob: Float\n    public var parts: [Float]\n}\n\n/// Everything RaoLM recorded about one token (RaoLM's TokenTrace; citations and span index skipped).\npublic struct RaoLMTrace: Codable, Sendable, Equatable {\n    public var index: Int\n    public var token: Int\n    public var text: String\n    public var isPrompt: Bool\n    public var lmEntropy: Float\n    public var knnEntropy: Float\n    public var mixedEntropy: Float\n    public var sourceEntropy: Float\n    public var lmProb: Float\n    public var agreement: Float\n    public var mixedProb: Float\n    public var lambda: Float\n    public var neighbours: [RaoLMNeighbour]\n    public var uncited: Bool?\n    public var confidence: Float?\n    public var strands: [RaoLMStrandShare]?\n    public var threadEntropy: Float?\n    public var candidates: [RaoLMCandidate]?\n    public var role: String?\n    public var bits: Float?\n    public var followed: String?\n}\n\n/// RaoLM's braided gate settings.\npublic struct RaoLMGate: Codable, Sendable, Equatable {\n    public var evidenceFloor: Float\n    public var evidenceCeiling: Float\n    public var share: String\n    public var shareRate: Float\n    public var credibility: Bool\n    public var credibilityRate: Float\n    public var agreement: Bool\n    public var generatedEvidence: Bool\n    public var trajectory: String?\n    public var trajectoryBeta: Float?\n    public var ask: String?\n    public var askFloor: Float?\n    public var thoughtAgreement: Bool?\n    public var commonsPrior: Float?\n}\n\npublic struct RaoLMStrandRef: Codable, Sendable, Equatable {\n    public var name: String\n    public var label: String\n    public var threadID: String?\n    public var version: Int\n    public var manifest: RaoLMManifest\n    public var rowOffset: Int\n    public var rowCount: Int\n    public var entryOffset: Int\n    public var commons: Bool?\n    public var address: String?\n    public var ownerKey: String?\n\n    public var isCommons: Bool { commons == true }\n}\n\npublic struct RaoLMBraid: Codable, Sendable, Equatable {\n    public var vocabularySHA256: String\n    public var gateFloor: Float\n    public var strands: [RaoLMStrandRef]\n    public var gating: String?\n    public var gate: RaoLMGate?\n    public var packSHA256: String?\n}\n\n/// One scored text: RaoLM's CitedGeneration.\npublic struct RaoLMGeneration: Codable, Sendable, Equatable {\n    public var version: Int\n    public var generationID: String\n    public var manifest: RaoLMManifest\n    public var createdAt: Date\n    public var prompt: RaoLMPrompt\n    public var params: RaoLMParameters\n    public var tokens: [Int]\n    public var text: String\n    public var stoppedOnEOS: Bool\n    public var partitions: [RaoLMPartition]\n    public var traces: [RaoLMTrace]\n    public var braid: RaoLMBraid?\n\n    public static func load(from url: URL) throws -> RaoLMGeneration { try JSONCoding.read(RaoLMGeneration.self, from: url) }\n}\n\n// MARK: - The dump and RaoLM's report\n\npublic struct RaoLMAnswer: Codable, Sendable, Equatable {\n    public var start: Int\n    public var count: Int\n    public var text: String\n}\n\n/// One scored text in the dump's index.json.\npublic struct RaoLMDumpText: Codable, Sendable, Equatable {\n    public var file: String\n    public var index: Int\n    public var kind: String\n    public var label: String\n    public var owner: String?\n    public var near: String?\n    public var document: String?\n    public var tokens: Int\n    public var answers: [RaoLMAnswer]\n\n    /// Text positions RaoLM counts as answer tokens: each answer's tokens from position 1 (position\n    /// 0 has no trace).\n    public var answerPositions: [Int] {\n        var positions: [Int] = []\n        var seen = Set<Int>()\n        for answer in answers {\n            for p in answer.start..<(answer.start + answer.count) where p >= 1 && seen.insert(p).inserted { positions.append(p) }\n        }\n        return positions\n    }\n}\n\n/// The dump's index.json: the texts, the node versions scored, and where each gate arm's records went.\npublic struct RaoLMDumpIndex: Codable, Sendable, Equatable {\n    public var createdAt: Date\n    public var dataRoot: String\n    public var nodes: [String: Int]\n    /// Arm name (\"both β4\") → its directory under the dump (\"arms/both-beta4\").\n    public var arms: [String: String]\n    public var texts: [RaoLMDumpText]\n\n    public static func load(from dump: URL) throws -> RaoLMDumpIndex { try JSONCoding.read(RaoLMDumpIndex.self, from: dump.appendingPathComponent(\"index.json\")) }\n}\n\n/// RaoLM's trajectory report (trajectory.json): per text each strand's reading, the arms, the rules.\npublic struct RaoLMTrajectoryReport: Codable, Sendable {\n    public struct Reading: Codable, Sendable, Equatable {\n        public var strand: String\n        public var trace: Float\n        public var longest: Int\n        public var wireLongest: Int\n        public var manner: Float?\n        public var arc: Float?\n        public var fit: Float\n        public var meanFit: Float\n        public var meanBest: Float\n        public var logLikelihood: Float\n    }\n\n    public struct Text: Codable, Sendable, Equatable {\n        public var kind: String\n        public var label: String\n        public var owner: String?\n        public var near: String?\n        public var tokens: Int\n        public var readings: [Reading]\n    }\n\n    public struct Arm: Codable, Sendable, Equatable {\n        public var arm: String\n        public var holderShare: Float?\n        public var answerTokens: Int\n        public var exact: Int\n        public var prompts: Int\n        public var largestGate: Float?\n        public var allAsked: Float?\n        public var notAsked: Float?\n    }\n\n    public struct Rule: Codable, Sendable, Equatable {\n        public var rule: String\n        public var passed: Bool\n        public var detail: String\n    }\n\n    public struct Evaluation: Codable, Sendable {\n        public var rules: [Rule]\n        public var qualifies: [String]\n        public var winner: String?\n        public var reported: [String: Float]\n        public var summary: String\n    }\n\n    public struct Constants: Codable, Sendable, Equatable {\n        public var phrase: Int\n        public var arc: Int\n        public var bridge: Int\n        public var heads: Int\n        public var seeds: Int\n    }\n\n    public var createdAt: Date\n    public var nodes: [String: Int]\n    public var documents: [String: Int]\n    public var memorised: [String: Float]\n    public var rule: Constants\n    public var texts: [Text]\n    public var arms: [Arm]\n    public var evaluation: Evaluation\n\n    public static func load(from url: URL) throws -> RaoLMTrajectoryReport { try JSONCoding.read(RaoLMTrajectoryReport.self, from: url) }\n\n    /// RaoLM's trace rule as Braid's.\n    public var traceRule: TraceRule {\n        var rule = TraceRule()\n        rule.phrase = self.rule.phrase\n        rule.arc = self.rule.arc\n        rule.bridge = self.rule.bridge\n        rule.heads = self.rule.heads\n        rule.seeds = self.rule.seeds\n        return rule\n    }\n}\n"},{"path":"Sources/BraidCore/Port/Safetensors.swift","lines":153,"bytes":7123,"header":{"lines":[1,15],"what":[8,10],"pin":[11,14],"in":null,"out":null},"marks":[],"first":272,"scopes":[["S","SafetensorsFile",null,"public",19,19,[19,40],153,null,-1,0],["S","Tensor",null,"public",20,20,[20,46],29,null,0,0],["v","count",null,"public",28,28,[28,30],28,null,1,8],["E","Failure",null,"public",31,31,[31,67],47,null,0,0,["short","header","missing","dtype","bounds"]],["v","description",null,"public",38,38,[38,39],46,null,3,0],["i","init",["url"],"public",55,55,[55,33],57,[54,54],0,0],["i","init",["data","url"],"public",59,59,[59,52],93,null,0,0],["f","width",["_"],"static",96,96,[96,47],104,[95,95],0,0],["f","tensor",["_"],"public",106,106,[106,56],109,null,0,0],["f","int32",["_"],"public",112,112,[112,56],118,[111,111],0,0],["f","float32",["_"],"public",121,121,[121,58],135,[120,120],0,0],["f","widen",["_"],"public static",138,138,[138,54],149,[137,137],0,0],["v","sha256",null,"public",152,152,[152,30],152,[151,151],0,8]],"text":"//\n//  Safetensors.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: A small safetensors reader with no MLX: the header, and any I32, F16 or F32 tensor as a\n//        Swift array. Enough to read a RaoLM provenance index's layout (its values, key rows and\n//        offsets) for the port validation and for `braid verify` on an imported RaoLM log.\n//  PIN:  The format is little-endian: an 8-byte header length, the header's JSON, then the data,\n//        each tensor at `data_offsets` relative to the data's start. Every range is checked\n//        against the file and against its dtype and shape before a byte is read; F16 is widened\n//        bit-exactly (subnormals, infinities and NaN included).\n//\n\nimport Foundation\n\npublic struct SafetensorsFile: Sendable {\n    public struct Tensor: Sendable, Equatable {\n        public var name: String\n        /// \"I32\", \"F16\", \"F32\", … as the header names it.\n        public var dtype: String\n        public var shape: [Int]\n        /// The tensor's bytes, absolute in the file.\n        public var bytes: Range<Int>\n\n        public var count: Int { shape.reduce(1, *) }\n    }\n\n    public enum Failure: Error, CustomStringConvertible, Equatable {\n        case short(String)\n        case header(String)\n        case missing(String)\n        case dtype(name: String, found: String, expected: String)\n        case bounds(String)\n\n        public var description: String {\n            switch self {\n            case .short(let detail): return \"safetensors: the file is too short (\\(detail))\"\n            case .header(let detail): return \"safetensors: the header is not valid (\\(detail))\"\n            case .missing(let name): return \"safetensors: no tensor named \\(name)\"\n            case .dtype(let name, let found, let expected): return \"safetensors: \\(name) is \\(found), not \\(expected)\"\n            case .bounds(let detail): return \"safetensors: \\(detail)\"\n            }\n        }\n    }\n\n    public let url: URL?\n    public let data: Data\n    public let tensors: [String: Tensor]\n    public let metadata: [String: String]\n\n    /// Reads (maps) the file at `url`.\n    public init(url: URL) throws {\n        try self.init(data: Data(contentsOf: url, options: .alwaysMapped), url: url)\n    }\n\n    public init(data: Data, url: URL? = nil) throws {\n        self.url = url\n        self.data = data\n        guard data.count >= 8 else { throw Failure.short(\"\\(data.count) bytes, no header length\") }\n        let length = data.withUnsafeBytes { UInt64(littleEndian: $0.loadUnaligned(fromByteOffset: 0, as: UInt64.self)) }\n        guard length <= UInt64(data.count - 8) else { throw Failure.short(\"a \\(length)-byte header in \\(data.count) bytes\") }\n        let start = data.startIndex\n        let headerData = data.subdata(in: (start + 8)..<(start + 8 + Int(length)))\n        guard let object = try? JSONSerialization.jsonObject(with: headerData), let header = object as? [String: Any] else {\n            throw Failure.header(\"not a JSON object\")\n        }\n        let base = 8 + Int(length)\n        var tensors: [String: Tensor] = [:]\n        var metadata: [String: String] = [:]\n        for (name, value) in header {\n            if name == \"__metadata__\" {\n                for (key, entry) in (value as? [String: Any]) ?? [:] { metadata[key] = entry as? String ?? \"\\(entry)\" }\n                continue\n            }\n            guard let entry = value as? [String: Any], let dtype = entry[\"dtype\"] as? String,\n                  let shape = (entry[\"shape\"] as? [Any])?.compactMap({ ($0 as? NSNumber)?.intValue }),\n                  let offsets = (entry[\"data_offsets\"] as? [Any])?.compactMap({ ($0 as? NSNumber)?.intValue }), offsets.count == 2\n            else { throw Failure.header(\"tensor \\(name) has no dtype, shape or data_offsets\") }\n            guard offsets[0] >= 0, offsets[0] <= offsets[1], base + offsets[1] <= data.count else {\n                throw Failure.bounds(\"\\(name) spans \\(offsets[0])..<\\(offsets[1]) past the file's \\(data.count - base) data bytes\")\n            }\n            let tensor = Tensor(name: name, dtype: dtype, shape: shape, bytes: (base + offsets[0])..<(base + offsets[1]))\n            if let width = Self.width(dtype), tensor.count * width != tensor.bytes.count {\n                throw Failure.bounds(\"\\(name) is \\(dtype) \\(shape) but holds \\(tensor.bytes.count) bytes\")\n            }\n            tensors[name] = tensor\n        }\n        self.tensors = tensors\n        self.metadata = metadata\n    }\n\n    /// Bytes per element of the dtypes this reader widens; nil for the rest.\n    static func width(_ dtype: String) -> Int? {\n        switch dtype {\n        case \"I32\", \"F32\": return 4\n        case \"F16\", \"BF16\", \"I16\": return 2\n        case \"I64\", \"F64\": return 8\n        case \"U8\", \"I8\", \"BOOL\": return 1\n        default: return nil\n        }\n    }\n\n    public func tensor(_ name: String) throws -> Tensor {\n        guard let tensor = tensors[name] else { throw Failure.missing(name) }\n        return tensor\n    }\n\n    /// An I32 tensor, flattened.\n    public func int32(_ name: String) throws -> [Int32] {\n        let tensor = try tensor(name)\n        guard tensor.dtype == \"I32\" else { throw Failure.dtype(name: name, found: tensor.dtype, expected: \"I32\") }\n        return data.withUnsafeBytes { raw in\n            (0..<tensor.count).map { Int32(littleEndian: raw.loadUnaligned(fromByteOffset: tensor.bytes.lowerBound + 4 * $0, as: Int32.self)) }\n        }\n    }\n\n    /// An F32 tensor, or an F16 one widened, flattened.\n    public func float32(_ name: String) throws -> [Float] {\n        let tensor = try tensor(name)\n        switch tensor.dtype {\n        case \"F32\":\n            return data.withUnsafeBytes { raw in\n                (0..<tensor.count).map { Float(bitPattern: UInt32(littleEndian: raw.loadUnaligned(fromByteOffset: tensor.bytes.lowerBound + 4 * $0, as: UInt32.self))) }\n            }\n        case \"F16\":\n            return data.withUnsafeBytes { raw in\n                (0..<tensor.count).map { Self.widen(UInt16(littleEndian: raw.loadUnaligned(fromByteOffset: tensor.bytes.lowerBound + 2 * $0, as: UInt16.self))) }\n            }\n        default:\n            throw Failure.dtype(name: name, found: tensor.dtype, expected: \"F32 or F16\")\n        }\n    }\n\n    /// IEEE half to single, exactly.\n    public static func widen(_ half: UInt16) -> Float {\n        let sign = UInt32(half & 0x8000) << 16\n        let exponent = UInt32((half >> 10) & 0x1F)\n        let mantissa = UInt32(half & 0x03FF)\n        if exponent == 0 {\n            // Zero or subnormal: mantissa × 2^-24, exact in single precision.\n            let magnitude = Float(mantissa) * Float(bitPattern: 0x3380_0000)\n            return sign == 0 ? magnitude : -magnitude\n        }\n        if exponent == 0x1F { return Float(bitPattern: sign | 0x7F80_0000 | (mantissa << 13)) }\n        return Float(bitPattern: sign | ((exponent + 112) << 23) | (mantissa << 13))\n    }\n\n    /// The SHA-256 of the whole file: what a RaoLM manifest calls the index's sha256.\n    public var sha256: String { ContentHash.sha256Hex(data) }\n}\n"},{"path":"Sources/BraidCore/Record/Credit/Credit.swift","lines":49,"bytes":2165,"header":{"lines":[1,12],"what":[8,10],"pin":[11,11],"in":null,"out":null},"marks":[],"first":285,"scopes":[["S","CreditRow",null,"public",17,17,[17,45],24,[16,16],-1,0],["E","Credit",null,"public",26,26,[26,19],49,null,-1,0,[]],["f","assign",["_","commons"],"public static",30,30,[30,78],30,[27,29],1,8],["f","assign",["_","slots"],"public static",33,33,[33,86],35,[32,32],1,0],["f","assign",["_","commonsAt"],"static",37,37,[37,82],48,null,1,0]],"text":"//\n//  Credit.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The credit view over a generation: per position, the token's role, its bits and each\n//        strand's credit. A form token's credit is the commons'; a content token's is each\n//        strand's share.\n//  PIN:  A derived view over the session log, never stored per token.\n//\n\nimport Foundation\n\n/// Per position: the token's role, its bits and each strand's credit.\npublic struct CreditRow: Sendable, Equatable {\n    public var role: TokenRole\n    /// −log₂ p_commons(y); nil without a commons.\n    public var bits: Float?\n    public var credit: [Float]\n    /// The strand whose document the sentence followed, when credit moved there.\n    public var followed: Int?\n}\n\npublic enum Credit {\n    /// The blend over a generation's steps: a form token is wholly the commons', a content token\n    /// each strand's as it supplied it (the commons keeping what it filled in). `texts` are the\n    /// texts of every step in order, so the word a token belongs to is whole.\n    public static func assign(_ steps: [Step], commons: Int?) -> [CreditRow?] { assign(steps) { _ in commons } }\n\n    /// The same, with the commons wherever each step's slots put it.\n    public static func assign(_ steps: [Step], slots: [[StrandSlot]]) -> [CreditRow?] {\n        assign(steps) { i in i < slots.count ? StrandSlots.commons(slots[i]) : nil }\n    }\n\n    static func assign(_ steps: [Step], commonsAt: (Int) -> Int?) -> [CreditRow?] {\n        let roles = TokenRoles.roles(steps.map(\\.text))\n        return steps.indices.map { i in\n            guard let threads = steps[i].threads else { return nil }\n            let commons = commonsAt(i)\n            let role = roles[i]\n            let base = commons.flatMap { threads.indices.contains($0) ? threads[$0].plm : nil }\n            let bits = base.map { Float(-log2(Double(max($0, 1e-30)))) }\n            let credit = threads.indices.map { t -> Float in role == .form ? (t == commons ? 1 : 0) : threads[t].share }\n            return CreditRow(role: role, bits: bits, credit: credit, followed: nil)\n        }\n    }\n}\n"},{"path":"Sources/BraidCore/Record/Credit/FollowedCredit.swift","lines":117,"bytes":6024,"header":{"lines":[1,16],"what":[8,13],"pin":[14,15],"in":null,"out":null},"marks":[],"first":290,"scopes":[["S","FollowDecision",null,"public",20,20,[20,59],29,null,-1,0],["E","FollowedCredit",null,"public",31,31,[31,27],117,null,-1,0,[]],["f","apply",["_","steps","slots","partitions","margin"],"public static",36,37,[38,71],65,[34,35],1,0],["f","sentences",["_"],"static",68,68,[68,59],84,[67,67],1,0],["f","decide",["_","window","slots","partitions","margin"],"static",86,86,[86,147],116,null,1,0]],"text":"//\n//  FollowedCredit.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The owner's rule for a fact several Threads hold: \"the trajectory is the decision maker\n//        if it's the same fact\". Per generated sentence, the Thread whose chains advanced on the\n//        most tokens (its trace expected the token that was written), by a margin of two and on\n//        more than half the sentence's content tokens, takes the Threads' credit of every content\n//        token two or more Threads hold. Threads within the margin split that credit evenly; where\n//        nobody decides, nothing moves. Weight never decides. Only credit moves.\n//  PIN:  Threads are named, not indexed: an attach or detach inside a sentence moves indices, so\n//        each step is read through its own slots and the decision counts by name.\n//\n\nimport Foundation\n\npublic struct FollowDecision: Codable, Sendable, Equatable {\n    public var window: TokenRange\n    /// The Thread whose chains advanced on the most tokens, by the margin, if any.\n    public var followed: String?\n    /// The Threads within the margin of the best when nobody decides.\n    public var tied: [String]\n    public var documentID: String?\n    /// Per Thread, the tokens its chain expected and got.\n    public var advances: [String: Int]\n}\n\npublic enum FollowedCredit {\n    public static let margin = 2\n\n    /// Re-assigns the Threads' credit sentence by sentence. `credits` is `Credit.assign`'s output\n    /// for the same steps; `slots[i]` names step i's strands and places their rows in `partitions`.\n    @discardableResult\n    public static func apply(_ credits: inout [CreditRow?], steps: [Step], slots: [[StrandSlot]], partitions: [Int: PartitionRef],\n                             margin: Int = margin) -> [FollowDecision] {\n        var decisions: [FollowDecision] = []\n        for window in sentences(steps) {\n            let decision = decide(steps, window: window, slots: slots, partitions: partitions, margin: margin)\n            decisions.append(decision)\n            for i in window.start..<window.end {\n                guard i < slots.count, var row = credits[i], row.role == .content, let threads = steps[i].threads else { continue }\n                let here = slots[i]\n                let holders = threads.indices.filter { $0 < here.count && !here[$0].commons && row.credit[$0] > 0 }\n                guard holders.count >= 2 else { continue }\n                let pooled = holders.reduce(Float(0)) { $0 + row.credit[$1] }\n                if let followed = decision.followed, let follower = here.firstIndex(where: { $0.name == followed }), threads.indices.contains(follower) {\n                    for h in holders { row.credit[h] = 0 }\n                    row.credit[follower] = pooled\n                    row.followed = follower\n                } else if decision.tied.count >= 2 {\n                    let sharers = holders.filter { decision.tied.contains(here[$0].name) }\n                    guard sharers.count >= 2 else { continue }\n                    let among = sharers.reduce(Float(0)) { $0 + row.credit[$1] }\n                    for h in sharers { row.credit[h] = among / Float(sharers.count) }\n                } else {\n                    continue\n                }\n                credits[i] = row\n            }\n        }\n        return decisions\n    }\n\n    /// The generated steps split into sentences, as `AnswerStop` reads them.\n    static func sentences(_ steps: [Step]) -> [TokenRange] {\n        var windows: [TokenRange] = []\n        var start: Int?\n        var text = \"\"\n        for i in steps.indices {\n            guard !steps[i].isPrompt else { continue }\n            if let s = start, AnswerStop.sentenceEnded(previous: text, next: steps[i].text) {\n                windows.append(TokenRange(start: s, end: i))\n                start = nil\n                text = \"\"\n            }\n            if start == nil { start = i }\n            text += steps[i].text\n        }\n        if let s = start { windows.append(TokenRange(start: s, end: steps.count)) }\n        return windows\n    }\n\n    static func decide(_ steps: [Step], window: TokenRange, slots: [[StrandSlot]], partitions: [Int: PartitionRef], margin: Int) -> FollowDecision {\n        var advances: [String: Int] = [:]\n        var documents: [String: [String: Int]] = [:]\n        let roles = TokenRoles.roles(steps.map(\\.text))\n        for i in window.start..<window.end {\n            guard i < slots.count, let threads = steps[i].threads else { continue }\n            let here = slots[i]\n            for (t, record) in threads.enumerated() where t < here.count && !here[t].commons {\n                guard let trace = record.trace, trace.next == steps[i].token else { continue }\n                let name = here[t].name\n                advances[name, default: 0] += 1\n                if let row = trace.row, let partition = partitions[here[t].rowOffset + Int(row)] {\n                    documents[name, default: [:]][partition.documentID, default: 0] += 1\n                }\n            }\n        }\n        let content = (window.start..<window.end).filter { roles[$0] == .content }.count\n        let ranked = advances.filter { $0.value > 0 }.sorted { $0.value != $1.value ? $0.value > $1.value : $0.key < $1.key }\n        var followed: String?\n        var tied: [String] = []\n        if let best = ranked.first, best.value * 2 > content {\n            if (ranked.dropFirst().first?.value ?? 0) + margin <= best.value {\n                followed = best.key\n            } else {\n                tied = ranked.filter { $0.value + margin > best.value }.map(\\.key).sorted()\n            }\n        }\n        // The document the followed chains ran through most (ties: the smaller id).\n        let document = followed.flatMap { documents[$0]?.max { $0.value != $1.value ? $0.value < $1.value : $0.key > $1.key }?.key }\n        return FollowDecision(window: window, followed: followed, tied: tied, documentID: document, advances: advances)\n    }\n}\n"},{"path":"Sources/BraidCore/Record/Credit/Royalties.swift","lines":85,"bytes":4003,"header":{"lines":[1,12],"what":[8,10],"pin":[11,11],"in":null,"out":null},"marks":[],"first":295,"scopes":[["S","RoyaltyLine",null,"public",16,16,[16,47],23,null,-1,0],["S","DocumentRoyalty",null,"public",25,25,[25,51],30,null,-1,0],["S","RoyaltiesView",null,"public",32,32,[32,49],37,null,-1,0],["E","Royalties",null,"public",39,39,[39,22],85,null,-1,0,[]],["f","view",["steps","credits","slots","partitions"],"public static",41,41,[41,139],84,[40,40],3,0]],"text":"//\n//  Royalties.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The royalties view over a generation's steps: per Thread the tokens it led, its summed\n//        share, its bits-weighted credit; per cited document the share of the tokens whose heaviest\n//        matching hit resolves to it. A read-time view; the log stores shares only.\n//  PIN:  Keyed by the Thread's name: a strand detached and re-attached mid-answer is one line.\n//\n\nimport Foundation\n\npublic struct RoyaltyLine: Sendable, Equatable {\n    public var name: String\n    public var commons: Bool\n    public var led: Int\n    public var share: Double\n    public var credit: Double\n    public var bits: Double\n}\n\npublic struct DocumentRoyalty: Sendable, Equatable {\n    public var name: String\n    public var documentID: String\n    public var tokens: Int\n    public var share: Double\n}\n\npublic struct RoyaltiesView: Sendable, Equatable {\n    /// In the order the Threads first appear among the generated steps.\n    public var strands: [RoyaltyLine]\n    public var documents: [DocumentRoyalty]\n    public var generated: Int\n}\n\npublic enum Royalties {\n    /// Over the generated steps only (the prompt earns nothing). `slots[i]` names step i's strands.\n    public static func view(steps: [Step], credits: [CreditRow?], slots: [[StrandSlot]], partitions: [Int: PartitionRef]) -> RoyaltiesView {\n        var lines: [String: RoyaltyLine] = [:]\n        var order: [String] = []\n        var documents: [String: DocumentRoyalty] = [:]\n        var generated = 0\n        for (i, step) in steps.enumerated() where !step.isPrompt {\n            guard i < slots.count, let threads = step.threads else { continue }\n            let here = slots[i]\n            generated += 1\n            let dominant = step.dominant()\n            for (t, record) in threads.enumerated() where t < here.count {\n                let name = here[t].name\n                if lines[name] == nil { order.append(name) }\n                var line = lines[name] ?? RoyaltyLine(name: name, commons: here[t].commons, led: 0, share: 0, credit: 0, bits: 0)\n                if dominant == t { line.led += 1 }\n                line.share += Double(record.share)\n                if i < credits.count, let row = credits[i], t < row.credit.count {\n                    let bits = Double(row.bits ?? 1)\n                    line.credit += Double(row.credit[t]) * bits\n                    line.bits += bits * Double(record.share)\n                }\n                lines[name] = line\n            }\n            // The cited document: the heaviest matching hit of the strand that supplied the most.\n            if let t = threads.indices.max(by: { threads[$0].share < threads[$1].share }), t < here.count, !here[t].commons {\n                let record = threads[t]\n                let weights = Mixer.weights(record.hits.map { Double($0.score) }, tau: here[t].tau)\n                var best: (weight: Double, row: Int)?\n                for (k, hit) in record.hits.enumerated() where hit.value == step.token {\n                    if best == nil || weights[k] > best!.weight { best = (weights[k], here[t].rowOffset + Int(hit.row)) }\n                }\n                if let best, let partition = partitions[best.row] {\n                    let key = \"\\(here[t].name)|\\(partition.documentID)\"\n                    var royalty = documents[key] ?? DocumentRoyalty(name: here[t].name, documentID: partition.documentID, tokens: 0, share: 0)\n                    royalty.tokens += 1\n                    royalty.share += Double(record.share)\n                    documents[key] = royalty\n                }\n            }\n        }\n        return RoyaltiesView(strands: order.compactMap { lines[$0] },\n                             documents: documents.values.sorted { $0.share != $1.share ? $0.share > $1.share : ($0.documentID != $1.documentID ? $0.documentID < $1.documentID : $0.name < $1.name) },\n                             generated: generated)\n    }\n}\n"},{"path":"Sources/BraidCore/Record/Credit/TokenRoles.swift","lines":60,"bytes":3074,"header":{"lines":[1,14],"what":[8,12],"pin":[13,13],"in":null,"out":null},"marks":[],"first":300,"scopes":[["E","TokenRole",null,"public",18,18,[18,49],18,null,-1,8,[]],["E","TokenRoles",null,"public",20,20,[20,23],60,null,-1,0,[]],["f","roles",["_"],"public static",32,32,[32,63],44,[31,31],1,0],["f","close",["_"],"",35,35,[35,31],40,null,2,4],["f","role",["of"],"static",46,46,[46,51],52,null,1,0],["f","startsWord",["_","after"],"static",54,54,[54,75],59,null,1,0]],"text":"//\n//  TokenRoles.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The owner's blend: the commons provides a text's structure and form, the Threads its\n//        content, information and taste. Every token is form (whitespace, punctuation, a function\n//        word) or content; roles go by whole words, so every piece of a word takes the word's\n//        role. A form token's credit is the commons'; a content token's is each strand's as it\n//        supplied it. Each token counts by its bits, −log₂ of what the commons gave it.\n//  PIN:  A derived view over the session log, never stored per token.\n//\n\nimport Foundation\n\npublic enum TokenRole: String, Codable, Sendable { case form, content }\n\npublic enum TokenRoles {\n    public static let functionWords: Set<String> = Set(\"\"\"\n        a an the this that these those my your his her its our their i you he she it we they me him us them who whom whose which what\n        of in on at to for with by from about as into onto over under between through during before after above below up down out off\n        near since until upon within without and or but nor so yet if then than because while when where though although whether\n        is are was were be been being am has have had do does did will would can could may might shall should must\n        not no there here also just very too only more most such each every some any all both either neither other another own same\n        \"\"\".split(whereSeparator: \\.isWhitespace).map(String.init))\n\n    static let clitics: Set<String> = [\"'s\", \"'t\", \"'re\", \"'ll\", \"'d\", \"'ve\", \"'m\", \"’s\", \"’t\", \"’re\", \"’ll\", \"’d\", \"’ve\", \"’m\"]\n\n    /// Each token's role, from the tokens' texts in order, each as the tokenizer decodes it alone.\n    public static func roles(_ texts: [String]) -> [TokenRole] {\n        var roles = [TokenRole](repeating: .content, count: texts.count)\n        var start = 0\n        func close(_ end: Int) {\n            guard end > start else { return }\n            let role = role(of: texts[start..<end].joined().trimmingCharacters(in: .whitespacesAndNewlines))\n            for i in start..<end { roles[i] = role }\n            start = end\n        }\n        for i in texts.indices.dropFirst() where startsWord(texts[i], after: texts[i - 1]) { close(i) }\n        close(texts.count)\n        return roles\n    }\n\n    static func role(of word: String) -> TokenRole {\n        if !word.contains(where: { $0.isLetter || $0.isNumber }) { return .form }\n        let lower = word.lowercased()\n        if clitics.contains(lower) { return .form }\n        if word.allSatisfy(\\.isLetter), functionWords.contains(lower) { return .form }\n        return .content\n    }\n\n    static func startsWord(_ text: String, after previous: String) -> Bool {\n        guard let first = text.first else { return false }\n        if first.isWhitespace || !(first.isLetter || first.isNumber) { return true }\n        guard let last = previous.last else { return true }\n        return !(last.isLetter || last.isNumber)\n    }\n}\n"},{"path":"Sources/BraidCore/Record/Session/Records.swift","lines":139,"bytes":5916,"header":{"lines":[1,15],"what":[8,11],"pin":[12,14],"in":null,"out":null},"marks":[],"first":306,"scopes":[["S","ThreadRecord",null,"public",20,20,[20,57],73,[19,19],-1,0],["i","init",["memory","weight","open","plm","pknn","share","hlm","hknn","evidence","module","shadowGate","shadowShare","hits","trace","gate"],"public",50,50,[51,154],67,null,0,0],["E","CodingKeys",null,"",69,69,[69,39],72,null,0,0,["memory","weight","open","plm","pknn","share","hlm","hknn","evidence","module","shadowGate","shadowShare","hits","trace","gate"]],["S","Candidate",null,"public",76,76,[76,54],90,[75,75],-1,0],["i","init",["token","text","prob","parts"],"public",82,82,[82,73],87,null,3,0],["E","CodingKeys",null,"",89,89,[89,39],89,null,3,8,[]],["E","StepSource",null,"public",92,92,[92,50],92,null,-1,8,[]],["E","StopReason",null,"public",93,93,[93,50],93,null,-1,8,[]],["S","Step",null,"public",97,97,[97,49],139,[95,96],-1,0],["i","init",["index","token","text","source","owner","prob","lambda","threads","candidates","stop"],"public",113,113,[114,99],125,null,8,0],["E","CodingKeys",null,"",127,127,[127,39],130,null,8,0,["kind","index","token","text","source","owner","prob","lambda","threads","candidates","stop"]],["v","isPrompt",null,"public",132,132,[132,30],132,null,8,8],["f","dominant",["threshold"],"public",135,135,[135,57],138,[134,134],8,0]],"text":"//\n//  Records.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: What one position of a braided generation records, per strand and for the token: the\n//        hits a node retrieved, its trace state, its gate numbers, the two stored entropies, the\n//        shadow β4 counterfactual, and the token's probability and candidates. This is the\n//        session log's `tok` line and the in-memory step; nothing else is stored per position.\n//  PIN:  Exactly two entropies per strand (H_lm, H_knn). Everything else (gate entropy, lift,\n//        mixture-entropy bounds, credit, spans, royalties) is derived at read time. Keys are short\n//        because a session writes one of these per token per strand.\n//\n\nimport Foundation\n\n/// What one strand did at one position.\npublic struct ThreadRecord: Codable, Sendable, Equatable {\n    /// The gate's memory for this strand (the live gate is the memory).\n    public var memory: Float\n    /// Its weight in the mixture after renormalising over the open strands (0 when closed).\n    public var weight: Float\n    public var open: Bool\n    /// p_lm,t(y): nil when the strand was not asked for its state.\n    public var plm: Float?\n    /// p_knn,t(y), the strand's own retrieval mass on the token.\n    public var pknn: Float\n    /// share_t(y) = w′_t·p_t(y)/p(y). Logged so verify can recompute and compare.\n    public var share: Float\n    /// The two stored entropies: H(p_lm,t) (nil when not asked) and H(p_knn,t).\n    public var hlm: Float?\n    public var hknn: Float\n    /// At prompt and context positions: the bounded evidence ratio ρ̃_t the gate observed.\n    public var evidence: Float?\n    /// The trajectory module's e_t that entered the evidence (step 7); nil before.\n    public var module: Float?\n    /// The shadow β4 counterfactual: the gate and the share this strand would have had under\n    /// m_t·exp(β·(trace_t − mean trace)), never applied.\n    public var shadowGate: Float\n    public var shadowShare: Float\n    public var hits: [Hit]\n    public var trace: TraceState?\n    /// The gate the mixture renormalised into `weight`, when it is not the memory: an imported RaoLM\n    /// log's (its memory lifted by agreement, and in its trajectory arms times its trace term). Nil in\n    /// Braid's own logs, where the live gate is the memory.\n    public var gate: Float?\n\n    public init(memory: Float, weight: Float, open: Bool, plm: Float?, pknn: Float, share: Float, hlm: Float?, hknn: Float,\n                evidence: Float? = nil, module: Float? = nil, shadowGate: Float, shadowShare: Float, hits: [Hit], trace: TraceState?, gate: Float? = nil) {\n        self.memory = memory\n        self.weight = weight\n        self.open = open\n        self.plm = plm\n        self.pknn = pknn\n        self.share = share\n        self.hlm = hlm\n        self.hknn = hknn\n        self.evidence = evidence\n        self.module = module\n        self.shadowGate = shadowGate\n        self.shadowShare = shadowShare\n        self.hits = hits\n        self.trace = trace\n        self.gate = gate\n    }\n\n    enum CodingKeys: String, CodingKey {\n        case memory = \"mem\", weight = \"w\", open, plm, pknn, share, hlm = \"Hlm\", hknn = \"Hknn\", evidence = \"ev\", module = \"mod\"\n        case shadowGate = \"sg\", shadowShare = \"ss\", hits, trace = \"tr\", gate = \"g\"\n    }\n}\n\n/// One of the mixture's likeliest tokens at a position, split by strand.\npublic struct Candidate: Codable, Sendable, Equatable {\n    public var token: Int32\n    public var text: String\n    public var prob: Float\n    public var parts: [Float]\n\n    public init(token: Int32, text: String, prob: Float, parts: [Float]) {\n        self.token = token\n        self.text = text\n        self.prob = prob\n        self.parts = parts\n    }\n\n    enum CodingKeys: String, CodingKey { case token = \"tok\", text = \"txt\", prob = \"p\", parts }\n}\n\npublic enum StepSource: String, Codable, Sendable { case prompt, gen, ctx }\npublic enum StopReason: String, Codable, Sendable { case eos, sentence, max }\n\n/// One position of a generation: the token at it and what every strand did there. Step `i`'s\n/// strands predicted token `i` from tokens `0..<i`; the first prompt token has no strands.\npublic struct Step: Codable, Sendable, Equatable {\n    public var kind: String = \"tok\"\n    public var index: Int\n    public var token: Int32\n    public var text: String\n    public var source: StepSource\n    /// For a `ctx` line: the strand whose own context this position belongs to.\n    public var owner: Int?\n    /// p(y) of the mixture.\n    public var prob: Float\n    /// Σ_t w′_t·λ_t, the λ the mixture used.\n    public var lambda: Float\n    public var threads: [ThreadRecord]?\n    public var candidates: [Candidate]?\n    public var stop: StopReason?\n\n    public init(index: Int, token: Int32, text: String, source: StepSource, owner: Int? = nil, prob: Float, lambda: Float,\n                threads: [ThreadRecord]?, candidates: [Candidate]? = nil, stop: StopReason? = nil) {\n        self.index = index\n        self.token = token\n        self.text = text\n        self.source = source\n        self.owner = owner\n        self.prob = prob\n        self.lambda = lambda\n        self.threads = threads\n        self.candidates = candidates\n        self.stop = stop\n    }\n\n    enum CodingKeys: String, CodingKey {\n        case kind, index = \"i\", token = \"tok\", text = \"txt\", source = \"src\", owner = \"t\", prob = \"p\", lambda = \"lam\", threads = \"thr\"\n        case candidates = \"cand\", stop\n    }\n\n    public var isPrompt: Bool { source != .gen }\n\n    /// The strand that supplied most of this token, when it supplied at least `threshold` of it.\n    public func dominant(threshold: Float = 0.6) -> Int? {\n        guard let threads, let best = threads.indices.max(by: { threads[$0].share < threads[$1].share }), threads[best].share >= threshold else { return nil }\n        return best\n    }\n}\n"},{"path":"Sources/BraidCore/Record/Session/SessionLog.swift","lines":383,"bytes":15167,"header":{"lines":[1,15],"what":[8,11],"pin":[12,14],"in":null,"out":null},"marks":[],"first":319,"scopes":[["S","SessionThread",null,"public",19,19,[19,58],50,null,-1,0],["i","init",["descriptor","lambda","rowOffset","rowCount"],"public",35,35,[35,92],49,null,0,0],["S","PackIdentity",null,"public",52,52,[52,57],71,null,-1,0],["i","init",["sha256","name","vocabularySHA256","tokenizerSHA256","hiddenSize","vocabulary","seamSHA256"],"public",62,62,[62,160],70,null,2,0],["S","SessionHeader",null,"public",73,73,[73,58],102,null,-1,0],["i","init",["sessionID","createdAt","source","pack","gate","trace","module","hitsLogged","threads"],"public",88,88,[89,142],101,null,4,0],["S","QuestionRewrite",null,"public",104,104,[104,60],117,null,-1,0],["i","init",["question","stem","rewriter","seconds"],"public",111,111,[111,83],116,null,6,0],["S","GenerationPrompt",null,"public",119,119,[119,61],129,null,-1,0],["i","init",["text","tokens","question"],"public",124,124,[124,81],128,null,8,0],["S","ContextRef",null,"public",131,131,[131,55],149,null,-1,0],["i","init",["strand","tokens","score","documentID","row","offset"],"public",139,139,[139,103],146,null,10,0],["E","CodingKeys",null,"",148,148,[148,39],148,null,10,8,[]],["S","GenerationParameters",null,"public",151,151,[151,65],162,null,-1,0],["i","init",[],"public",161,161,[161,18],161,null,13,8],["S","GenerationLine",null,"public",164,164,[164,59],180,null,-1,0],["i","init",["generationID","prompt","context","params","strands"],"public",173,173,[173,137],179,null,15,0],["S","EndLine",null,"public",182,182,[182,52],193,null,-1,0],["S","MembershipLine",null,"public",195,195,[195,59],220,null,-1,0],["i","init",["kind","strand","thread","position","caughtUp","seconds","memory","catchUpHits"],"public",208,208,[208,159],217,null,18,0],["E","CodingKeys",null,"",219,219,[219,39],219,null,18,8,[]],["S","LineKind",null,"",223,223,[223,25],223,[222,222],-1,8],["E","SessionLog",null,"public",225,225,[225,23],248,null,-1,0,[]],["f","fileName",["sessionID","at"],"public static",227,227,[227,85],229,[226,226],22,0],["f","stamp",["at"],"public static",232,232,[232,63],238,[231,231],22,0],["f","newSessionID",[],"public static",240,240,[240,48],240,null,22,8],["f","generationID",["pack","threads","gateFingerprint","prompt","params"],"public static",243,243,[243,173],247,[242,242],22,0],["C","SessionWriter",null,"public final",251,251,[251,54],294,[250,250],-1,0],["i","init",["url","header"],"public",259,259,[259,56],264,null,27,0],["f","write",["_"],"private",266,266,[266,56],270,null,27,0],["f","begin",["_"],"public",272,272,[272,59],276,null,27,0],["f","append",["_"],"public",278,278,[278,44],278,null,27,8],["f","membership",["_"],"public",280,280,[280,58],280,null,27,8],["f","end",["generationID","tokens","generated","stoppedOn","text","partitions"],"public",283,284,[284,155],291,[282,282],27,0],["f","close",[],"public",293,293,[293,24],293,null,27,8],["S","LoggedGeneration",null,"public",297,297,[297,52],308,[296,296],-1,0],["f","==",["lhs","rhs"],"public static",305,305,[305,81],307,null,35,2],["S","LoggedSession",null,"public",310,310,[310,38],314,null,-1,0],["E","SessionReader",null,"public",316,316,[316,26],383,null,-1,0,[]],["E","Failure",null,"public",317,317,[317,67],331,null,38,0,["empty","noHeader","schema","stray"]],["v","description",null,"public",323,323,[323,39],330,null,39,0],["f","read",["_"],"public static",333,333,[333,64],382,null,38,0]],"text":"//\n//  SessionLog.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The session log: one JSON object per line. `header` once; per generation `gen`, the\n//        `tok` lines (one per position, see Records.swift), `end`; `attach` and `detach` where a\n//        strand joined or left. The artifact `braid verify` replays, the trajectory module reads\n//        offline, and the benches run against.\n//  PIN:  Sorted keys, compact lines, schema versioned. The `end` line carries the SHA-256 of every\n//        line of its generation as written, so a log that was edited is caught before any number\n//        in it is trusted.\n//\n\nimport Foundation\n\npublic struct SessionThread: Codable, Sendable, Equatable {\n    public var name: String\n    public var label: String\n    public var commons: Bool\n    public var threadID: String?\n    public var lane: String?\n    public var indexSHA256: String?\n    public var checkpointSHA256: String?\n    public var versionSHA256: String?\n    public var corpusHash: String?\n    public var lambda: Float\n    public var tau: Float\n    /// Where this strand's rows begin in the braid's global partition table, and how many it has.\n    public var rowOffset: Int\n    public var rowCount: Int\n\n    public init(descriptor d: NodeDescriptor, lambda: Float, rowOffset: Int, rowCount: Int) {\n        name = d.name\n        label = d.label\n        commons = d.isCommons\n        threadID = d.threadID\n        lane = d.lane\n        indexSHA256 = d.indexSHA256\n        checkpointSHA256 = d.checkpointsSHA256\n        versionSHA256 = d.versionSHA256\n        corpusHash = d.corpusHash\n        self.lambda = lambda\n        tau = d.tau\n        self.rowOffset = rowOffset\n        self.rowCount = rowCount\n    }\n}\n\npublic struct PackIdentity: Codable, Sendable, Equatable {\n    public var sha256: String?\n    public var name: String?\n    public var vocabularySHA256: String\n    public var tokenizerSHA256: String\n    public var hiddenSize: Int\n    public var vocabulary: Int\n    /// The seam of the tail every strand runs (the commons' blocks ≥ cut, embedding and final norm); nil in logs written before it was recorded.\n    public var seamSHA256: String?\n\n    public init(sha256: String?, name: String?, vocabularySHA256: String, tokenizerSHA256: String, hiddenSize: Int, vocabulary: Int, seamSHA256: String? = nil) {\n        self.sha256 = sha256\n        self.name = name\n        self.vocabularySHA256 = vocabularySHA256\n        self.tokenizerSHA256 = tokenizerSHA256\n        self.hiddenSize = hiddenSize\n        self.vocabulary = vocabulary\n        self.seamSHA256 = seamSHA256\n    }\n}\n\npublic struct SessionHeader: Codable, Sendable, Equatable {\n    public var kind = \"header\"\n    public var schema: Int\n    public var sessionID: String\n    public var createdAt: Date\n    /// \"braid\", or \"raolm\" for a log imported from RaoLM generations.\n    public var source: String\n    public var pack: PackIdentity\n    public var gate: GateSettings\n    public var gateFingerprint: String\n    public var trace: TraceRule\n    public var module: ModuleSettings?\n    public var hitsLogged: Int\n    public var threads: [SessionThread]\n\n    public init(sessionID: String, createdAt: Date = Date(timeIntervalSince1970: Date().timeIntervalSince1970.rounded(.down)), source: String = \"braid\",\n                pack: PackIdentity, gate: GateSettings, trace: TraceRule, module: ModuleSettings?, hitsLogged: Int, threads: [SessionThread]) {\n        schema = BraidVersion.sessionSchema\n        self.sessionID = sessionID\n        self.createdAt = createdAt\n        self.source = source\n        self.pack = pack\n        self.gate = gate\n        gateFingerprint = gate.fingerprint\n        self.trace = trace\n        self.module = module\n        self.hitsLogged = hitsLogged\n        self.threads = threads\n    }\n}\n\npublic struct QuestionRewrite: Codable, Sendable, Equatable {\n    public var question: String\n    public var stem: String\n    /// \"commons\" (the commons model, prompted) or \"none\" (the question itself).\n    public var rewriter: String\n    public var seconds: Double\n\n    public init(question: String, stem: String, rewriter: String, seconds: Double) {\n        self.question = question\n        self.stem = stem\n        self.rewriter = rewriter\n        self.seconds = seconds\n    }\n}\n\npublic struct GenerationPrompt: Codable, Sendable, Equatable {\n    public var text: String\n    public var tokens: [Int32]\n    public var question: QuestionRewrite?\n\n    public init(text: String, tokens: [Int32], question: QuestionRewrite? = nil) {\n        self.text = text\n        self.tokens = tokens\n        self.question = question\n    }\n}\n\npublic struct ContextRef: Codable, Sendable, Equatable {\n    public var strand: Int\n    public var tokens: [Int32]\n    public var score: Float\n    public var documentID: String\n    public var row: Int\n    public var offset: Int\n\n    public init(strand: Int, tokens: [Int32], score: Float, documentID: String, row: Int, offset: Int) {\n        self.strand = strand\n        self.tokens = tokens\n        self.score = score\n        self.documentID = documentID\n        self.row = row\n        self.offset = offset\n    }\n\n    enum CodingKeys: String, CodingKey { case strand = \"t\", tokens, score, documentID, row, offset }\n}\n\npublic struct GenerationParameters: Codable, Sendable, Equatable {\n    public var lambda: Float = 0.5\n    public var tau: Float = 0.05\n    public var k: Int = 16\n    public var temperature: Float = 0\n    public var topK: Int = 0\n    public var seed: UInt64 = 42\n    public var maxTokens: Int = 24\n    public var stopAtSentenceEnd = false\n\n    public init() {}\n}\n\npublic struct GenerationLine: Codable, Sendable, Equatable {\n    public var kind = \"gen\"\n    public var generationID: String\n    public var prompt: GenerationPrompt\n    public var context: [ContextRef]?\n    public var params: GenerationParameters\n    /// The strands in this generation's order (the header's, as changed by attach/detach lines so far).\n    public var strands: [String]\n\n    public init(generationID: String, prompt: GenerationPrompt, context: [ContextRef]?, params: GenerationParameters, strands: [String]) {\n        self.generationID = generationID\n        self.prompt = prompt\n        self.context = context\n        self.params = params\n        self.strands = strands\n    }\n}\n\npublic struct EndLine: Codable, Sendable, Equatable {\n    public var kind = \"end\"\n    public var generationID: String\n    public var tokens: Int\n    public var generated: Int\n    public var stoppedOn: StopReason?\n    public var text: String\n    /// Every global row any logged hit or chain touched.\n    public var partitions: [PartitionRef]\n    /// SHA-256 of every line of this generation (gen … last tok), each with its newline.\n    public var bodySHA256: String\n}\n\npublic struct MembershipLine: Codable, Sendable, Equatable {\n    /// \"attach\" or \"detach\".\n    public var kind: String\n    public var strand: Int\n    public var thread: SessionThread\n    public var position: Int\n    public var caughtUp: Int\n    public var seconds: Double\n    public var memory: [Float]\n    /// For an attach: the newcomer's hits at every prefix position (what seeded its chains), so the\n    /// trace replays exactly from the log.\n    public var catchUpHits: [[Hit]]?\n\n    public init(kind: String, strand: Int, thread: SessionThread, position: Int, caughtUp: Int, seconds: Double, memory: [Float], catchUpHits: [[Hit]]? = nil) {\n        self.kind = kind\n        self.strand = strand\n        self.thread = thread\n        self.position = position\n        self.caughtUp = caughtUp\n        self.seconds = seconds\n        self.memory = memory\n        self.catchUpHits = catchUpHits\n    }\n\n    enum CodingKeys: String, CodingKey { case kind, strand = \"t\", thread, position, caughtUp, seconds, memory, catchUpHits = \"hits\" }\n}\n\n/// A line's kind, read before decoding it.\nstruct LineKind: Codable { var kind: String }\n\npublic enum SessionLog {\n    /// `sessions/<yyyymmdd-hhmmss>-<id8>.jsonl`.\n    public static func fileName(sessionID: String, at date: Date = Date()) -> String {\n        \"\\(stamp(at: date))-\\(sessionID.prefix(8)).jsonl\"\n    }\n\n    /// `yyyyMMdd-HHmmss` in UTC: the stamp sessions and bench reports are named by.\n    public static func stamp(at date: Date = Date()) -> String {\n        let formatter = DateFormatter()\n        formatter.locale = Locale(identifier: \"en_US_POSIX\")\n        formatter.timeZone = TimeZone(identifier: \"UTC\")\n        formatter.dateFormat = \"yyyyMMdd-HHmmss\"\n        return formatter.string(from: date)\n    }\n\n    public static func newSessionID() -> String { UUID().uuidString.replacingOccurrences(of: \"-\", with: \"\").lowercased() }\n\n    /// 16 hex of sha256(pack ‖ index SHAs ‖ gate fingerprint ‖ prompt ‖ params): the same prompt to the same braid repeats it.\n    public static func generationID(pack: PackIdentity, threads: [SessionThread], gateFingerprint: String, prompt: GenerationPrompt, params: GenerationParameters) -> String {\n        let parts = [pack.sha256 ?? pack.vocabularySHA256] + threads.map { \"\\($0.name)@\\($0.indexSHA256 ?? \"-\")\" } + [gateFingerprint]\n            + [(try? JSONCoding.line(prompt)) ?? prompt.text, (try? JSONCoding.line(params)) ?? \"\"]\n        return \"gen-\" + String(ContentHash.sha256Hex(parts.joined(separator: \"|\")).prefix(16))\n    }\n}\n\n/// Writes a session log line by line, hashing each generation's body as it goes.\npublic final class SessionWriter: @unchecked Sendable {\n    public let url: URL\n    public let header: SessionHeader\n    private let writer: JSONLWriter\n    private let encoder = JSONCoding.lineEncoder()\n    private var body: [String] = []\n    private var inGeneration = false\n\n    public init(url: URL, header: SessionHeader) throws {\n        self.url = url\n        self.header = header\n        writer = try JSONLWriter(url: url, truncate: true)\n        try writer.appendRaw(String(decoding: try encoder.encode(header), as: UTF8.self))\n    }\n\n    private func write<T: Encodable>(_ value: T) throws {\n        let line = String(decoding: try encoder.encode(value), as: UTF8.self)\n        if inGeneration { body.append(line) }\n        try writer.appendRaw(line)\n    }\n\n    public func begin(_ generation: GenerationLine) throws {\n        inGeneration = true\n        body = []\n        try write(generation)\n    }\n\n    public func append(_ step: Step) throws { try write(step) }\n\n    public func membership(_ line: MembershipLine) throws { try write(line) }\n\n    /// Closes the generation with its body hash and returns the end line as written.\n    @discardableResult\n    public func end(generationID: String, tokens: Int, generated: Int, stoppedOn: StopReason?, text: String, partitions: [PartitionRef]) throws -> EndLine {\n        let hash = ContentHash.sha256Hex(body.map { $0 + \"\\n\" }.joined())\n        let line = EndLine(generationID: generationID, tokens: tokens, generated: generated, stoppedOn: stoppedOn, text: text, partitions: partitions, bodySHA256: hash)\n        inGeneration = false\n        body = []\n        try write(line)\n        return line\n    }\n\n    public func close() { writer.close() }\n}\n\n/// A generation as read back: its lines in order.\npublic struct LoggedGeneration: Sendable, Equatable {\n    public var gen: GenerationLine\n    public var steps: [Step]\n    public var end: EndLine?\n    /// Membership changes inside this generation, keyed by the step index they precede.\n    public var membership: [(before: Int, line: MembershipLine)]\n    public var bodySHA256: String\n\n    public static func == (lhs: LoggedGeneration, rhs: LoggedGeneration) -> Bool {\n        lhs.gen == rhs.gen && lhs.steps == rhs.steps && lhs.end == rhs.end && lhs.bodySHA256 == rhs.bodySHA256\n    }\n}\n\npublic struct LoggedSession: Sendable {\n    public var header: SessionHeader\n    public var generations: [LoggedGeneration]\n    public var membership: [MembershipLine]\n}\n\npublic enum SessionReader {\n    public enum Failure: Error, CustomStringConvertible, Equatable {\n        case empty\n        case noHeader\n        case schema(Int)\n        case stray(String, line: Int)\n\n        public var description: String {\n            switch self {\n            case .empty: return \"the session log is empty\"\n            case .noHeader: return \"the first line is not a header\"\n            case .schema(let s): return \"session schema \\(s) is not \\(BraidVersion.sessionSchema)\"\n            case .stray(let kind, let line): return \"a \\(kind) line outside a generation at line \\(line)\"\n            }\n        }\n    }\n\n    public static func read(_ url: URL) throws -> LoggedSession {\n        let text = try String(contentsOf: url, encoding: .utf8)\n        let lines = text.split(separator: \"\\n\").filter { !$0.allSatisfy(\\.isWhitespace) }\n        guard let first = lines.first else { throw Failure.empty }\n        let decoder = JSONCoding.decoder()\n        guard (try? decoder.decode(LineKind.self, from: Data(first.utf8)))?.kind == \"header\" else { throw Failure.noHeader }\n        let header = try decoder.decode(SessionHeader.self, from: Data(first.utf8))\n        guard header.schema == BraidVersion.sessionSchema else { throw Failure.schema(header.schema) }\n        var generations: [LoggedGeneration] = []\n        var membership: [MembershipLine] = []\n        var current: LoggedGeneration?\n        var body: [String] = []\n        for (n, raw) in lines.enumerated().dropFirst() {\n            let data = Data(raw.utf8)\n            let kind = try decoder.decode(LineKind.self, from: data).kind\n            switch kind {\n            case \"gen\":\n                if let open = current { generations.append(open) }\n                body = [String(raw)]\n                current = LoggedGeneration(gen: try decoder.decode(GenerationLine.self, from: data), steps: [], end: nil, membership: [], bodySHA256: \"\")\n            case \"tok\":\n                guard var open = current else { throw Failure.stray(kind, line: n + 1) }\n                body.append(String(raw))\n                open.steps.append(try decoder.decode(Step.self, from: data))\n                current = open\n            case \"end\":\n                guard var open = current else { throw Failure.stray(kind, line: n + 1) }\n                open.end = try decoder.decode(EndLine.self, from: data)\n                open.bodySHA256 = ContentHash.sha256Hex(body.map { $0 + \"\\n\" }.joined())\n                generations.append(open)\n                current = nil\n                body = []\n            case \"attach\", \"detach\":\n                let line = try decoder.decode(MembershipLine.self, from: data)\n                membership.append(line)\n                if var open = current {\n                    body.append(String(raw))\n                    open.membership.append((open.steps.count, line))\n                    current = open\n                }\n            default:\n                continue\n            }\n        }\n        if var open = current {\n            open.bodySHA256 = ContentHash.sha256Hex(body.map { $0 + \"\\n\" }.joined())\n            generations.append(open)\n        }\n        return LoggedSession(header: header, generations: generations, membership: membership)\n    }\n}\n"},{"path":"Sources/BraidCore/Record/Verify/SessionReplay.swift","lines":193,"bytes":10509,"header":{"lines":[1,16],"what":[8,15],"pin":null,"in":null,"out":null},"marks":[],"first":361,"scopes":[["S","ReplayIssue",null,"public",20,20,[20,81],39,null,-1,0],["i","init",["generationID","step","strand","check","detail"],"public",27,27,[27,95],33,null,0,0],["v","description",null,"public",35,35,[35,35],38,null,0,0],["E","SessionReplay",null,"public",41,41,[41,26],193,null,-1,0,[]],["S","Tolerances",null,"public",42,42,[42,39],48,null,3,0],["i","init",[],"public",47,47,[47,22],47,null,4,8],["f","skipped",["for"],"public static",52,52,[52,70],54,[50,51],3,0],["f","strands",["for","session"],"public static",57,57,[57,108],67,[56,56],3,0],["f","slots",["for","session"],"public static",72,72,[72,105],93,[69,71],3,0],["f","check",["_","session","tolerances"],"public static",96,96,[96,141],192,[95,95],3,0],["f","issue",["_","_","step","strand"],"",100,100,[100,92],102,null,9,4]],"text":"//\n//  SessionReplay.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: What a session log proves about itself with no model: the body hashes; shares that sum\n//        to 1; w′ from memory and the open set; shares from p_lm, p_knn, λ and w′; p from the open\n//        strands; H_knn from the hits; the memory recursion over prompt and context positions\n//        (the gate replay that proves the clamp held); the shadow β4 from the memory and the\n//        traces. The trace replay needs the index layout and lives beside it in the verifier.\n//        A log imported from RaoLM (`source: raolm`) takes the checks that do not depend on\n//        Braid's live gate: w′ comes from the gate it logs (RaoLM's), and the memory recursion and\n//        the shadow are not replayed (`skipped(for:)` says so).\n//\n\nimport Foundation\n\npublic struct ReplayIssue: Codable, Sendable, Equatable, CustomStringConvertible {\n    public var generationID: String\n    public var step: Int?\n    public var strand: Int?\n    public var check: String\n    public var detail: String\n\n    public init(generationID: String, step: Int?, strand: Int?, check: String, detail: String) {\n        self.generationID = generationID\n        self.step = step\n        self.strand = strand\n        self.check = check\n        self.detail = detail\n    }\n\n    public var description: String {\n        let at = [step.map { \"step \\($0)\" }, strand.map { \"strand \\($0)\" }].compactMap { $0 }.joined(separator: \", \")\n        return \"\\(generationID) \\(at.isEmpty ? \"\" : \"(\\(at)) \")\\(check): \\(detail)\"\n    }\n}\n\npublic enum SessionReplay {\n    public struct Tolerances: Sendable {\n        public var shareSum: Double = 1e-5\n        public var arithmetic: Double = 1e-6\n        public var entropy: Double = 1e-5\n        public var memory: Double = 1e-5\n        public init() {}\n    }\n\n    /// The checks a log does not take, by its source: an imported RaoLM log's memory moved under\n    /// RaoLM's gate, not Braid's live gate, and it ran no shadow.\n    public static func skipped(for header: SessionHeader) -> [String] {\n        header.source == RaoLMImport.source ? [\"memory recursion\", \"shadow β4\"] : []\n    }\n\n    /// The strands in effect for a generation: the header's order with earlier memberships applied.\n    public static func strands(for generation: LoggedGeneration, session: LoggedSession) -> [SessionThread] {\n        var strands = session.header.threads\n        for line in session.membership where line.kind == \"attach\" || line.kind == \"detach\" {\n            // Membership lines before this generation (by name list) are already folded into `gen.strands`.\n            _ = line\n        }\n        // The generation line records its own strand order; map names back to the header or the attach lines.\n        let known = session.header.threads + session.membership.filter { $0.kind == \"attach\" }.map(\\.thread)\n        strands = generation.gen.strands.compactMap { name in known.last { $0.name == name } }\n        return strands\n    }\n\n    /// Per step of the generation (aligned with `generation.steps`), the strands its records are in:\n    /// the generation's strand order with every attach and detach line before that step applied. A\n    /// context line's one record is its owner's.\n    public static func slots(for generation: LoggedGeneration, session: LoggedSession) -> [[StrandSlot]] {\n        var current = strands(for: generation, session: session).map(StrandSlot.init)\n        var membershipIndex = 0\n        var result: [[StrandSlot]] = []\n        for (k, step) in generation.steps.enumerated() {\n            while membershipIndex < generation.membership.count, generation.membership[membershipIndex].before == k {\n                let line = generation.membership[membershipIndex].line\n                if line.kind == \"attach\" {\n                    current.append(StrandSlot(line.thread))\n                } else if current.indices.contains(line.strand) {\n                    current.remove(at: line.strand)\n                }\n                membershipIndex += 1\n            }\n            if step.source == .ctx, let owner = step.owner, current.indices.contains(owner) {\n                result.append([current[owner]])\n            } else {\n                result.append(current)\n            }\n        }\n        return result\n    }\n\n    /// Every arithmetic check over one generation.\n    public static func check(_ generation: LoggedGeneration, session: LoggedSession, tolerances: Tolerances = Tolerances()) -> [ReplayIssue] {\n        var issues: [ReplayIssue] = []\n        let id = generation.gen.generationID\n        let settings = session.header.gate\n        func issue(_ check: String, _ detail: String, step: Int? = nil, strand: Int? = nil) {\n            issues.append(ReplayIssue(generationID: id, step: step, strand: strand, check: check, detail: detail))\n        }\n        if let end = generation.end, end.bodySHA256 != generation.bodySHA256 {\n            issue(\"body\", \"the end line's sha256 \\(end.bodySHA256.prefix(12)) is not the body's \\(generation.bodySHA256.prefix(12))\")\n        }\n        var strands = strands(for: generation, session: session)\n        let commons = strands.firstIndex(where: \\.commons)\n        var state = GateState(strands: strands.count, commons: commons, prior: settings.commonsPrior)\n        let liveGate = skipped(for: session.header).isEmpty\n        var stateKnown = liveGate\n        var membershipIndex = 0\n        for (k, step) in generation.steps.enumerated() {\n            // Apply memberships that precede this step.\n            while membershipIndex < generation.membership.count, generation.membership[membershipIndex].before == k {\n                let line = generation.membership[membershipIndex].line\n                if line.kind == \"attach\" {\n                    strands.append(line.thread)\n                    Gate.attach(&state)\n                } else if strands.indices.contains(line.strand) {\n                    strands.remove(at: line.strand)\n                    Gate.detach(&state, at: line.strand)\n                }\n                membershipIndex += 1\n            }\n            guard let threads = step.threads else { continue }\n            if step.source == .ctx { continue }\n            if threads.count != strands.count {\n                issue(\"strands\", \"\\(threads.count) records for \\(strands.count) strands\", step: k)\n                stateKnown = false\n                continue\n            }\n            let shareSum = threads.reduce(0.0) { $0 + Double($1.share) }\n            if abs(shareSum - 1) > tolerances.shareSum { issue(\"shares\", \"sum \\(shareSum)\", step: k) }\n            // w′ from the gate and open: the memory (Braid's live gate), or the gate a record logs as its own.\n            let gates = threads.map { Double($0.gate ?? $0.memory) }\n            let open = threads.map(\\.open)\n            let weights = Gate.renormalised(gates, open: open)\n            for t in threads.indices where abs(weights[t] - Double(threads[t].weight)) > tolerances.arithmetic {\n                issue(\"weights\", \"w′ \\(threads[t].weight) recomputes as \\(weights[t])\", step: k, strand: t)\n            }\n            // p and shares from the logged per-strand probabilities.\n            let lambdas = strands.map { Double($0.lambda) }\n            let probabilities: [Double?] = threads.indices.map { t in\n                guard let plm = threads[t].plm else { return nil }\n                return lambdas[t] * Double(threads[t].pknn) + (1 - lambdas[t]) * Double(plm)\n            }\n            let p = threads.indices.reduce(0.0) { $0 + (open[$1] ? weights[$1] * (probabilities[$1] ?? 0) : 0) }\n            if abs(p - Double(step.prob)) > tolerances.arithmetic * 10 { issue(\"p\", \"p \\(step.prob) recomputes as \\(p)\", step: k) }\n            if p > 0 {\n                for t in threads.indices {\n                    let expected = open[t] ? weights[t] * (probabilities[t] ?? 0) / p : 0\n                    if abs(expected - Double(threads[t].share)) > tolerances.arithmetic * 10 {\n                        issue(\"share\", \"share \\(threads[t].share) recomputes as \\(expected)\", step: k, strand: t)\n                    }\n                }\n            }\n            // H_knn from the hits.\n            if session.header.hitsLogged >= 16 {\n                for t in threads.indices {\n                    let w = Mixer.weights(threads[t].hits.map { Double($0.score) }, tau: Double(strands[t].tau))\n                    var knn: [Int32: Double] = [:]\n                    for (i, hit) in threads[t].hits.enumerated() { knn[hit.value, default: 0] += w[i] }\n                    let h = Mixer.entropy(knn.values)\n                    if abs(h - Double(threads[t].hknn)) > tolerances.entropy { issue(\"Hknn\", \"\\(threads[t].hknn) recomputes as \\(h)\", step: k, strand: t) }\n                }\n            }\n            // The shadow from the memory and the traces.\n            if liveGate {\n                let traces = threads.map { Double($0.trace?.trace ?? 0) }\n                let shadow = Gate.shadowWeights(GateState(memoryOnly: threads.map { Double($0.memory) }, commons: commons), traces: traces, beta: settings.shadowBeta)\n                for t in threads.indices where abs(shadow[t] - Double(threads[t].shadowGate)) > tolerances.arithmetic * 10 {\n                    issue(\"shadow\", \"shadow gate \\(threads[t].shadowGate) recomputes as \\(shadow[t])\", step: k, strand: t)\n                }\n            }\n            // The memory recursion: this step's memory must be what the gate holds now; prompt\n            // positions then move it by the logged evidence.\n            if stateKnown {\n                for t in threads.indices where abs(state.memory[t] - Double(threads[t].memory)) > tolerances.memory {\n                    issue(\"memory\", \"memory \\(threads[t].memory) recomputes as \\(state.memory[t])\", step: k, strand: t)\n                    stateKnown = false\n                }\n                if step.source == .prompt, k > 0 || threads.count > 0 {\n                    let likelihoods = threads.indices.map { t -> Double in\n                        probabilities[t] ?? lambdas[t] * Double(threads[t].pknn)\n                    }\n                    let module: [Double]? = threads.allSatisfy { $0.module != nil } ? threads.map { Double($0.module!) } : nil\n                    Gate.observe(&state, likelihoods: likelihoods, module: module, settings: settings)\n                }\n            }\n        }\n        return issues\n    }\n}\n"},{"path":"Sources/BraidCore/Record/Verify/Spans.swift","lines":297,"bytes":14890,"header":{"lines":[1,18],"what":[8,11],"pin":[12,17],"in":null,"out":null},"marks":[],"first":372,"scopes":[["E","CitationMath",null,"public",22,22,[22,25],30,null,-1,0,[]],["f","simTerm",["_"],"public static",24,24,[24,56],24,[23,23],0,8],["f","confidence",["score","support","sourceLoss"],"public static",26,26,[26,92],29,null,0,0],["S","Citation",null,"public",33,33,[33,53],42,[32,32],-1,0],["S","SpanAlternative",null,"public",44,44,[44,60],49,null,-1,0],["E","VerificationStatus",null,"public",51,51,[51,58],53,null,-1,0,["verified","stale","mismatch","tokenizerDrift","missing","unverified"]],["S","SpanVerification",null,"public",55,55,[55,61],65,null,-1,0],["i","init",["status","liveTextSHA256","detail"],"public",60,60,[60,98],64,null,6,0],["S","TokenRange",null,"public",67,67,[67,55],77,null,-1,0],["i","init",["start","end"],"public",71,71,[71,38],74,null,8,0],["v","count",null,"public",76,76,[76,26],76,null,8,8],["S","CitedSpan",null,"public",80,80,[80,54],102,[79,79],-1,0],["E","Kind",null,"public",81,81,[81,48],81,null,11,8,[]],["S","SpanAnnotation",null,"public",105,105,[105,50],110,[104,104],-1,0],["v","uncited",null,"public",109,109,[109,29],109,null,13,8],["S","GlobalHit",null,"",113,113,[113,17],121,[112,112],-1,0],["E","Spans",null,"public",123,123,[123,18],297,null,-1,0,[]],["S","Settings",null,"public",124,124,[124,37],130,null,16,0],["i","init",[],"public",129,129,[129,22],129,null,17,8],["f","ngramKey",["_","_","_"],"public static",133,133,[133,78],135,[132,132],16,0],["f","distinctiveness",["tokens","sharedNgrams"],"public static",137,137,[137,92],142,null,16,0],["f","isBreak",["_","_"],"static",144,144,[144,94],147,null,16,0],["f","globalHits",["_","slots"],"static",152,152,[152,77],163,[149,151],16,0],["f","groupedCitations",["_","token","partitions","threadID"],"static",166,166,[166,134],188,[165,165],16,0],["S","Chain",null,"private",190,190,[190,25],197,null,16,0],["v","totalWeight",null,"",196,196,[196,31],196,null,24,8],["f","annotate",["steps","rowOffsets","taus","partitions","sharedNgrams","threadID","settings"],"public static",200,200,[201,145],204,[199,199],16,0],["f","annotate",["steps","slots","partitions","sharedNgrams","threadID","settings"],"public static",209,209,[210,145],296,[206,208],16,0],["f","sortKey",["_"],"",242,242,[242,71],245,null,27,4]],"text":"//\n//  Spans.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: Turns a generation's per-position hits into citations: groups each token's matching hits\n//        by partition, scores them, and finds verbatim spans — runs of emitted tokens that walk\n//        one partition position by position. A derived view over the session log; nothing here\n//        is stored per token.\n//  PIN:  RaoLM's rules: a hit matches when its value is the token that was chosen; a span needs at\n//        least three tokens, each with a matching hit of rank ≤ 3 at (row, offset + t); overlaps\n//        are resolved greedily (longest, then heaviest), the losers kept as alternatives; break\n//        positions (past a partition's own tokens) are never cited. Confidence is\n//        (simTerm(best cosine) · support · e^{−loss})^{1/3}: evidence of memorisation and retrieval\n//        support, not an influence certificate.\n//\n\nimport Foundation\n\npublic enum CitationMath {\n    /// Cosine 0.5 → 0, cosine 1.0 → 1.\n    public static func simTerm(_ score: Float) -> Float { min(max((score - 0.5) / 0.5, 0), 1) }\n\n    public static func confidence(score: Float, support: Float, sourceLoss: Float) -> Float {\n        let product = simTerm(score) * min(max(support, 0), 1) * exp(-max(sourceLoss, 0))\n        return product > 0 ? Float(pow(Double(product), 1.0 / 3.0)) : 0\n    }\n}\n\n/// Retrieval support for one emitted token, grouped by partition (global rows).\npublic struct Citation: Codable, Sendable, Equatable {\n    public var row: Int\n    public var address: SourceAddress\n    /// Σ weight of the matching hits in this partition (each hit's softmax weight times its strand's w′).\n    public var weight: Float\n    public var bestRank: Int\n    public var bestScore: Float\n    public var sourceLoss: Float\n    public var confidence: Float\n}\n\npublic struct SpanAlternative: Codable, Sendable, Equatable {\n    public var row: Int\n    public var source: SourceAddress\n    public var length: Int\n    public var cumulativeWeight: Float\n}\n\npublic enum VerificationStatus: String, Codable, Sendable {\n    case verified, stale, mismatch, tokenizerDrift, missing, unverified\n}\n\npublic struct SpanVerification: Codable, Sendable, Equatable {\n    public var status: VerificationStatus\n    public var liveTextSHA256: String?\n    public var detail: String?\n\n    public init(status: VerificationStatus, liveTextSHA256: String? = nil, detail: String? = nil) {\n        self.status = status\n        self.liveTextSHA256 = liveTextSHA256\n        self.detail = detail\n    }\n}\n\npublic struct TokenRange: Codable, Sendable, Equatable {\n    public var start: Int\n    public var end: Int\n\n    public init(start: Int, end: Int) {\n        self.start = start\n        self.end = end\n    }\n\n    public var count: Int { end - start }\n}\n\n/// A run of emitted tokens that reproduces a corpus partition verbatim, token by token.\npublic struct CitedSpan: Codable, Sendable, Equatable {\n    public enum Kind: String, Codable, Sendable { case verbatim, promptVerbatim }\n\n    public var kind: Kind\n    /// Positions in prompt ++ generated, half-open.\n    public var tokenRange: TokenRange\n    public var promptTokens: Int\n    public var tokens: [Int32]\n    public var text: String\n    public var row: Int\n    public var source: SourceAddress\n    public var documentName: String\n    public var textSHA256: String\n    public var ranks: [Int]\n    public var weights: [Float]\n    /// Weakest-link confidence over the span's tokens.\n    public var confidence: Float\n    public var meanConfidence: Float\n    /// 1 − (token 3-grams shared by ≥ 2 documents) / (token 3-grams). 0 means boilerplate.\n    public var distinctiveness: Float\n    public var alternatives: [SpanAlternative]\n    public var verification: SpanVerification?\n}\n\n/// Per position, the citations found and the span the token belongs to.\npublic struct SpanAnnotation: Sendable, Equatable {\n    public var citations: [Citation]\n    public var confidence: Float?\n    public var spanIndex: Int?\n    public var uncited: Bool { citations.isEmpty }\n}\n\n/// One matching hit in the braid's global row space, as the span finder sees it.\nstruct GlobalHit {\n    var strand: Int\n    var rank: Int\n    var score: Float\n    var weight: Float\n    var value: Int32\n    var cited: TokenPosition\n    var loss: Float\n}\n\npublic enum Spans {\n    public struct Settings: Sendable {\n        public var rankThreshold = 3\n        public var minSpanLength = 3\n        public var maxCitations = 3\n        public var maxAlternatives = 5\n        public init() {}\n    }\n\n    /// Token 3-grams packed into one integer (token ids are below 2^20).\n    public static func ngramKey(_ a: Int32, _ b: Int32, _ c: Int32) -> UInt64 {\n        (UInt64(UInt32(bitPattern: a) & 0xFFFFF) << 40) | (UInt64(UInt32(bitPattern: b) & 0xFFFFF) << 20) | UInt64(UInt32(bitPattern: c) & 0xFFFFF)\n    }\n\n    public static func distinctiveness(tokens: [Int32], sharedNgrams: Set<UInt64>) -> Float {\n        guard tokens.count >= 3 else { return 0 }\n        var shared = 0\n        for i in 0...(tokens.count - 3) where sharedNgrams.contains(ngramKey(tokens[i], tokens[i + 1], tokens[i + 2])) { shared += 1 }\n        return 1 - Float(shared) / Float(tokens.count - 2)\n    }\n\n    static func isBreak(_ position: TokenPosition, _ partitions: [Int: PartitionRef]) -> Bool {\n        guard let partition = partitions[position.row] else { return false }\n        return position.offset >= partition.tokenCount\n    }\n\n    /// Every strand's hits at a step in the global row space, weighted by the strand's w′ and its\n    /// own softmax over its hits (the mass the mixture gave each). The step's own slots map strand\n    /// t's node-local rows onto the global table.\n    static func globalHits(_ step: Step, slots: [StrandSlot]) -> [GlobalHit] {\n        guard let threads = step.threads else { return [] }\n        var hits: [GlobalHit] = []\n        for (t, record) in threads.enumerated() where t < slots.count {\n            let weights = Mixer.weights(record.hits.map { Double($0.score) }, tau: slots[t].tau)\n            for (i, hit) in record.hits.enumerated() {\n                hits.append(GlobalHit(strand: t, rank: i + 1, score: hit.score, weight: Float(Double(record.weight) * weights[i]), value: hit.value,\n                                      cited: TokenPosition(row: slots[t].rowOffset + Int(hit.row), offset: Int(hit.offset)), loss: hit.loss))\n            }\n        }\n        return hits\n    }\n\n    /// Every partition the token's matching hits come from, strongest first.\n    static func groupedCitations(_ hits: [GlobalHit], token: Int32, partitions: [Int: PartitionRef], threadID: String?) -> [Citation] {\n        var groups: [Int: (weight: Float, best: GlobalHit)] = [:]\n        for hit in hits where hit.value == token && !isBreak(hit.cited, partitions) {\n            let row = hit.cited.row\n            if let existing = groups[row] {\n                let better = hit.score > existing.best.score || (hit.score == existing.best.score && hit.rank < existing.best.rank)\n                groups[row] = (existing.weight + hit.weight, better ? hit : existing.best)\n            } else {\n                groups[row] = (hit.weight, hit)\n            }\n        }\n        let citations: [Citation] = groups.compactMap { row, group in\n            guard let partition = partitions[row] else { return nil }\n            return Citation(row: row, address: partition.address(offset: group.best.cited.offset, threadID: threadID), weight: group.weight,\n                            bestRank: group.best.rank, bestScore: group.best.score, sourceLoss: group.best.loss,\n                            confidence: CitationMath.confidence(score: group.best.score, support: group.weight, sourceLoss: group.best.loss))\n        }\n        return citations.sorted {\n            if $0.weight != $1.weight { return $0.weight > $1.weight }\n            if $0.bestScore != $1.bestScore { return $0.bestScore > $1.bestScore }\n            return $0.row < $1.row\n        }\n    }\n\n    private struct Chain {\n        var start: Int\n        var length: Int\n        var position: TokenPosition\n        var ranks: [Int]\n        var weights: [Float]\n        var totalWeight: Float { weights.reduce(0, +) }\n    }\n\n    /// The same strands at every step.\n    public static func annotate(steps: [Step], rowOffsets: [Int], taus: [Double], partitions: [Int: PartitionRef], sharedNgrams: Set<UInt64> = [],\n                                threadID: String? = nil, settings: Settings = Settings()) -> (annotations: [SpanAnnotation], spans: [CitedSpan]) {\n        let slots = StrandSlots.indexed(rowOffsets: rowOffsets, taus: taus)\n        return annotate(steps: steps, slots: steps.map { _ in slots }, partitions: partitions, sharedNgrams: sharedNgrams, threadID: threadID, settings: settings)\n    }\n\n    /// Citations per step and the selected spans. `steps` are consecutive (step k has index\n    /// `steps[0].index + k`); `slots[k]` names step k's strands (attach and detach move them);\n    /// `partitions` is the braid's global table by row.\n    public static func annotate(steps: [Step], slots: [[StrandSlot]], partitions: [Int: PartitionRef], sharedNgrams: Set<UInt64> = [],\n                                threadID: String? = nil, settings: Settings = Settings()) -> (annotations: [SpanAnnotation], spans: [CitedSpan]) {\n        let hits = steps.indices.map { k in globalHits(steps[k], slots: k < slots.count ? slots[k] : []) }\n        var allCitations: [[Citation]] = []\n        var annotations: [SpanAnnotation] = []\n        for k in steps.indices {\n            let grouped = groupedCitations(hits[k], token: steps[k].token, partitions: partitions, threadID: threadID)\n            allCitations.append(grouped)\n            annotations.append(SpanAnnotation(citations: Array(grouped.prefix(settings.maxCitations)), confidence: grouped.first?.confidence, spanIndex: nil))\n        }\n        var eligible: [[TokenPosition: (rank: Int, weight: Float)]] = steps.indices.map { k in\n            var map: [TokenPosition: (rank: Int, weight: Float)] = [:]\n            for hit in hits[k] where hit.value == steps[k].token && hit.rank <= settings.rankThreshold && !isBreak(hit.cited, partitions) {\n                if let existing = map[hit.cited], existing.rank <= hit.rank { continue }\n                map[hit.cited] = (hit.rank, hit.weight)\n            }\n            return map\n        }\n        var chains: [Chain] = []\n        for k in steps.indices {\n            for position in eligible[k].keys.sorted() {\n                let previous = TokenPosition(row: position.row, offset: position.offset - 1)\n                if k > 0, eligible[k - 1][previous] != nil { continue }\n                var chain = Chain(start: k, length: 0, position: position, ranks: [], weights: [])\n                while k + chain.length < steps.count, let info = eligible[k + chain.length][TokenPosition(row: position.row, offset: position.offset + chain.length)] {\n                    chain.ranks.append(info.rank)\n                    chain.weights.append(info.weight)\n                    chain.length += 1\n                }\n                if chain.length >= settings.minSpanLength { chains.append(chain) }\n            }\n        }\n        eligible.removeAll()\n        func sortKey(_ chain: Chain) -> (Int, Float, String, Int, Int) {\n            let partition = partitions[chain.position.row]\n            return (chain.length, chain.totalWeight, partition?.documentID ?? \"\", partition?.partitionIndex ?? 0, chain.position.offset)\n        }\n        let ordered = chains.sorted { a, b in\n            let ka = sortKey(a), kb = sortKey(b)\n            if ka.0 != kb.0 { return ka.0 > kb.0 }\n            if ka.1 != kb.1 { return ka.1 > kb.1 }\n            if ka.2 != kb.2 { return ka.2 < kb.2 }\n            if ka.3 != kb.3 { return ka.3 < kb.3 }\n            return ka.4 < kb.4\n        }\n        var selected: [Chain] = []\n        var alternatives: [[SpanAlternative]] = []\n        for chain in ordered {\n            let range = chain.start..<(chain.start + chain.length)\n            if let owner = selected.firstIndex(where: { range.overlaps($0.start..<($0.start + $0.length)) }) {\n                if alternatives[owner].count < settings.maxAlternatives, let partition = partitions[chain.position.row] {\n                    alternatives[owner].append(SpanAlternative(row: chain.position.row, source: partition.address(offset: chain.position.offset, threadID: threadID),\n                                                               length: chain.length, cumulativeWeight: chain.totalWeight))\n                }\n                continue\n            }\n            selected.append(chain)\n            alternatives.append([])\n        }\n        let order = selected.indices.sorted { selected[$0].start < selected[$1].start }\n        var spans: [CitedSpan] = []\n        for index in order {\n            let chain = selected[index]\n            guard let partition = partitions[chain.position.row] else { continue }\n            let members = Array(steps[chain.start..<(chain.start + chain.length)])\n            let confidences = members.indices.map { t in allCitations[chain.start + t].first { $0.row == chain.position.row }?.confidence ?? Float(0) }\n            let tokens = members.map(\\.token)\n            let promptTokens = members.filter(\\.isPrompt).count\n            let span = CitedSpan(kind: promptTokens == members.count ? .promptVerbatim : .verbatim,\n                                 tokenRange: TokenRange(start: members[0].index, end: members[members.count - 1].index + 1), promptTokens: promptTokens,\n                                 tokens: tokens, text: members.map(\\.text).joined(), row: chain.position.row,\n                                 source: partition.address(offset: chain.position.offset, threadID: threadID), documentName: partition.documentName,\n                                 textSHA256: partition.textSHA256, ranks: chain.ranks, weights: chain.weights, confidence: confidences.min() ?? 0,\n                                 meanConfidence: Stats.mean(confidences), distinctiveness: distinctiveness(tokens: tokens, sharedNgrams: sharedNgrams),\n                                 alternatives: alternatives[index], verification: nil)\n            let spanIndex = spans.count\n            spans.append(span)\n            for t in 0..<chain.length {\n                let k = chain.start + t\n                annotations[k].spanIndex = spanIndex\n                if let own = allCitations[k].first(where: { $0.row == chain.position.row }) {\n                    annotations[k].citations = Array(([own] + allCitations[k].filter { $0.row != chain.position.row }).prefix(settings.maxCitations))\n                    annotations[k].confidence = own.confidence\n                }\n            }\n        }\n        return (annotations, spans)\n    }\n}\n"},{"path":"Sources/BraidCore/Record/Verify/Verifier.swift","lines":218,"bytes":13490,"header":{"lines":[1,16],"what":[8,15],"pin":null,"in":null,"out":null},"marks":[],"first":401,"scopes":[["E","VerifyStatus",null,"public",20,20,[20,52],20,null,-1,8,[]],["S","SpanCheck",null,"public",22,22,[22,54],31,null,-1,0],["S","TraceCheck",null,"public",33,33,[33,55],41,null,-1,0],["S","VerifyReport",null,"public",43,43,[43,46],57,null,-1,0],["P","PartitionReading",null,"public",60,60,[60,33],62,[59,59],-1,0],["f","partitionText",["documentID","partitionIndex"],"",61,61,null,61,null,4,1],["S","SnapshotPartitionReader",null,"public",64,64,[64,56],74,null,-1,0],["i","init",["snapshots"],"public",66,66,[66,45],72,null,6,0],["f","partitionText",["documentID","partitionIndex"],"public",73,73,[73,89],73,null,6,8],["E","Verifier",null,"public",76,76,[76,21],218,null,-1,0,[]],["f","verify",["session","name","layouts","reader","tokenizer","spanSettings"],"public static",80,80,[81,95],217,null,9,0]],"text":"//\n//  Verifier.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: What a session log proves: its structure and body hashes, the share arithmetic, the gate's\n//        memory recursion (the clamp held), the shadow gate, the trace replayed from the hits over\n//        each strand's index layout, and every verbatim span re-read from the source — the live lane\n//        or the snapshot. The key replay (recomputing cited keys from state checkpoints) is the\n//        model-side check BraidKit adds on top. A log imported from RaoLM takes the checks that\n//        do not depend on Braid's live gate (the report's `skipped` names the rest); where such a\n//        record lacks a strand's hits, the chains that would have started there cannot be replayed,\n//        so a mismatch after that point is counted unreplayable instead of failed.\n//\n\nimport Foundation\n\npublic enum VerifyStatus: String, Codable, Sendable { case ok, failed }\n\npublic struct SpanCheck: Codable, Sendable, Equatable {\n    public var generationID: String\n    public var span: Int\n    public var text: String\n    public var documentID: String\n    public var partitionIndex: Int\n    public var tokenOffset: Int\n    public var status: VerificationStatus\n    public var detail: String?\n}\n\npublic struct TraceCheck: Codable, Sendable, Equatable {\n    public var generationID: String\n    public var strand: Int\n    public var positions: Int\n    public var mismatches: Int\n    /// An imported RaoLM log's mismatches after a position whose hits the record lacks (not failures:\n    /// the seeds there are not in the log).\n    public var unreplayable: Int = 0\n}\n\npublic struct VerifyReport: Codable, Sendable {\n    public var session: String\n    public var createdAt: Date\n    public var generations: Int\n    public var issues: [ReplayIssue]\n    public var traces: [TraceCheck]\n    public var spans: [SpanCheck]\n    public var spansVerified: Int\n    public var spansFailed: Int\n    public var status: VerifyStatus\n    public var notes: [String]\n    /// The checks this log did not take: an imported RaoLM log's memory recursion and shadow β4, and\n    /// the spans when no source was given to re-read them from.\n    public var skipped: [String] = []\n}\n\n/// Reads partition texts for the span check: a snapshot, or a live lane.\npublic protocol PartitionReading {\n    func partitionText(documentID: String, partitionIndex: Int) throws -> String?\n}\n\npublic struct SnapshotPartitionReader: PartitionReading {\n    let texts: [String: [Int: String]]\n    public init(snapshots: [CorpusSnapshot]) {\n        var texts: [String: [Int: String]] = [:]\n        for snapshot in snapshots {\n            for document in snapshot.documents { texts[document.id] = Dictionary(uniqueKeysWithValues: document.partitions.map { ($0.index, $0.text) }) }\n        }\n        self.texts = texts\n    }\n    public func partitionText(documentID: String, partitionIndex: Int) throws -> String? { texts[documentID]?[partitionIndex] }\n}\n\npublic enum Verifier {\n    /// Per strand name, the index layout to replay traces over (nil for strands without an index).\n    public typealias Layouts = (String) -> IndexLayout?\n\n    public static func verify(session: LoggedSession, name: String, layouts: Layouts, reader: PartitionReading?, tokenizer: (any Tokenizing)?,\n                              spanSettings: Spans.Settings = Spans.Settings()) -> VerifyReport {\n        var issues: [ReplayIssue] = []\n        var traces: [TraceCheck] = []\n        var spans: [SpanCheck] = []\n        var notes: [String] = []\n        // Spans are checked token for token against the session's own tokenizer, or not at all.\n        let tokenizerRefused = tokenizer.map { $0.sha256 != session.header.pack.tokenizerSHA256 } ?? false\n        if let tokenizer, tokenizerRefused {\n            issues.append(ReplayIssue(generationID: \"-\", step: nil, strand: nil, check: \"tokenizer\",\n                                      detail: \"the tokenizer \\(tokenizer.sha256.prefix(12)) is not the session's \\(session.header.pack.tokenizerSHA256.prefix(12)); spans are not checked against it\"))\n        }\n        let imported = session.header.source == RaoLMImport.source\n        var skipped = SessionReplay.skipped(for: session.header)\n        if imported {\n            notes.append(\"source raolm: a RaoLM generation imported as a session. RaoLM's gate (its memory lifted by agreement, and in the trajectory arms times exp(β·(trace − mean))) is not Braid's live gate, so the memory recursion and the shadow β4 are not checked; w′ is checked from the logged gate, p and the shares from w′ and each strand's p_lm and p_knn, H_knn from the hits, and the trace is replayed over RaoLM's index layout\")\n        }\n        if reader == nil { skipped.append(\"spans\") }\n        for generation in session.generations {\n            issues += SessionReplay.check(generation, session: session)\n            let strands = SessionReplay.strands(for: generation, session: session)\n            let shared = generation.steps.filter { $0.source != .ctx }\n            // Trace replay per strand: the tracker over the logged hits reproduces every logged chain.\n            // Membership changes inside the generation move strands' indices; a strand attached\n            // mid-generation seeds its chains from the catch-up hits the attach line carries.\n            var current = strands\n            var trackers: [String: TraceTracker] = [:]\n            var tokensSoFar: [Int32] = []\n            var positions: [String: Int] = [:]\n            var mismatches: [String: Int] = [:]\n            var unreplayable: [String: Int] = [:]\n            // An imported record lacks a Thread strand's hits where RaoLM gave its retrieval no weight.\n            var lacking: Set<String> = []\n            for strand in strands where !strand.commons {\n                if let layout = layouts(strand.name) { trackers[strand.name] = TraceTracker(corpus: layout.corpus, rule: session.header.trace) }\n            }\n            var membershipIndex = 0\n            var previousToken: Int32? = nil\n            for (k, step) in generation.steps.enumerated() {\n                while membershipIndex < generation.membership.count, generation.membership[membershipIndex].before == k {\n                    let line = generation.membership[membershipIndex].line\n                    if line.kind == \"attach\" {\n                        current.append(line.thread)\n                        if !line.thread.commons, let layout = layouts(line.thread.name) {\n                            if let hits = line.catchUpHits {\n                                // The catch-up: the same feeds the live tracker got, (token j, hits j) over the prefix but its last position.\n                                var tracker = TraceTracker(corpus: layout.corpus, rule: session.header.trace)\n                                for (j, h) in hits.enumerated() where j + 1 < tokensSoFar.count { _ = tracker.step(token: tokensSoFar[j], hits: h) }\n                                trackers[line.thread.name] = tracker\n                            } else {\n                                // A log written before attach lines carried the catch-up hits: the chains the\n                                // newcomer started with are not in the log, so its trace cannot be replayed.\n                                trackers[line.thread.name] = nil\n                                notes.append(\"\\(line.thread.name) attached at \\(line.position) without catch-up hits in the log; its trace is not replayed\")\n                            }\n                        }\n                    } else if current.indices.contains(line.strand) {\n                        current.remove(at: line.strand)\n                    }\n                    membershipIndex += 1\n                }\n                defer {\n                    previousToken = step.token\n                    if step.source != .ctx { tokensSoFar.append(step.token) }\n                }\n                guard step.source != .ctx, let records = step.threads, records.count == current.count, let token = previousToken else { continue }\n                for (t, strand) in current.enumerated() where !strand.commons {\n                    guard var tracker = trackers[strand.name] else { continue }\n                    // Step j logs the hits that predicted token j and the chain state after feeding (token j−1, those hits).\n                    let state = tracker.step(token: token, hits: records[t].hits)\n                    trackers[strand.name] = tracker\n                    positions[strand.name, default: 0] += 1\n                    if let logged = records[t].trace, logged.length != state.length || logged.next != state.next {\n                        if lacking.contains(strand.name) { unreplayable[strand.name, default: 0] += 1 } else { mismatches[strand.name, default: 0] += 1 }\n                    }\n                    // Hits seed chains for the tokens after this one, so a lack here leaves later states unknown.\n                    if imported, records[t].hits.isEmpty { lacking.insert(strand.name) }\n                }\n            }\n            for (name, count) in positions.sorted(by: { $0.key < $1.key }) {\n                let misses = mismatches[name] ?? 0\n                let index = (session.header.threads + session.membership.filter { $0.kind == \"attach\" }.map(\\.thread)).firstIndex { $0.name == name } ?? 0\n                let unknown = unreplayable[name] ?? 0\n                traces.append(TraceCheck(generationID: generation.gen.generationID, strand: index, positions: count, mismatches: misses, unreplayable: unknown))\n                if misses > 0 {\n                    issues.append(ReplayIssue(generationID: generation.gen.generationID, step: nil, strand: index, check: \"trace\", detail: \"\\(name): \\(misses) of \\(count) chain states differ on replay\"))\n                }\n                if unknown > 0 {\n                    notes.append(\"\\(name): \\(unknown) of \\(count) chain states differ after a position whose hits the RaoLM record lacks (RaoLM pooled none of them there); not replayable\")\n                }\n            }\n            // Spans from the log, re-read from the source.\n            guard let reader, let end = generation.end, !tokenizerRefused else { continue }\n            let partitions = Dictionary(uniqueKeysWithValues: end.partitions.map { ($0.row, $0) })\n            // Each step read through the strands it was recorded with (attach and detach move indices).\n            let allSlots = SessionReplay.slots(for: generation, session: session)\n            let sharedSlots = generation.steps.indices.filter { generation.steps[$0].source != .ctx }.map { allSlots[$0] }\n            let (_, found) = Spans.annotate(steps: shared, slots: sharedSlots, partitions: partitions, settings: spanSettings)\n            for (i, span) in found.enumerated() where span.kind == .verbatim {\n                var check = SpanCheck(generationID: generation.gen.generationID, span: i, text: span.text, documentID: span.source.documentID, partitionIndex: span.source.partitionIndex,\n                                      tokenOffset: span.source.tokenOffset, status: .unverified, detail: nil)\n                do {\n                    guard let live = try reader.partitionText(documentID: span.source.documentID, partitionIndex: span.source.partitionIndex) else {\n                        check.status = .missing\n                        spans.append(check)\n                        continue\n                    }\n                    if ContentHash.sha256Hex(live) != span.textSHA256 {\n                        check.status = .stale\n                        check.detail = \"live text \\(ContentHash.sha256Hex(live).prefix(12)) ≠ indexed \\(span.textSHA256.prefix(12))\"\n                    } else if let tokenizer, tokenizer.sha256 == session.header.pack.tokenizerSHA256 {\n                        let tokens = tokenizer.encode(live)\n                        let range = span.source.tokenOffset ..< span.source.tokenOffset + span.tokens.count\n                        if range.upperBound <= tokens.count, Array(tokens[range]) == span.tokens {\n                            check.status = .verified\n                        } else if range.upperBound <= tokens.count, tokenizer.decode(Array(tokens[range])) == span.text {\n                            check.status = .tokenizerDrift\n                        } else {\n                            check.status = .mismatch\n                            check.detail = \"tokens at offset \\(span.source.tokenOffset) differ\"\n                        }\n                    } else {\n                        check.status = .verified\n                        check.detail = \"text hash only (no tokenizer)\"\n                    }\n                } catch {\n                    check.status = .missing\n                    check.detail = \"\\(error)\"\n                }\n                spans.append(check)\n            }\n        }\n        let verified = spans.filter { $0.status == .verified }.count\n        let failed = spans.count - verified\n        return VerifyReport(session: name, createdAt: Date(timeIntervalSince1970: Date().timeIntervalSince1970.rounded(.down)), generations: session.generations.count,\n                            issues: issues, traces: traces, spans: spans, spansVerified: verified, spansFailed: failed,\n                            status: issues.isEmpty && failed == 0 ? .ok : .failed, notes: notes, skipped: skipped)\n    }\n}\n"},{"path":"Sources/BraidCore/Strand/AnswerStop.swift","lines":23,"bytes":857,"header":{"lines":[1,10],"what":[8,9],"pin":null,"in":null,"out":null},"marks":[],"first":412,"scopes":[["E","AnswerStop",null,"public",16,16,[16,23],23,[14,15],-1,0,[]],["f","sentenceEnded",["previous","next"],"public static",17,17,[17,77],22,null,0,0]],"text":"//\n//  AnswerStop.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: Where an answer ends: the rule a generation stops on (`stop: sentence`) and that\n//        followed credit closes a sentence with.\n//\n\nimport Foundation\n\n/// Where an answer ends: a sentence ends when the text so far ends in `.?!` and the next token\n/// opens with whitespace or a capital, or when the next token holds a newline.\npublic enum AnswerStop {\n    public static func sentenceEnded(previous: String, next: String) -> Bool {\n        if next.contains(\"\\n\") { return true }\n        guard let last = previous.last(where: { !$0.isWhitespace }), \".?!\".contains(last) else { return false }\n        guard let first = next.first else { return false }\n        return first.isWhitespace || first.isNewline || first.isUppercase\n    }\n}\n"},{"path":"Sources/BraidCore/Strand/Cluster.swift","lines":491,"bytes":27377,"header":{"lines":[1,16],"what":[8,12],"pin":[13,15],"in":null,"out":null},"marks":[[147,"Membership"],[258,"Generation"]],"first":414,"scopes":[["S","ClusterSettings",null,"public",20,20,[20,40],33,null,-1,0],["i","init",[],"public",32,32,[32,18],32,null,0,8],["S","Generation",null,"public",36,36,[36,35],51,[35,35],-1,0],["v","text",null,"public",49,49,[49,28],49,null,2,8],["v","generated",null,"public",50,50,[50,33],50,null,2,8],["E","ClusterEvent",null,"public",53,53,[53,35],57,null,-1,0,["attached","detached","step"]],["E","ClusterError",null,"public",59,59,[59,57],73,null,-1,0,["duplicate","unknown","commonsTwice","noStrands"]],["v","description",null,"public",65,65,[65,35],72,null,6,0],["C","Cluster",null,"public final",75,75,[75,27],491,null,-1,0],["S","Member",null,"",76,76,[76,18],85,null,8,0],["E","Pending",null,"private",87,87,[87,25],87,null,8,8,[]],["i","init",["reed","tokenizer","pack","settings","sessionID"],"public",105,105,[105,173],111,null,8,0],["v","strandNames",null,"public",113,113,[113,37],113,null,8,8],["v","commonsIndex",null,"public",114,114,[114,34],114,null,8,8],["v","strandRecords",null,"public",115,115,[115,46],115,null,8,8],["v","partitions",null,"public",116,116,[116,47],116,null,8,8],["f","rowOffsets",[],"public",117,117,[117,38],117,null,8,8],["f","contextRefs",["_"],"public",121,121,[121,79],127,[119,120],8,0],["v","slots",null,"public",130,130,[130,35],132,[129,129],8,0],["f","taus",[],"public",133,133,[133,35],133,null,8,8],["f","startLog",["at"],"public",136,136,[136,45],140,[135,135],8,0],["f","closeLog",[],"public",142,142,[142,27],145,null,8,0],["f","attach",["_"],"public",150,150,[150,48],156,[149,149],8,0],["f","detach",["_"],"public",158,158,[158,46],164,null,8,0],["f","cancel",[],"public",166,166,[166,25],171,null,8,0],["f","admit",["_","position","tokens","into","module","trackers","emissions"],"private",175,175,[175,201],223,null,8,0],["f","admit",["_","position","tokens"],"private",225,225,[225,81],231,null,8,0],["f","dismiss",["_","position","session","gate","module","trackers","emissions"],"private",233,233,[233,198],246,null,8,0],["f","dismiss",["_","position","session"],"private",248,248,[248,84],254,null,8,0],["f","generate",["prompt","contexts","params","onStep"],"public",262,262,[263,79],473,[260,261],8,0],["f","record",["position","token","source","memory","expertsAt","mixture","traces","evidence","candidates","stop"],"",332,332,[333,106],355,null,29,4],["f","applyPending",["position","tokens","gate","module","trackers","emissions"],"private",475,475,[475,182],490,null,8,0]],"text":"//\n//  Cluster.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The braid at run time: the strands attached (Threads and the commons), the one reed,\n//        the gate, and the generation loop that mixes every position, chooses, records a step and\n//        advances every node. Strands attach and detach at token boundaries; a strand that joins\n//        catches up on the session so far with one forward. Every generation writes the session\n//        log that `braid verify` replays.\n//  PIN:  The final distribution is the cluster's output, not any node's. Every number that chooses\n//        a token or sets a share is Double on the CPU. Trace is computed here from the hits, so it\n//        is a function of the log; the shadow β4 gate is computed and logged, never applied.\n//\n\nimport Foundation\n\npublic struct ClusterSettings: Sendable {\n    public var gate = GateSettings()\n    public var trace = TraceRule.standard\n    /// The trajectory module's settings. It runs in every session, so its e_t is logged (`mod`) beside\n    /// the shadow β4 at every prompt and context position; its evidence enters the gate only when\n    /// `gate.moduleGain` (κ) is above 0. Nil turns it off.\n    public var module: ModuleSettings? = ModuleSettings()\n    public var k = 16\n    public var hitsLogged = 16\n    public var candidates = 3\n    public var spans = Spans.Settings()\n\n    public init() {}\n}\n\n/// What a generation returns: the lines as logged plus the derived views.\npublic struct Generation: Sendable {\n    public var gen: GenerationLine\n    public var steps: [Step]\n    public var end: EndLine\n    public var strands: [SessionThread]\n    public var annotations: [SpanAnnotation]\n    public var spans: [CitedSpan]\n    public var credits: [CreditRow?]\n    public var decisions: [FollowDecision]\n    public var royalties: RoyaltiesView\n    /// Per step (aligned with `steps`), the strands its records are in.\n    public var slots: [[StrandSlot]] = []\n\n    public var text: String { end.text }\n    public var generated: [Step] { steps.filter { !$0.isPrompt } }\n}\n\npublic enum ClusterEvent: Sendable {\n    case attached(name: String, position: Int, caughtUp: Int, seconds: Double)\n    case detached(name: String, position: Int)\n    case step(Step)\n}\n\npublic enum ClusterError: Error, CustomStringConvertible {\n    case duplicate(String)\n    case unknown(String)\n    case commonsTwice\n    case noStrands\n\n    public var description: String {\n        switch self {\n        case .duplicate(let name): return \"a strand named \\(name) is already attached\"\n        case .unknown(let name): return \"no strand named \\(name)\"\n        case .commonsTwice: return \"a braid has one commons\"\n        case .noStrands: return \"no strands attached\"\n        }\n    }\n}\n\npublic final class Cluster {\n    struct Member {\n        var node: any Node\n        var descriptor: NodeDescriptor\n        var layout: IndexLayout?\n        var corpus: TraceCorpus?\n        var rowOffset: Int\n        var tau: Double\n        var lambdaScale: Double\n        var record: SessionThread\n    }\n\n    private enum Pending { case attach(any Node), detach(String) }\n\n    public let reed: any Reed\n    public let tokenizer: any Tokenizing\n    public let pack: PackIdentity\n    public var settings: ClusterSettings\n    var members: [Member] = []\n    public private(set) var writer: SessionWriter?\n    public let sessionID: String\n    public var onEvent: ((ClusterEvent) -> Void)?\n\n    private var pending: [Pending] = []\n    private let lock = NSLock()\n    private var partitionTable: [Int: PartitionRef] = [:]\n    private var sharedNgrams: Set<UInt64> = []\n    private var nextRow = 0\n    private var cancelled = false\n\n    public init(reed: any Reed, tokenizer: any Tokenizing, pack: PackIdentity, settings: ClusterSettings = ClusterSettings(), sessionID: String = SessionLog.newSessionID()) {\n        self.reed = reed\n        self.tokenizer = tokenizer\n        self.pack = pack\n        self.settings = settings\n        self.sessionID = sessionID\n    }\n\n    public var strandNames: [String] { members.map(\\.descriptor.name) }\n    public var commonsIndex: Int? { members.firstIndex { $0.descriptor.isCommons } }\n    public var strandRecords: [SessionThread] { members.map(\\.record) }\n    public var partitions: [Int: PartitionRef] { partitionTable }\n    public func rowOffsets() -> [Int] { members.map(\\.rowOffset) }\n\n    /// The context lines a generation with these per-Thread contexts logs: one per attached Thread\n    /// (never the commons) that has a context, by its strand index now.\n    public func contextRefs(_ contexts: [String: NodeContext]) -> [ContextRef] {\n        members.enumerated().compactMap { t, member in\n            guard !member.descriptor.isCommons, let context = contexts[member.descriptor.name] else { return nil }\n            return ContextRef(strand: t, tokens: context.tokens, score: context.score, documentID: context.documentID,\n                              row: context.position.row, offset: context.position.offset)\n        }\n    }\n\n    /// The members as slots, now.\n    public var slots: [StrandSlot] {\n        members.map { StrandSlot(name: $0.descriptor.name, rowOffset: $0.rowOffset, rowCount: $0.record.rowCount, tau: $0.tau, commons: $0.descriptor.isCommons) }\n    }\n    public func taus() -> [Double] { members.map(\\.tau) }\n\n    /// Starts writing the session log at `url` (the header names the strands attached now).\n    public func startLog(at url: URL) throws {\n        let header = SessionHeader(sessionID: sessionID, pack: pack, gate: settings.gate, trace: settings.trace, module: settings.module,\n                                   hitsLogged: settings.hitsLogged, threads: strandRecords)\n        writer = try SessionWriter(url: url, header: header)\n    }\n\n    public func closeLog() {\n        writer?.close()\n        writer = nil\n    }\n\n    // MARK: Membership\n\n    /// Attaches a node now, or at the next token boundary while a generation runs.\n    public func attach(_ node: any Node) throws {\n        lock.lock()\n        let running = generating\n        if running { pending.append(.attach(node)) }\n        lock.unlock()\n        if !running { try admit(node, position: 0, tokens: nil) }\n    }\n\n    public func detach(_ name: String) throws {\n        lock.lock()\n        let running = generating\n        if running { pending.append(.detach(name)) }\n        lock.unlock()\n        if !running { try dismiss(name, position: 0, session: nil) }\n    }\n\n    public func cancel() {\n        lock.lock()\n        cancelled = true\n        lock.unlock()\n        for member in members { member.node.cancel() }\n    }\n\n    private var generating = false\n\n    private func admit(_ node: any Node, position: Int, tokens: [Int32]?, into gate: inout GateState? , module: inout LiveModule?, trackers: inout [TraceTracker?], emissions: inout [NodeStep?]) throws {\n        let descriptor = node.descriptor\n        guard !members.contains(where: { $0.descriptor.name == descriptor.name }) else { throw ClusterError.duplicate(descriptor.name) }\n        if descriptor.isCommons, commonsIndex != nil { throw ClusterError.commonsTwice }\n        try Conformance.check(descriptor, vocabularySHA256: reed.vocabularySHA256, packSHA256: pack.sha256, hiddenSize: reed.hiddenSize, tokenizerSHA256: tokenizer.sha256,\n                              seamSHA256: pack.seamSHA256)\n        let layout = try node.layout()\n        let rowOffset = nextRow\n        if let layout {\n            for partition in layout.partitions {\n                var global = partition\n                global.row = rowOffset + partition.row\n                global.threadID = partition.threadID ?? descriptor.threadID ?? descriptor.name\n                partitionTable[global.row] = global\n            }\n            nextRow += (layout.partitions.map(\\.row).max() ?? -1) + 1\n            sharedNgrams.formUnion(layout.sharedNgrams)\n        }\n        let lambdaScale = Double(descriptor.lambdaScale)\n        let record = SessionThread(descriptor: descriptor, lambda: Float(lambdaScale * Double(currentLambda)), rowOffset: rowOffset, rowCount: layout?.partitions.count ?? 0)\n        let member = Member(node: node, descriptor: descriptor, layout: layout, corpus: layout?.corpus, rowOffset: rowOffset, tau: Double(descriptor.tau),\n                            lambdaScale: lambdaScale, record: record)\n        members.append(member)\n        var caughtUp = 0\n        var catchUpHits: [[Hit]]? = nil\n        let started = Date()\n        if let tokens {\n            // Mid-session: one forward over the prefix brings the newcomer level.\n            let steps = try node.open(session: sessionID, tokens: tokens, k: settings.k)\n            emissions.append(steps.last)\n            caughtUp = tokens.count\n            catchUpHits = steps.map { Array($0.hits.prefix(settings.hitsLogged)) }\n            var tracker = layout.map { TraceTracker(corpus: $0.corpus, rule: settings.trace) }\n            if var t = tracker {\n                for (j, step) in steps.enumerated() where j + 1 < tokens.count { _ = t.step(token: tokens[j], hits: step.hits) }\n                tracker = t\n            }\n            trackers.append(tracker)\n            gate?.commons = commonsIndex\n            if gate != nil { Gate.attach(&gate!) }\n            module?.attach()\n        }\n        let seconds = Date().timeIntervalSince(started)\n        if tokens != nil {\n            try writer?.membership(MembershipLine(kind: \"attach\", strand: members.count - 1, thread: record, position: position, caughtUp: caughtUp,\n                                                 seconds: seconds, memory: gate?.memory.map(Float.init) ?? [], catchUpHits: catchUpHits))\n        }\n        onEvent?(.attached(name: descriptor.name, position: position, caughtUp: caughtUp, seconds: seconds))\n    }\n\n    private func admit(_ node: any Node, position: Int, tokens: [Int32]?) throws {\n        var gate: GateState? = nil\n        var module: LiveModule? = nil\n        var trackers: [TraceTracker?] = []\n        var emissions: [NodeStep?] = []\n        try admit(node, position: position, tokens: tokens, into: &gate, module: &module, trackers: &trackers, emissions: &emissions)\n    }\n\n    private func dismiss(_ name: String, position: Int, session: SessionID?, gate: inout GateState?, module: inout LiveModule?, trackers: inout [TraceTracker?], emissions: inout [NodeStep?]) throws {\n        guard let index = members.firstIndex(where: { $0.descriptor.name == name }) else { throw ClusterError.unknown(name) }\n        let member = members.remove(at: index)\n        if let session { member.node.close(session: session) }\n        if trackers.indices.contains(index) { trackers.remove(at: index) }\n        if emissions.indices.contains(index) { emissions.remove(at: index) }\n        if gate != nil { Gate.detach(&gate!, at: index) }\n        module?.detach(at: index)\n        if session != nil {\n            try writer?.membership(MembershipLine(kind: \"detach\", strand: index, thread: member.record, position: position, caughtUp: 0, seconds: 0,\n                                                 memory: gate?.memory.map(Float.init) ?? []))\n        }\n        onEvent?(.detached(name: name, position: position))\n    }\n\n    private func dismiss(_ name: String, position: Int, session: SessionID?) throws {\n        var gate: GateState? = nil\n        var module: LiveModule? = nil\n        var trackers: [TraceTracker?] = []\n        var emissions: [NodeStep?] = []\n        try dismiss(name, position: position, session: session, gate: &gate, module: &module, trackers: &trackers, emissions: &emissions)\n    }\n\n    private var currentLambda: Float = 0.5\n\n    // MARK: Generation\n\n    /// Runs one generation: scores the prompt, generates up to `params.maxTokens`, logs every\n    /// position, advances every node, applies attach/detach at token boundaries.\n    public func generate(prompt: GenerationPrompt, contexts: [String: NodeContext] = [:], params: GenerationParameters = GenerationParameters(),\n                         onStep: ((Step) -> Void)? = nil) throws -> Generation {\n        guard !members.isEmpty else { throw ClusterError.noStrands }\n        lock.lock()\n        generating = true\n        cancelled = false\n        lock.unlock()\n        defer {\n            lock.lock()\n            generating = false\n            lock.unlock()\n        }\n        currentLambda = params.lambda\n        for i in members.indices { members[i].record.lambda = Float(members[i].lambdaScale * Double(params.lambda)) }\n        let eos = tokenizer.eos\n        var tokens: [Int32] = [eos] + prompt.tokens\n        let promptCount = tokens.count\n        let strands = strandRecords\n        let generationID = SessionLog.generationID(pack: pack, threads: strands, gateFingerprint: settings.gate.fingerprint, prompt: prompt, params: params)\n        let contextRefs = self.contextRefs(contexts)\n        var contextTokens: [[Int32]] = members.map { _ in [] }\n        for ref in contextRefs { contextTokens[ref.strand] = ref.tokens }\n        let gen = GenerationLine(generationID: generationID, prompt: prompt, context: contextRefs.isEmpty ? nil : contextRefs, params: params, strands: strandNames)\n        try writer?.begin(gen)\n        var steps: [Step] = []\n        var stepSlots: [[StrandSlot]] = []\n        var touched = Set<Int>()\n        var rng = SplitMix64(seed: params.seed)\n\n        // Open every strand on eos ‖ its context ‖ prompt.\n        var emissions: [NodeStep?] = []\n        var trackers: [TraceTracker?] = []\n        var promptEmissions: [[NodeStep]] = []\n        for (t, member) in members.enumerated() {\n            let own = [eos] + contextTokens[t] + prompt.tokens\n            let opened = try member.node.open(session: sessionID, tokens: own, k: settings.k)\n            promptEmissions.append(opened)\n            emissions.append(opened.last)\n            trackers.append(member.corpus.map { TraceTracker(corpus: $0, rule: settings.trace) })\n        }\n        var gate = GateState(strands: members.count, commons: commonsIndex, prior: settings.gate.commonsPrior)\n        var module = settings.module.map { LiveModule(strands: members.count, commons: commonsIndex, settings: $0) }\n        var moduleEvidence: [Double]? = nil\n\n        // Context positions: each strand's own words before the stem, logged as ctx lines and run\n        // through its tracker so a chain is live when the stem begins. The module reads them too (the\n        // runway before a short stem): each ctx line logs the e_t the strand's next observation would\n        // carry. The gate observes nothing here.\n        for t in members.indices where !contextTokens[t].isEmpty {\n            let own = contextTokens[t]\n            let logits = try reed.logits(promptEmissions[t].prefix(own.count).map(\\.state))\n            for c in 1...own.count {\n                let emission = promptEmissions[t][c - 1]\n                let expert = Expert(hits: emission.hits, tau: members[t].tau, logits: logits[c - 1], lambda: members[t].lambdaScale * Double(params.lambda))\n                let state = trackers[t]?.step(token: c == 1 ? eos : own[c - 2], hits: promptEmissions[t][c - 1].hits)\n                let record = ThreadRecord(memory: Float(gate.memory[t]), weight: 1, open: true, plm: expert.plm.map { Float($0[Int(own[c - 1])]) },\n                                          pknn: Float(expert.knn[Int(own[c - 1])] ?? 0), share: 1, hlm: expert.lmEntropy.map(Float.init), hknn: Float(expert.knnEntropy),\n                                          module: module.map { Float($0.evidence(strand: t)) }, shadowGate: 1, shadowShare: 1,\n                                          hits: Array(emission.hits.prefix(settings.hitsLogged)), trace: state)\n                let step = Step(index: c, token: own[c - 1], text: tokenizer.text(own[c - 1]), source: .ctx, owner: t, prob: expert.probability(of: Int(own[c - 1])).map(Float.init) ?? 0,\n                                lambda: Float(expert.lambda), threads: [record])\n                try writer?.append(step)\n                steps.append(step)\n                stepSlots.append([slots[t]])\n                module?.pushContext(record, strand: t)\n            }\n        }\n        // Every strand's e_t for the first prompt observation (0 before any reading).\n        moduleEvidence = module?.evidence()\n\n        func record(position j: Int, token: Int32, source: StepSource, memory: [Double], expertsAt: [Expert], mixture: Mixture, traces: [TraceState?], evidence: [Double]?,\n                    candidates: [(token: Int, prob: Double, parts: [Double])], stop: StopReason?) -> Step {\n            let y = Int(token)\n            let shares = Mixer.shares(mixture, experts: expertsAt, token: y)\n            let traceValues = traces.map { Double($0?.trace ?? 0) }\n            let shadowGates = Gate.shadowWeights(GateState(memoryOnly: memory, commons: commonsIndex), traces: traceValues, beta: settings.gate.shadowBeta)\n            let shadowWeights = Gate.renormalised(shadowGates, open: mixture.open)\n            let shadowP = expertsAt.indices.reduce(0.0) { $0 + (mixture.open[$1] ? shadowWeights[$1] * (expertsAt[$1].probability(of: y) ?? 0) : 0) }\n            let records = expertsAt.indices.map { t -> ThreadRecord in\n                let expert = expertsAt[t]\n                for hit in expert.hits { touched.insert(members[t].rowOffset + Int(hit.row)) }\n                if let row = traces[t]?.row { touched.insert(members[t].rowOffset + Int(row)) }\n                let shadowShare = shadowP > 0 && mixture.open[t] ? shadowWeights[t] * (expert.probability(of: y) ?? 0) / shadowP : 0\n                return ThreadRecord(memory: Float(memory[t]), weight: Float(mixture.weights[t]), open: mixture.open[t],\n                                    plm: expert.plm.map { Float(y < $0.count ? $0[y] : 0) }, pknn: Float(expert.knn[y] ?? 0), share: Float(shares[t]),\n                                    hlm: expert.lmEntropy.map(Float.init), hknn: Float(expert.knnEntropy), evidence: evidence.map { Float($0[t]) },\n                                    module: moduleEvidence.map { Float($0[t]) }, shadowGate: Float(shadowGates[t]), shadowShare: Float(shadowShare),\n                                    hits: Array(expert.hits.prefix(settings.hitsLogged)), trace: traces[t])\n            }\n            return Step(index: j, token: token, text: tokenizer.text(token), source: source, prob: Float(y < mixture.mixed.count ? mixture.mixed[y] : 0),\n                        lambda: Float(mixture.lambda), threads: records,\n                        candidates: candidates.map { Candidate(token: Int32($0.token), text: tokenizer.text(Int32($0.token)), prob: Float($0.prob), parts: $0.parts.map(Float.init)) },\n                        stop: stop)\n        }\n\n        // The eos opener: no strands predicted it.\n        let opener = Step(index: 0, token: eos, text: tokenizer.text(eos), source: .prompt, prob: 1, lambda: params.lambda, threads: nil)\n        try writer?.append(opener)\n        steps.append(opener)\n        stepSlots.append(slots)\n        onStep?(opener)\n\n        // Prompt positions: every strand asked, evidence observed.\n        var promptLogits: [[[Float]]] = []\n        for t in members.indices {\n            let states = promptEmissions[t].dropFirst(contextTokens[t].count).map(\\.state)\n            promptLogits.append(try reed.logits(Array(states)))\n        }\n        for j in 1..<promptCount {\n            let experts = members.indices.map { t -> Expert in\n                let local = contextTokens[t].count + j - 1\n                return Expert(hits: promptEmissions[t][local].hits, tau: members[t].tau, logits: promptLogits[t][j - 1], lambda: members[t].lambdaScale * Double(params.lambda))\n            }\n            let traces: [TraceState?] = members.indices.map { t in\n                let local = contextTokens[t].count + j - 1\n                return trackers[t]?.step(token: tokens[j - 1], hits: promptEmissions[t][local].hits)\n            }\n            let gates = Gate.weights(gate)\n            let open = members.map { _ in true }\n            let mixture = Mixer.mix(experts: experts, gates: gates, open: open, vocabulary: reed.vocabulary)\n            let y = Int(tokens[j])\n            let likelihoods = experts.indices.map { t in experts[t].probability(of: y) ?? experts[t].lowerBound(of: y) }\n            let memory = gate.memory\n            let evidence = Gate.observe(&gate, likelihoods: likelihoods, module: moduleEvidence, settings: settings.gate)\n            let step = record(position: j, token: tokens[j], source: .prompt, memory: memory, expertsAt: experts, mixture: mixture, traces: traces,\n                              evidence: evidence, candidates: Mixer.candidates(mixture, experts: experts, count: settings.candidates), stop: nil)\n            try writer?.append(step)\n            steps.append(step)\n            stepSlots.append(slots)\n            onStep?(step)\n            onEvent?(.step(step))\n            if var m = module { moduleEvidence = m.push(step); module = m }\n        }\n\n        // Generation.\n        var generatedText = \"\"\n        var stopped: StopReason? = nil\n        var position = promptCount\n        while position - promptCount < params.maxTokens {\n            try applyPending(position: position, tokens: tokens, gate: &gate, module: &module, trackers: &trackers, emissions: &emissions)\n            // Attach and detach move strands: each strand's e_t follows it (a newcomer starts at 0).\n            if let m = module { moduleEvidence = m.evidence() }\n            lock.lock()\n            let stop = cancelled\n            lock.unlock()\n            if stop { stopped = .max; break }\n            guard !members.isEmpty else { throw ClusterError.noStrands }\n            let states = emissions.map { $0?.state ?? [] }\n            let logits = try reed.logits(states)\n            let experts = members.indices.map { t in\n                Expert(hits: emissions[t]?.hits ?? [], tau: members[t].tau, logits: logits[t], lambda: members[t].lambdaScale * Double(params.lambda))\n            }\n            let traces: [TraceState?] = members.indices.map { t in trackers[t]?.step(token: tokens[position - 1], hits: emissions[t]?.hits ?? []) }\n            let gates = Gate.weights(gate)\n            let open = Gate.open(gates, commons: commonsIndex, floor: Gate.floor(settings.gate.openFloor, strands: members.count))\n            let mixture = Mixer.mix(experts: experts, gates: gates, open: open, vocabulary: reed.vocabulary)\n            let token: Int\n            if params.temperature > 0 {\n                var tempered = [Double](repeating: 0, count: reed.vocabulary)\n                for t in experts.indices where mixture.reedWeights[t] > 0 && mixture.weights[t] > 0 {\n                    let p = Mixer.softmax(logits[t], temperature: Double(params.temperature))\n                    for i in 0..<min(p.count, tempered.count) { tempered[i] += mixture.reedWeights[t] * (1 - mixture.lambda) * p[i] }\n                }\n                for t in experts.indices where mixture.knnWeights[t] > 0 && mixture.weights[t] > 0 {\n                    for (tok, v) in experts[t].knn where tok >= 0 && tok < tempered.count { tempered[tok] += mixture.knnWeights[t] * mixture.lambda * v }\n                }\n                token = Mixer.sample(tempered, topK: params.topK, rng: &rng)\n            } else {\n                token = Mixer.choose(mixture.mixed) { candidate in\n                    Mixer.citedAge(candidate, experts: experts, mixture: mixture) { t, row in self.partitionTable[self.members[t].rowOffset + Int(row)]?.createdAt }\n                }\n            }\n            let text = tokenizer.text(Int32(token))\n            var reason: StopReason? = nil\n            if Int32(token) == eos { reason = .eos }\n            else if params.stopAtSentenceEnd, !generatedText.isEmpty, AnswerStop.sentenceEnded(previous: generatedText, next: text) { reason = .sentence }\n            if reason == .sentence { stopped = .sentence; break }\n            let last = position - promptCount + 1 == params.maxTokens\n            let step = record(position: position, token: Int32(token), source: .gen, memory: gate.memory, expertsAt: experts, mixture: mixture, traces: traces,\n                              evidence: nil, candidates: Mixer.candidates(mixture, experts: experts, count: settings.candidates),\n                              stop: reason ?? (last ? .max : nil))\n            try writer?.append(step)\n            steps.append(step)\n            stepSlots.append(slots)\n            onStep?(step)\n            onEvent?(.step(step))\n            if var m = module { moduleEvidence = m.push(step); module = m }\n            if reason == .eos { stopped = .eos; break }\n            tokens.append(Int32(token))\n            generatedText += text\n            position += 1\n            if last { stopped = .max; break }\n            for t in members.indices { emissions[t] = try members[t].node.advance(session: sessionID, token: Int32(token), k: settings.k) }\n        }\n        for member in members { member.node.close(session: sessionID) }\n\n        let touchedPartitions = touched.sorted().compactMap { partitionTable[$0] }\n        let end = try writer?.end(generationID: generationID, tokens: tokens.count, generated: tokens.count - promptCount, stoppedOn: stopped, text: generatedText,\n                                  partitions: touchedPartitions)\n            ?? EndLine(generationID: generationID, tokens: tokens.count, generated: tokens.count - promptCount, stoppedOn: stopped, text: generatedText,\n                       partitions: touchedPartitions, bodySHA256: \"\")\n        // The derived views, each step read through the strands it was recorded with.\n        let sharedIndices = steps.indices.filter { steps[$0].source != .ctx }\n        let shared = sharedIndices.map { steps[$0] }\n        let sharedSlots = sharedIndices.map { stepSlots[$0] }\n        let (annotations, spans) = Spans.annotate(steps: shared, slots: sharedSlots, partitions: partitionTable, sharedNgrams: sharedNgrams, settings: settings.spans)\n        var credits = Credit.assign(shared, slots: sharedSlots)\n        let decisions = FollowedCredit.apply(&credits, steps: shared, slots: sharedSlots, partitions: partitionTable)\n        let royalties = Royalties.view(steps: shared, credits: credits, slots: sharedSlots, partitions: partitionTable)\n        return Generation(gen: gen, steps: steps, end: end, strands: strands, annotations: annotations, spans: spans, credits: credits, decisions: decisions,\n                          royalties: royalties, slots: stepSlots)\n    }\n\n    private func applyPending(position: Int, tokens: [Int32], gate: inout GateState, module: inout LiveModule?, trackers: inout [TraceTracker?], emissions: inout [NodeStep?]) throws {\n        lock.lock()\n        let queued = pending\n        pending = []\n        lock.unlock()\n        for op in queued {\n            var g: GateState? = gate\n            switch op {\n            case .attach(let node):\n                try admit(node, position: position, tokens: tokens, into: &g, module: &module, trackers: &trackers, emissions: &emissions)\n            case .detach(let name):\n                try dismiss(name, position: position, session: sessionID, gate: &g, module: &module, trackers: &trackers, emissions: &emissions)\n            }\n            if let g { gate = g }\n        }\n    }\n}\n"},{"path":"Sources/BraidCore/Strand/Conformance.swift","lines":53,"bytes":3183,"header":{"lines":[1,11],"what":[8,10],"pin":null,"in":null,"out":null},"marks":[],"first":446,"scopes":[["E","Conformance",null,"public",16,16,[16,24],53,[15,15],-1,0,[]],["E","Failure",null,"public",17,17,[17,67],33,null,0,0,["vocabulary","pack","hiddenSize","tokenizer","seam"]],["v","description",null,"public",24,24,[24,39],32,null,1,0],["f","check",["_","vocabularySHA256","packSHA256","hiddenSize","tokenizerSHA256","seamSHA256"],"public static",37,37,[38,63],52,[35,36],0,0]],"text":"//\n//  Conformance.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The checks every node passes before it joins a braid: the reed's vocabulary, its hidden\n//        size, the braid's pack (the commons is exempt), the tokenizer, and the seam of the tail it\n//        runs (the commons included: its tail is the one every Thread runs).\n//\n\nimport Foundation\n\n/// The checks every node passes before it joins a braid, exactly as RaoLM's umbrella applied them.\npublic enum Conformance {\n    public enum Failure: Error, CustomStringConvertible, Equatable {\n        case vocabulary(node: String, expected: String, found: String)\n        case pack(node: String, expected: String, found: String?)\n        case hiddenSize(node: String, expected: Int, found: Int)\n        case tokenizer(node: String, expected: String, found: String)\n        case seam(node: String, expected: String, found: String)\n\n        public var description: String {\n            switch self {\n            case .vocabulary(let node, let expected, let found): return \"\\(node): vocabulary \\(found.prefix(12)) is not the reed's \\(expected.prefix(12))\"\n            case .pack(let node, let expected, let found): return \"\\(node): pack \\(found?.prefix(12) ?? \"none\") is not the braid's \\(expected.prefix(12))\"\n            case .hiddenSize(let node, let expected, let found): return \"\\(node): hidden size \\(found) is not the reed's \\(expected)\"\n            case .tokenizer(let node, let expected, let found): return \"\\(node): tokenizer \\(found.prefix(12)) is not the braid's \\(expected.prefix(12))\"\n            case .seam(let node, let expected, let found): return \"\\(node): seam \\(found.prefix(12)) is not the braid's tail \\(expected.prefix(12))\"\n            }\n        }\n    }\n\n    /// `vocabularySHA256` → .vocabulary, `hiddenSize` → .hiddenSize, `packSHA256` → .pack (the commons is exempt), tokenizer → .tokenizer,\n    /// `seamSHA256` → .seam when both the braid and the node name one.\n    public static func check(_ descriptor: NodeDescriptor, vocabularySHA256: String, packSHA256: String?, hiddenSize: Int, tokenizerSHA256: String,\n                             seamSHA256: String? = nil) throws {\n        guard descriptor.vocabularySHA256 == vocabularySHA256 else {\n            throw Failure.vocabulary(node: descriptor.name, expected: vocabularySHA256, found: descriptor.vocabularySHA256)\n        }\n        guard descriptor.hiddenSize == hiddenSize else { throw Failure.hiddenSize(node: descriptor.name, expected: hiddenSize, found: descriptor.hiddenSize) }\n        if let packSHA256, !descriptor.isCommons, descriptor.packSHA256 != packSHA256 {\n            throw Failure.pack(node: descriptor.name, expected: packSHA256, found: descriptor.packSHA256)\n        }\n        guard descriptor.tokenizerSHA256 == tokenizerSHA256 else {\n            throw Failure.tokenizer(node: descriptor.name, expected: tokenizerSHA256, found: descriptor.tokenizerSHA256)\n        }\n        if let seamSHA256, let found = descriptor.seamSHA256, found != seamSHA256 {\n            throw Failure.seam(node: descriptor.name, expected: seamSHA256, found: found)\n        }\n    }\n}\n"},{"path":"Sources/BraidCore/Strand/Hit.swift","lines":70,"bytes":2776,"header":{"lines":[1,12],"what":[8,10],"pin":[11,11],"in":null,"out":null},"marks":[],"first":450,"scopes":[["S","Hit",null,"public",19,19,[19,48],70,[16,18],-1,0],["i","init",["entry","score","value","row","offset","loss"],"public",27,27,[27,102],34,null,0,0],["v","cited",null,"public",36,36,[36,36],36,null,0,8],["E","CodingKeys",null,"",38,38,[38,39],38,null,0,8,[]],["i","init",["from"],"public",42,42,[42,46],59,[40,41],0,0],["f","encode",["to"],"public",61,61,[61,51],69,null,0,0]],"text":"//\n//  Hit.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: One retrieved corpus position, as a node emits it beside its normed state: the index\n//        entry, its cosine, the token that followed it, where that token sits and the loss of the\n//        transition. The trace, the spans and the session log all read hits.\n//  PIN:  Logged as `[entry, score, value, row, offset, loss]`.\n//\n\nimport Foundation\n\n/// One retrieved corpus position: the index entry, its cosine, the token that followed it, where\n/// that token sits (the citation address, in the node's own partition table), and the eval loss\n/// of the transition (citation confidence reads it).\npublic struct Hit: Codable, Sendable, Equatable {\n    public var entry: Int32\n    public var score: Float\n    public var value: Int32\n    public var row: Int32\n    public var offset: Int32\n    public var loss: Float\n\n    public init(entry: Int32, score: Float, value: Int32, row: Int32, offset: Int32, loss: Float = 0) {\n        self.entry = entry\n        self.score = score\n        self.value = value\n        self.row = row\n        self.offset = offset\n        self.loss = loss\n    }\n\n    public var cited: TokenPosition { TokenPosition(row: Int(row), offset: Int(offset)) }\n\n    enum CodingKeys: String, CodingKey { case entry = \"e\", score = \"s\", value = \"v\", row = \"r\", offset = \"o\", loss = \"l\" }\n\n    /// Logged as a compact array `[entry, score, value, row, offset, loss]` (hits are most of a log's\n    /// bytes); the object form `{\"e\":…,\"s\":…}` of the first logs is still read.\n    public init(from decoder: Decoder) throws {\n        if var array = try? decoder.unkeyedContainer() {\n            entry = try array.decode(Int32.self)\n            score = try array.decode(Float.self)\n            value = try array.decode(Int32.self)\n            row = try array.decode(Int32.self)\n            offset = try array.decode(Int32.self)\n            loss = try array.decode(Float.self)\n        } else {\n            let c = try decoder.container(keyedBy: CodingKeys.self)\n            entry = try c.decode(Int32.self, forKey: .entry)\n            score = try c.decode(Float.self, forKey: .score)\n            value = try c.decode(Int32.self, forKey: .value)\n            row = try c.decode(Int32.self, forKey: .row)\n            offset = try c.decode(Int32.self, forKey: .offset)\n            loss = try c.decodeIfPresent(Float.self, forKey: .loss) ?? 0\n        }\n    }\n\n    public func encode(to encoder: Encoder) throws {\n        var array = encoder.unkeyedContainer()\n        try array.encode(entry)\n        try array.encode(score)\n        try array.encode(value)\n        try array.encode(row)\n        try array.encode(offset)\n        try array.encode(loss)\n    }\n}\n"},{"path":"Sources/BraidCore/Strand/IndexLayout.swift","lines":74,"bytes":3084,"header":{"lines":[1,12],"what":[8,11],"pin":null,"in":null,"out":null},"marks":[],"first":456,"scopes":[["S","PartitionRef",null,"public",17,17,[17,57],49,[16,16],-1,0],["i","init",["row","documentID","documentName","partitionIndex","partitionURL","textSHA256","tokenCount","memorisedAtEpoch","threadID","createdAt"],"public",32,32,[33,113],44,null,0,0],["f","address",["offset","threadID"],"public",46,46,[46,73],48,null,0,0],["S","IndexLayout",null,"public",52,52,[52,36],70,[51,51],-1,0],["i","init",["values","keyRow","keyOffset","partitions","breakLength","sharedNgrams"],"public",60,60,[60,148],67,null,3,0],["v","corpus",null,"public",69,69,[69,35],69,null,3,8],["X","TokenPosition",null,"",72,72,[72,36],74,null,-1,0],["f","<",["lhs","rhs"],"public static",73,73,[73,74],73,null,6,10]],"text":"//\n//  IndexLayout.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: Where a node's index entries sit: its partition table (one row per partition, with the\n//        document, the text hash and the Thread it lives on) and the layout the tracker and the\n//        citations read (values, each entry's row and offset, the break length, shared n-grams).\n//        Corpus positions order by (row, offset).\n//\n\nimport Foundation\n\n/// One row of the partition table an index was built over.\npublic struct PartitionRef: Codable, Sendable, Equatable {\n    public var row: Int\n    public var documentID: String\n    public var documentName: String\n    public var partitionIndex: Int\n    public var partitionURL: String?\n    public var textSHA256: String\n    public var tokenCount: Int\n    public var memorisedAtEpoch: Int?\n    /// The Thread this partition lives on, when a table mixes Threads (the braid's global table).\n    public var threadID: String?\n    /// When its document was created in its lane, as the lane reports it (smaller is older). It\n    /// breaks near-ties between tokens.\n    public var createdAt: Int64?\n\n    public init(row: Int, documentID: String, documentName: String, partitionIndex: Int, partitionURL: String? = nil, textSHA256: String,\n                tokenCount: Int, memorisedAtEpoch: Int? = nil, threadID: String? = nil, createdAt: Int64? = nil) {\n        self.row = row\n        self.documentID = documentID\n        self.documentName = documentName\n        self.partitionIndex = partitionIndex\n        self.partitionURL = partitionURL\n        self.textSHA256 = textSHA256\n        self.tokenCount = tokenCount\n        self.memorisedAtEpoch = memorisedAtEpoch\n        self.threadID = threadID\n        self.createdAt = createdAt\n    }\n\n    public func address(offset: Int, threadID: String?) -> SourceAddress {\n        SourceAddress(threadID: self.threadID ?? threadID, documentID: documentID, partitionIndex: partitionIndex, tokenOffset: offset, partitionURL: partitionURL)\n    }\n}\n\n/// What the tracker and the citations need of a node's index: where every entry sits.\npublic struct IndexLayout: Sendable {\n    public var values: [Int32]\n    public var keyRow: [Int32]\n    public var keyOffset: [Int32]\n    public var partitions: [PartitionRef]\n    public var breakLength: Int\n    public var sharedNgrams: Set<UInt64>\n\n    public init(values: [Int32], keyRow: [Int32], keyOffset: [Int32], partitions: [PartitionRef], breakLength: Int, sharedNgrams: Set<UInt64> = []) {\n        self.values = values\n        self.keyRow = keyRow\n        self.keyOffset = keyOffset\n        self.partitions = partitions\n        self.breakLength = breakLength\n        self.sharedNgrams = sharedNgrams\n    }\n\n    public var corpus: TraceCorpus { TraceCorpus(values: values, keyRow: keyRow, keyOffset: keyOffset, partitions: partitions, breakLength: breakLength) }\n}\n\nextension TokenPosition: Comparable {\n    public static func < (lhs: TokenPosition, rhs: TokenPosition) -> Bool { (lhs.row, lhs.offset) < (rhs.row, rhs.offset) }\n}\n"},{"path":"Sources/BraidCore/Strand/Node.swift","lines":137,"bytes":5694,"header":{"lines":[1,16],"what":[8,12],"pin":[13,15],"in":null,"out":null},"marks":[],"first":464,"scopes":[["E","NodeKind",null,"public",20,20,[20,48],20,null,-1,8,[]],["S","NodeDescriptor",null,"public",22,22,[22,59],63,null,-1,0],["i","init",["name","label","kind","vocabularySHA256","packSHA256","seamSHA256","hiddenSize","tokenizerSHA256","indexSHA256","checkpointsSHA256","versionSHA256","corpusHash","threadID","lane","lambdaScale","tau"],"public",41,41,[43,132],60,null,1,0],["v","isCommons",null,"public",62,62,[62,31],62,null,1,8],["S","NodeStep",null,"public",66,66,[66,44],76,[65,65],-1,0],["i","init",["position","state","hits"],"public",71,71,[71,60],75,null,4,0],["S","NodeContext",null,"public",79,79,[79,47],91,[78,78],-1,0],["i","init",["tokens","score","documentID","position"],"public",85,85,[85,92],90,null,6,0],["S","NodeCheckpoint",null,"public",94,94,[94,59],120,[93,93],-1,0],["i","init",["node","position","prefixSHA256","packSHA256","versionSHA256","bytes"],"public",104,104,[104,125],112,null,8,0],["f","prefixHash",["_"],"public static",115,115,[115,63],119,[114,114],8,0],["P","Node",null,"public",124,124,[124,32],137,null,-1,0],["v","descriptor",null,"",125,125,[125,35],125,null,11,9],["f","layout",[],"",127,127,null,127,[126,126],11,1],["f","open",["session","tokens","k"],"",130,130,null,130,[128,129],11,1],["f","advance",["session","token","k"],"",131,131,null,131,null,11,1],["f","context",["stem","subject","k","floor"],"",132,132,null,132,null,11,1],["f","checkpoint",["session"],"",133,133,null,133,null,11,1],["f","restore",["session","checkpoint","tokens"],"",134,134,null,134,null,11,1],["f","close",["session"],"",135,135,null,135,null,11,1],["f","cancel",[],"",136,136,null,136,null,11,1]],"text":"//\n//  Node.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The node protocol: what a Thread (or the commons) is to the cluster. A node emits a\n//        normed state and its hits at every position, catches up on a prefix in one call, hands\n//        out and takes back its history artifact (the recurrent state stack), and answers the\n//        question path's context lookup. The protocol is the transfer logic over the wire; v1\n//        implements it in process (BraidKit's LocalNode), later versions over a wire.\n//  PIN:  The node's output boundary is a normalized state. The cluster runs the reed once per\n//        node and computes H_lm, H_knn and the trace from what crosses, so every number in the\n//        session log is a function of the log.\n//\n\nimport Foundation\n\npublic enum NodeKind: String, Codable, Sendable { case thread, commons }\n\npublic struct NodeDescriptor: Codable, Sendable, Equatable {\n    public var name: String\n    public var label: String\n    public var kind: NodeKind\n    public var vocabularySHA256: String\n    public var packSHA256: String?\n    public var seamSHA256: String?\n    public var hiddenSize: Int\n    public var tokenizerSHA256: String\n    public var indexSHA256: String?\n    public var checkpointsSHA256: String?\n    public var versionSHA256: String?\n    public var corpusHash: String?\n    public var threadID: String?\n    public var lane: String?\n    /// The strand's own λ scale (0 for the commons) and kNN temperature.\n    public var lambdaScale: Float\n    public var tau: Float\n\n    public init(name: String, label: String? = nil, kind: NodeKind, vocabularySHA256: String, packSHA256: String?, seamSHA256: String? = nil,\n                hiddenSize: Int, tokenizerSHA256: String, indexSHA256: String? = nil, checkpointsSHA256: String? = nil, versionSHA256: String? = nil,\n                corpusHash: String? = nil, threadID: String? = nil, lane: String? = nil, lambdaScale: Float = 1, tau: Float = 0.05) {\n        self.name = name\n        self.label = label ?? name.prefix(1).uppercased() + name.dropFirst()\n        self.kind = kind\n        self.vocabularySHA256 = vocabularySHA256\n        self.packSHA256 = packSHA256\n        self.seamSHA256 = seamSHA256\n        self.hiddenSize = hiddenSize\n        self.tokenizerSHA256 = tokenizerSHA256\n        self.indexSHA256 = indexSHA256\n        self.checkpointsSHA256 = checkpointsSHA256\n        self.versionSHA256 = versionSHA256\n        self.corpusHash = corpusHash\n        self.threadID = threadID\n        self.lane = lane\n        self.lambdaScale = kind == .commons ? 0 : lambdaScale\n        self.tau = tau\n    }\n\n    public var isCommons: Bool { kind == .commons }\n}\n\n/// One position's emission: the normed state and the hits its key retrieved (expecting the next token).\npublic struct NodeStep: Sendable, Equatable {\n    public var position: Int\n    public var state: [Float]\n    public var hits: [Hit]\n\n    public init(position: Int, state: [Float], hits: [Hit]) {\n        self.position = position\n        self.state = state\n        self.hits = hits\n    }\n}\n\n/// The question path's context: the sentence before the node's best hit for a stem, from its own index.\npublic struct NodeContext: Sendable, Equatable {\n    public var tokens: [Int32]\n    public var score: Float\n    public var documentID: String\n    public var position: TokenPosition\n\n    public init(tokens: [Int32], score: Float, documentID: String, position: TokenPosition) {\n        self.tokens = tokens\n        self.score = score\n        self.documentID = documentID\n        self.position = position\n    }\n}\n\n/// The history artifact: a node's full recurrent state after a prefix, bound to that prefix.\npublic struct NodeCheckpoint: Codable, Sendable, Equatable {\n    public var node: String\n    public var position: Int\n    public var prefixSHA256: String\n    public var packSHA256: String?\n    public var versionSHA256: String?\n    /// The state stack, opaque to the cluster (safetensors bytes in BraidKit).\n    public var bytes: Data\n    public var sha256: String\n\n    public init(node: String, position: Int, prefixSHA256: String, packSHA256: String?, versionSHA256: String?, bytes: Data) {\n        self.node = node\n        self.position = position\n        self.prefixSHA256 = prefixSHA256\n        self.packSHA256 = packSHA256\n        self.versionSHA256 = versionSHA256\n        self.bytes = bytes\n        sha256 = ContentHash.sha256Hex(bytes)\n    }\n\n    /// sha256 of the consumed token ids as little-endian int32.\n    public static func prefixHash(_ tokens: [Int32]) -> String {\n        var data = Data(capacity: tokens.count * 4)\n        for token in tokens { withUnsafeBytes(of: token.littleEndian) { data.append(contentsOf: $0) } }\n        return ContentHash.sha256Hex(data)\n    }\n}\n\npublic typealias SessionID = String\n\npublic protocol Node: AnyObject {\n    var descriptor: NodeDescriptor { get }\n    /// The index layout (nil for the commons). Read once per version.\n    func layout() throws -> IndexLayout?\n    /// Opens a session on `tokens` (the eos opener included): one forward from a zero state,\n    /// returning every position's emission. The catch-up when a node attaches mid-session.\n    func open(session: SessionID, tokens: [Int32], k: Int) throws -> [NodeStep]\n    func advance(session: SessionID, token: Int32, k: Int) throws -> NodeStep\n    func context(stem: [Int32], subject: Range<Int>?, k: Int, floor: Float) throws -> NodeContext?\n    func checkpoint(session: SessionID) throws -> NodeCheckpoint\n    func restore(session: SessionID, checkpoint: NodeCheckpoint, tokens: [Int32]) throws\n    func close(session: SessionID)\n    func cancel()\n}\n"},{"path":"Sources/BraidCore/Strand/Reed.swift","lines":29,"bytes":893,"header":{"lines":[1,10],"what":[8,9],"pin":null,"in":null,"out":null},"marks":[],"first":485,"scopes":[["P","Reed",null,"public",15,15,[15,31],20,[14,14],-1,0],["v","vocabulary",null,"",16,16,[16,24],16,null,0,9],["v","vocabularySHA256",null,"",17,17,[17,33],17,null,0,9],["v","hiddenSize",null,"",18,18,[18,24],18,null,0,9],["f","logits",["_"],"",19,19,null,19,null,0,1],["P","Tokenizing",null,"public",22,22,[22,37],29,null,-1,0],["v","eos",null,"",23,23,[23,19],23,null,5,9],["v","sha256",null,"",24,24,[24,23],24,null,5,9],["f","encode",["_"],"",25,25,null,25,null,5,1],["f","decode",["_"],"",26,26,null,26,null,5,1],["f","text",["_"],"",28,28,null,28,[27,27],5,1]],"text":"//\n//  Reed.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The two services a braid shares across its strands: the reed (logits from normed\n//        states; BraidKit's runs on MLX, tests use a fake) and the tokenizer.\n//\n\nimport Foundation\n\n/// The reed: logits from normed states. BraidKit's reed runs on MLX; tests use a fake.\npublic protocol Reed: Sendable {\n    var vocabulary: Int { get }\n    var vocabularySHA256: String { get }\n    var hiddenSize: Int { get }\n    func logits(_ states: [[Float]]) throws -> [[Float]]\n}\n\npublic protocol Tokenizing: Sendable {\n    var eos: Int32 { get }\n    var sha256: String { get }\n    func encode(_ text: String) -> [Int32]\n    func decode(_ tokens: [Int32]) -> String\n    /// The token's own text, as it decodes alone (its leading space included).\n    func text(_ token: Int32) -> String\n}\n"},{"path":"Sources/BraidCore/Strand/StrandSlot.swift","lines":49,"bytes":1974,"header":{"lines":[1,12],"what":[8,11],"pin":null,"in":null,"out":null},"marks":[],"first":496,"scopes":[["S","StrandSlot",null,"public",16,16,[16,56],39,null,-1,0],["i","init",["name","rowOffset","rowCount","tau","commons"],"public",25,25,[25,93],31,null,0,0],["i","init",["_"],"public",33,33,[33,41],35,null,0,0],["f","holds",["row"],"public",38,38,[38,40],38,[37,37],0,8],["E","StrandSlots",null,"public",41,41,[41,24],49,null,-1,0,[]],["f","indexed",["rowOffsets","taus","commons"],"public static",43,43,[43,103],45,[42,42],4,0],["f","commons",["_"],"public static",48,48,[48,62],48,[47,47],4,8]],"text":"//\n//  StrandSlot.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: Who strand index t was at one step. Attach and detach lines move strands' indices in the\n//        middle of a generation, so every per-step view — citations and spans, credit, the\n//        followed-credit decision, royalties — reads a step's records through that step's own slots\n//        and aggregates across steps by the Thread's name.\n//\n\nimport Foundation\n\npublic struct StrandSlot: Sendable, Equatable, Hashable {\n    public var name: String\n    /// Where this strand's rows begin in the braid's global partition table, and how many it has (a\n    /// re-attached Thread gets new rows).\n    public var rowOffset: Int\n    public var rowCount: Int\n    public var tau: Double\n    public var commons: Bool\n\n    public init(name: String, rowOffset: Int, rowCount: Int = 0, tau: Double, commons: Bool) {\n        self.name = name\n        self.rowOffset = rowOffset\n        self.rowCount = rowCount\n        self.tau = tau\n        self.commons = commons\n    }\n\n    public init(_ thread: SessionThread) {\n        self.init(name: thread.name, rowOffset: thread.rowOffset, rowCount: thread.rowCount, tau: Double(thread.tau), commons: thread.commons)\n    }\n\n    /// Whether a global row is one of this strand's.\n    public func holds(row: Int) -> Bool { !commons && row >= rowOffset && row < rowOffset + rowCount }\n}\n\npublic enum StrandSlots {\n    /// Slots for callers that know only offsets and τs: named by index (\"0\", \"1\", …).\n    public static func indexed(rowOffsets: [Int], taus: [Double], commons: Int? = nil) -> [StrandSlot] {\n        rowOffsets.indices.map { t in StrandSlot(name: \"\\(t)\", rowOffset: rowOffsets[t], tau: t < taus.count ? taus[t] : 0.05, commons: t == commons) }\n    }\n\n    /// The commons' index among one step's slots.\n    public static func commons(_ slots: [StrandSlot]) -> Int? { slots.firstIndex(where: \\.commons) }\n}\n"},{"path":"Sources/BraidCore/Support/BraidConfig.swift","lines":135,"bytes":7588,"header":{"lines":[1,12],"what":[8,11],"pin":null,"in":null,"out":null},"marks":[],"first":503,"scopes":[["S","BraidConfig",null,"public",16,16,[16,47],135,null,-1,0],["S","Pack",null,"public",17,17,[17,44],48,null,0,0],["i","init",["name","sha256","vocabularySHA256","tokenizerSHA256","hiddenSize","layers","heads","headDim","stateSize","convKernel","vocabRows","vocabTokens","keyScheme"],"public",32,32,[33,106],47,null,1,0],["S","Index",null,"public",50,50,[50,45],56,null,0,0],["i","init",[],"public",55,55,[55,22],55,null,3,8],["i","init",["pack"],"public",65,65,[65,35],65,null,0,8],["f","render",[],"public",69,69,[69,35],88,null,0,0],["f","parse",["_"],"public static",90,90,[90,67],125,null,0,0],["f","str",["_","_"],"",92,92,[92,66],95,null,7,4],["f","int",["_","_"],"",96,96,[96,63],99,null,7,4],["f","load",["from"],"public static",127,127,[127,65],127,null,0,8],["f","save",["to"],"public",129,129,[129,41],132,null,0,0],["v","sha256",null,"public",134,134,[134,30],134,null,0,8]],"text":"//\n//  BraidConfig.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: braid.toml at the work-area root, written by `braid init`: the pack a braid runs on\n//        (its hashes and shape), the index and gate constants, which Threads bare `braid`\n//        attaches, and where the machine's AII lives. The cut is the pack's (`braid_cut`), not\n//        braid.toml's; a `cut` key an older file carries is ignored.\n//\n\nimport Foundation\n\npublic struct BraidConfig: Sendable, Equatable {\n    public struct Pack: Sendable, Equatable {\n        public var name: String\n        public var sha256: String\n        public var vocabularySHA256: String\n        public var tokenizerSHA256: String\n        public var hiddenSize: Int\n        public var layers: Int\n        public var heads: Int\n        public var headDim: Int\n        public var stateSize: Int\n        public var convKernel: Int\n        public var vocabRows: Int\n        public var vocabTokens: Int\n        public var keyScheme: String\n\n        public init(name: String, sha256: String, vocabularySHA256: String, tokenizerSHA256: String, hiddenSize: Int, layers: Int, heads: Int, headDim: Int,\n                    stateSize: Int, convKernel: Int, vocabRows: Int, vocabTokens: Int, keyScheme: String) {\n            self.name = name\n            self.sha256 = sha256\n            self.vocabularySHA256 = vocabularySHA256\n            self.tokenizerSHA256 = tokenizerSHA256\n            self.hiddenSize = hiddenSize\n            self.layers = layers\n            self.heads = heads\n            self.headDim = headDim\n            self.stateSize = stateSize\n            self.convKernel = convKernel\n            self.vocabRows = vocabRows\n            self.vocabTokens = vocabTokens\n            self.keyScheme = keyScheme\n        }\n    }\n\n    public struct Index: Sendable, Equatable {\n        public var alpha: Double = 0.5\n        public var k: Int = 16\n        public var tau: Double = 0.05\n        public var checkpointStride: Int = 1024\n        public init() {}\n    }\n\n    public var version = 1\n    public var pack: Pack?\n    public var index = Index()\n    public var gate = GateSettings()\n    public var attach: [String] = []\n    public var aiiHome: String = \"~/.rao\"\n\n    public init(pack: Pack? = nil) { self.pack = pack }\n\n    public static let fileName = \"braid.toml\"\n\n    public func render() -> String {\n        var document: TOMLSubset.Document = [(\"\", [(\"version\", .integer(version))])]\n        if let p = pack {\n            document.append((\"pack\", [\n                (\"name\", .string(p.name)), (\"sha256\", .string(p.sha256)), (\"vocabulary_sha256\", .string(p.vocabularySHA256)),\n                (\"tokenizer_sha256\", .string(p.tokenizerSHA256)), (\"hidden_size\", .integer(p.hiddenSize)), (\"layers\", .integer(p.layers)),\n                (\"heads\", .integer(p.heads)), (\"head_dim\", .integer(p.headDim)), (\"state_size\", .integer(p.stateSize)), (\"conv_kernel\", .integer(p.convKernel)),\n                (\"vocab_rows\", .integer(p.vocabRows)), (\"vocab_tokens\", .integer(p.vocabTokens)), (\"key_scheme\", .string(p.keyScheme)),\n            ]))\n        }\n        document.append((\"index\", [(\"alpha\", .float(index.alpha)), (\"k\", .integer(index.k)), (\"tau\", .float(index.tau)), (\"checkpoint_stride\", .integer(index.checkpointStride))]))\n        document.append((\"gate\", [\n            (\"evidence_floor\", .float(gate.evidenceFloor)), (\"evidence_ceiling\", .float(gate.evidenceCeiling)), (\"share_rate\", .float(gate.shareRate)),\n            (\"credibility_rate\", .float(gate.credibilityRate)), (\"commons_prior\", .float(gate.commonsPrior)), (\"open_floor\", .float(gate.openFloor)),\n            (\"module_gain\", .float(gate.moduleGain)), (\"shadow_beta\", .float(gate.shadowBeta)), (\"evidence\", .string(gate.evidence.rawValue)),\n        ]))\n        document.append((\"cluster\", [(\"attach\", .strings(attach))]))\n        document.append((\"aii\", [(\"home\", .string(aiiHome))]))\n        return TOMLSubset.render(document)\n    }\n\n    public static func parse(_ text: String) throws -> BraidConfig {\n        let document = try TOMLSubset.parse(text)\n        func str(_ table: String, _ key: String) throws -> String {\n            guard let value = TOMLSubset.value(document, table, key)?.string else { throw BraidFailure.configuration(\"braid.toml: missing \\(table).\\(key)\") }\n            return value\n        }\n        func int(_ table: String, _ key: String) throws -> Int {\n            guard let value = TOMLSubset.value(document, table, key)?.integer else { throw BraidFailure.configuration(\"braid.toml: missing \\(table).\\(key)\") }\n            return value\n        }\n        var config = BraidConfig()\n        config.version = TOMLSubset.value(document, \"\", \"version\")?.integer ?? 1\n        if document.contains(where: { $0.table == \"pack\" }) {\n            config.pack = Pack(name: try str(\"pack\", \"name\"), sha256: try str(\"pack\", \"sha256\"), vocabularySHA256: try str(\"pack\", \"vocabulary_sha256\"),\n                               tokenizerSHA256: try str(\"pack\", \"tokenizer_sha256\"), hiddenSize: try int(\"pack\", \"hidden_size\"), layers: try int(\"pack\", \"layers\"),\n                               heads: try int(\"pack\", \"heads\"), headDim: try int(\"pack\", \"head_dim\"), stateSize: try int(\"pack\", \"state_size\"),\n                               convKernel: try int(\"pack\", \"conv_kernel\"), vocabRows: try int(\"pack\", \"vocab_rows\"), vocabTokens: try int(\"pack\", \"vocab_tokens\"),\n                               keyScheme: try str(\"pack\", \"key_scheme\"))\n        }\n        if let v = TOMLSubset.value(document, \"index\", \"alpha\")?.float { config.index.alpha = v }\n        if let v = TOMLSubset.value(document, \"index\", \"k\")?.integer { config.index.k = v }\n        if let v = TOMLSubset.value(document, \"index\", \"tau\")?.float { config.index.tau = v }\n        if let v = TOMLSubset.value(document, \"index\", \"checkpoint_stride\")?.integer { config.index.checkpointStride = v }\n        if let v = TOMLSubset.value(document, \"gate\", \"evidence_floor\")?.float { config.gate.evidenceFloor = v }\n        if let v = TOMLSubset.value(document, \"gate\", \"evidence_ceiling\")?.float { config.gate.evidenceCeiling = v }\n        if let v = TOMLSubset.value(document, \"gate\", \"share_rate\")?.float { config.gate.shareRate = v }\n        if let v = TOMLSubset.value(document, \"gate\", \"credibility_rate\")?.float { config.gate.credibilityRate = v }\n        if let v = TOMLSubset.value(document, \"gate\", \"commons_prior\")?.float { config.gate.commonsPrior = v }\n        if let v = TOMLSubset.value(document, \"gate\", \"open_floor\")?.float { config.gate.openFloor = v }\n        if let v = TOMLSubset.value(document, \"gate\", \"module_gain\")?.float { config.gate.moduleGain = v }\n        if let v = TOMLSubset.value(document, \"gate\", \"shadow_beta\")?.float { config.gate.shadowBeta = v }\n        if let v = TOMLSubset.value(document, \"gate\", \"evidence\")?.string, let e = GateSettings.Evidence(rawValue: v) { config.gate.evidence = e }\n        config.attach = TOMLSubset.value(document, \"cluster\", \"attach\")?.strings ?? []\n        config.aiiHome = TOMLSubset.value(document, \"aii\", \"home\")?.string ?? \"~/.rao\"\n        return config\n    }\n\n    public static func load(from url: URL) throws -> BraidConfig { try parse(String(contentsOf: url, encoding: .utf8)) }\n\n    public func save(to url: URL) throws {\n        try FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)\n        try Data(render().utf8).write(to: url, options: .atomic)\n    }\n\n    public var sha256: String { ContentHash.sha256Hex(render()) }\n}\n"},{"path":"Sources/BraidCore/Support/BraidFailure.swift","lines":50,"bytes":2175,"header":{"lines":[1,11],"what":[8,10],"pin":null,"in":null,"out":null},"marks":[],"first":516,"scopes":[["E","ExitCode",null,"public",15,15,[15,38],28,null,-1,0,["ok","doctor","verifyMismatch","usage","data","missingInput","unavailable","internalError","exists","temporary","configuration","interrupted"]],["S","BraidFailure",null,"public",30,30,[30,69],50,null,-1,0],["i","init",["_","hint","code"],"public",35,35,[35,72],39,null,1,0],["v","description",null,"public",41,41,[41,35],41,null,1,8],["f","usage",["_","hint"],"public static",43,43,[43,85],43,null,1,8],["f","data",["_","hint"],"public static",44,44,[44,84],44,null,1,8],["f","missing",["_","hint"],"public static",45,45,[45,87],45,null,1,8],["f","unavailable",["_","hint"],"public static",46,46,[46,91],46,null,1,8],["f","exists",["_","hint"],"public static",47,47,[47,86],47,null,1,8],["f","temporary",["_","hint"],"public static",48,48,[48,89],48,null,1,8],["f","configuration",["_","hint"],"public static",49,49,[49,93],49,null,1,8]],"text":"//\n//  BraidFailure.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: One error type the CLI prints and maps to sysexits, so scripts can branch on the code.\n//        The table is RaoLM's: 1 doctor, 3 verify mismatch, 64 usage, 65 data, 66 missing input,\n//        69 unavailable, 70 internal, 73 exists, 75 temporary, 78 configuration, 130 interrupted.\n//\n\nimport Foundation\n\npublic enum ExitCode: Int32, Sendable {\n    case ok = 0\n    case doctor = 1\n    case verifyMismatch = 3\n    case usage = 64\n    case data = 65\n    case missingInput = 66\n    case unavailable = 69\n    case internalError = 70\n    case exists = 73\n    case temporary = 75\n    case configuration = 78\n    case interrupted = 130\n}\n\npublic struct BraidFailure: Error, CustomStringConvertible, Sendable {\n    public var message: String\n    public var hint: String?\n    public var code: ExitCode\n\n    public init(_ message: String, hint: String? = nil, code: ExitCode) {\n        self.message = message\n        self.hint = hint\n        self.code = code\n    }\n\n    public var description: String { hint.map { \"\\(message)\\n  \\($0)\" } ?? message }\n\n    public static func usage(_ message: String, hint: String? = nil) -> BraidFailure { BraidFailure(message, hint: hint, code: .usage) }\n    public static func data(_ message: String, hint: String? = nil) -> BraidFailure { BraidFailure(message, hint: hint, code: .data) }\n    public static func missing(_ message: String, hint: String? = nil) -> BraidFailure { BraidFailure(message, hint: hint, code: .missingInput) }\n    public static func unavailable(_ message: String, hint: String? = nil) -> BraidFailure { BraidFailure(message, hint: hint, code: .unavailable) }\n    public static func exists(_ message: String, hint: String? = nil) -> BraidFailure { BraidFailure(message, hint: hint, code: .exists) }\n    public static func temporary(_ message: String, hint: String? = nil) -> BraidFailure { BraidFailure(message, hint: hint, code: .temporary) }\n    public static func configuration(_ message: String, hint: String? = nil) -> BraidFailure { BraidFailure(message, hint: hint, code: .configuration) }\n}\n"},{"path":"Sources/BraidCore/Support/ContentHash.swift","lines":112,"bytes":5208,"header":{"lines":[1,13],"what":[8,9],"pin":[10,12],"in":null,"out":null},"marks":[],"first":527,"scopes":[["E","ContentHash",null,"public",18,18,[18,24],83,null,-1,0,[]],["f","sha256Hex",["_"],"public static",19,19,[19,57],21,null,0,0],["f","sha256Hex",["_"],"public static",24,24,[24,59],24,[23,23],0,8],["f","sha256Hex",["parts"],"public static",27,27,[27,58],31,[26,26],0,0],["f","sha256Hex",["fileAt"],"public static",34,34,[34,67],44,[33,33],0,0],["f","canonical",["_"],"public static",48,48,[48,59],61,[46,47],0,0],["S","CorpusEntry",null,"public",63,63,[63,51],73,null,0,0],["i","init",["documentID","partitionIndex","textSHA256"],"public",68,68,[68,81],72,null,6,0],["f","corpusHash",["_"],"public static",77,77,[77,70],82,[75,76],0,0],["E","DocumentID",null,"public",86,86,[86,23],112,[85,85],-1,0,[]],["f","make",["slug","canonicalText"],"public static",89,89,[89,75],91,[87,88],9,0],["f","isValid",["_"],"public static",95,95,[95,53],95,null,9,8],["f","partitionURL",["aii","lane","documentID","index"],"public static",100,100,[100,105],102,[97,99],9,0],["f","prefix",["slug"],"public static",105,105,[105,54],105,[104,104],9,8],["f","isValidHandle",["_"],"public static",109,109,[109,63],111,[107,108],9,0]],"text":"//\n//  ContentHash.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The hashing Braid's provenance chain rests on: text, files, byte parts laid end to end,\n//        and the corpus hash that names exactly which Thread state a model was trained on.\n//  PIN:  Every hash is lowercase hex SHA-256. The corpus hash is order-independent: it sorts its\n//        entries, so the same partitions exported in any order hash the same. These are RaoLM's\n//        definitions, unchanged, so a RaoLM dataset or snapshot hashes the same here.\n//\n\nimport Crypto\nimport Foundation\n\npublic enum ContentHash {\n    public static func sha256Hex(_ data: Data) -> String {\n        SHA256.hash(data: data).map { String(format: \"%02x\", $0) }.joined()\n    }\n\n    /// SHA-256 of the UTF-8 bytes of `text`, exactly as given (no canonicalization).\n    public static func sha256Hex(_ text: String) -> String { sha256Hex(Data(text.utf8)) }\n\n    /// SHA-256 of `parts` laid end to end, without joining them first.\n    public static func sha256Hex(parts: [Data]) -> String {\n        var hasher = SHA256()\n        for part in parts { hasher.update(data: part) }\n        return hasher.finalize().map { String(format: \"%02x\", $0) }.joined()\n    }\n\n    /// SHA-256 of a file's bytes, streamed in 1 MiB chunks.\n    public static func sha256Hex(fileAt url: URL) throws -> String {\n        let handle = try FileHandle(forReadingFrom: url)\n        defer { try? handle.close() }\n        var hasher = SHA256()\n        while true {\n            let chunk = try handle.read(upToCount: 1 << 20) ?? Data()\n            if chunk.isEmpty { break }\n            hasher.update(data: chunk)\n        }\n        return hasher.finalize().map { String(format: \"%02x\", $0) }.joined()\n    }\n\n    /// The canonical form document ids are derived from: NFC, `\\r\\n` → `\\n`, trailing whitespace\n    /// stripped from every line, and the whole trimmed.\n    public static func canonical(_ text: String) -> String {\n        let normalized = text.precomposedStringWithCanonicalMapping\n            .replacingOccurrences(of: \"\\r\\n\", with: \"\\n\")\n            .replacingOccurrences(of: \"\\r\", with: \"\\n\")\n        let lines = normalized.split(separator: \"\\n\", omittingEmptySubsequences: false).map { line -> Substring in\n            var end = line.endIndex\n            while end > line.startIndex {\n                let before = line.index(before: end)\n                if line[before] == \" \" || line[before] == \"\\t\" { end = before } else { break }\n            }\n            return line[line.startIndex..<end]\n        }\n        return lines.joined(separator: \"\\n\").trimmingCharacters(in: .whitespacesAndNewlines)\n    }\n\n    public struct CorpusEntry: Sendable, Equatable {\n        public var documentID: String\n        public var partitionIndex: Int\n        public var textSHA256: String\n\n        public init(documentID: String, partitionIndex: Int, textSHA256: String) {\n            self.documentID = documentID\n            self.partitionIndex = partitionIndex\n            self.textSHA256 = textSHA256\n        }\n    }\n\n    /// SHA-256 over the lines `\"<documentID>\\t<partitionIndex>\\t<textSHA256>\\n\"`, sorted by\n    /// (documentID, partitionIndex). Recomputable by hand with `shasum -a 256`.\n    public static func corpusHash(_ entries: [CorpusEntry]) -> String {\n        let sorted = entries.sorted { ($0.documentID, $0.partitionIndex) < ($1.documentID, $1.partitionIndex) }\n        var text = \"\"\n        for entry in sorted { text += \"\\(entry.documentID)\\t\\(entry.partitionIndex)\\t\\(entry.textSHA256)\\n\" }\n        return sha256Hex(text)\n    }\n}\n\n/// Document ids, partition urls and the handles Braid passes to a Thread lane.\npublic enum DocumentID {\n    /// `braid-<slug>-<first 24 hex of sha256(canonical text)>`. Content-addressed, never contains\n    /// a `/`. RaoLM's `raolm-…` ids (the datasets on the T9) are accepted wherever an id is read.\n    public static func make(slug: String, canonicalText: String) -> String {\n        \"braid-\\(slug)-\" + String(ContentHash.sha256Hex(canonicalText).prefix(24))\n    }\n\n    public static let pattern = #\"^(braid|raolm)-[a-z0-9-]+-[0-9a-f]{24}$\"#\n\n    public static func isValid(_ id: String) -> Bool { id.range(of: pattern, options: .regularExpression) != nil }\n\n    /// The per-partition address Braid hands a lane at ingest and reads back from ExportCorpus.\n    /// Thread parses it with `URL(string:)` and returns `absoluteString`, which round-trips for\n    /// this alphabet.\n    public static func partitionURL(aii: String, lane: String, documentID: String, index: Int) -> String {\n        \"braid://\\(aii)/\\(lane)/\\(documentID)/\\(index)\"\n    }\n\n    /// The prefix every document id of a corpus shares; ExportCorpus filters on it.\n    public static func prefix(slug: String) -> String { \"braid-\\(slug)-\" }\n\n    /// Owner, group and slug handles: lowercase, `[a-z0-9._-]`, 2–64 characters. Thread stores a\n    /// gRPC owner as given but lowercases partition owners, so mixed case would split one owner.\n    public static func isValidHandle(_ handle: String) -> Bool {\n        handle.range(of: #\"^[a-z0-9][a-z0-9._-]{1,63}$\"#, options: .regularExpression) != nil\n    }\n}\n"},{"path":"Sources/BraidCore/Support/JSONCoding.swift","lines":148,"bytes":5917,"header":{"lines":[1,13],"what":[8,9],"pin":[10,12],"in":null,"out":null},"marks":[],"first":542,"scopes":[["E","JSONCoding",null,"public",17,17,[17,23],102,null,-1,0,[]],["f","prettyEncoder",[],"public static",19,19,[19,54],25,[18,18],0,0],["f","lineEncoder",[],"public static",28,28,[28,52],34,[27,27],0,0],["f","decoder",[],"public static",36,36,[36,48],41,null,0,0],["f","write",["_","to"],"public static",43,43,[43,75],46,null,0,0],["f","read",["_","from"],"public static",48,48,[48,85],50,null,0,0],["f","standardized",["_"],"public static",55,55,[55,62],84,[52,54],0,0],["f","readStandardized",["_","from"],"public static",87,87,[87,97],89,[86,86],0,0],["f","line",["_"],"public static",92,92,[92,71],94,[91,91],0,0],["f","readLines",["_","from"],"public static",97,97,[97,92],101,[96,96],0,0],["C","JSONLWriter",null,"public final",105,105,[105,52],148,[104,104],-1,0],["i","init",["url","truncate"],"public",111,111,[111,57],118,null,10,0],["d","deinit",null,"",120,120,[120,11],120,null,10,8],["f","append",["_"],"public",122,122,[122,56],128,null,10,0],["f","appendAll",["_"],"public",130,130,[130,62],133,null,10,0],["f","appendRaw",["_"],"public",136,136,[136,49],140,[135,135],10,0],["f","close",[],"public",142,142,[142,24],147,null,10,0]],"text":"//\n//  JSONCoding.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The one JSON encoder and decoder Braid writes manifests, snapshots, session logs and\n//        bench reports with.\n//  PIN:  Sorted keys and ISO-8601 dates, so the same value always encodes to the same bytes and\n//        a manifest's hash means something. Non-finite floats encode as strings so a log line\n//        never fails to write.\n//\n\nimport Foundation\n\npublic enum JSONCoding {\n    /// Pretty, sorted, stable. For files people read (manifests, snapshots, reports).\n    public static func prettyEncoder() -> JSONEncoder {\n        let encoder = JSONEncoder()\n        encoder.outputFormatting = [.prettyPrinted, .sortedKeys, .withoutEscapingSlashes]\n        encoder.dateEncodingStrategy = .iso8601\n        encoder.nonConformingFloatEncodingStrategy = .convertToString(positiveInfinity: \"inf\", negativeInfinity: \"-inf\", nan: \"nan\")\n        return encoder\n    }\n\n    /// Compact, sorted, stable. For JSONL rows.\n    public static func lineEncoder() -> JSONEncoder {\n        let encoder = JSONEncoder()\n        encoder.outputFormatting = [.sortedKeys, .withoutEscapingSlashes]\n        encoder.dateEncodingStrategy = .iso8601\n        encoder.nonConformingFloatEncodingStrategy = .convertToString(positiveInfinity: \"inf\", negativeInfinity: \"-inf\", nan: \"nan\")\n        return encoder\n    }\n\n    public static func decoder() -> JSONDecoder {\n        let decoder = JSONDecoder()\n        decoder.dateDecodingStrategy = .iso8601\n        decoder.nonConformingFloatDecodingStrategy = .convertFromString(positiveInfinity: \"inf\", negativeInfinity: \"-inf\", nan: \"nan\")\n        return decoder\n    }\n\n    public static func write<T: Encodable>(_ value: T, to url: URL) throws {\n        try FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)\n        try prettyEncoder().encode(value).write(to: url, options: .atomic)\n    }\n\n    public static func read<T: Decodable>(_ type: T.Type, from url: URL) throws -> T {\n        try decoder().decode(type, from: Data(contentsOf: url))\n    }\n\n    /// Python's json module writes the bare literals `Infinity`, `-Infinity` and `NaN`, which are\n    /// not JSON; Hugging Face configs carry them (`time_step_limit`). This turns them into the\n    /// strings the decoder reads as non-finite floats, outside quoted strings only.\n    public static func standardized(_ text: String) -> String {\n        let literals = [(\"-Infinity\", \"\\\"-inf\\\"\"), (\"Infinity\", \"\\\"inf\\\"\"), (\"NaN\", \"\\\"nan\\\"\")]\n        var out = \"\"\n        var inString = false\n        var escaped = false\n        var i = text.startIndex\n        while i < text.endIndex {\n            let c = text[i]\n            if inString {\n                out.append(c)\n                if escaped { escaped = false } else if c == \"\\\\\" { escaped = true } else if c == \"\\\"\" { inString = false }\n                i = text.index(after: i)\n                continue\n            }\n            if c == \"\\\"\" {\n                inString = true\n                out.append(c)\n                i = text.index(after: i)\n                continue\n            }\n            if let (literal, replacement) = literals.first(where: { text[i...].hasPrefix($0.0) }) {\n                out += replacement\n                i = text.index(i, offsetBy: literal.count)\n                continue\n            }\n            out.append(c)\n            i = text.index(after: i)\n        }\n        return out\n    }\n\n    /// Reads JSON that may carry Python's non-standard float literals.\n    public static func readStandardized<T: Decodable>(_ type: T.Type, from url: URL) throws -> T {\n        try decoder().decode(type, from: Data(standardized(String(contentsOf: url, encoding: .utf8)).utf8))\n    }\n\n    /// One compact line, no trailing newline.\n    public static func line<T: Encodable>(_ value: T) throws -> String {\n        String(decoding: try lineEncoder().encode(value), as: UTF8.self)\n    }\n\n    /// Every non-empty line of a JSONL file, decoded.\n    public static func readLines<T: Decodable>(_ type: T.Type, from url: URL) throws -> [T] {\n        let text = try String(contentsOf: url, encoding: .utf8)\n        let decoder = decoder()\n        return try text.split(separator: \"\\n\").filter { !$0.allSatisfy(\\.isWhitespace) }.map { try decoder.decode(type, from: Data($0.utf8)) }\n    }\n}\n\n/// An append-only JSONL file. One encodable value per line.\npublic final class JSONLWriter: @unchecked Sendable {\n    public let url: URL\n    private let handle: FileHandle\n    private let encoder = JSONCoding.lineEncoder()\n    private let lock = NSLock()\n\n    public init(url: URL, truncate: Bool = false) throws {\n        self.url = url\n        let manager = FileManager.default\n        try manager.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)\n        if truncate || !manager.fileExists(atPath: url.path) { manager.createFile(atPath: url.path, contents: nil) }\n        handle = try FileHandle(forWritingTo: url)\n        try handle.seekToEnd()\n    }\n\n    deinit { try? handle.close() }\n\n    public func append<T: Encodable>(_ value: T) throws {\n        var data = try encoder.encode(value)\n        data.append(0x0A)\n        lock.lock()\n        defer { lock.unlock() }\n        try handle.write(contentsOf: data)\n    }\n\n    public func appendAll<T: Encodable>(_ values: [T]) throws {\n        for value in values { try append(value) }\n        close()\n    }\n\n    /// Writes an already encoded line (used for lines whose bytes are hashed as written).\n    public func appendRaw(_ line: String) throws {\n        lock.lock()\n        defer { lock.unlock() }\n        try handle.write(contentsOf: Data((line + \"\\n\").utf8))\n    }\n\n    public func close() {\n        lock.lock()\n        defer { lock.unlock() }\n        try? handle.synchronize()\n        try? handle.close()\n    }\n}\n"},{"path":"Sources/BraidCore/Support/Stats.swift","lines":141,"bytes":5754,"header":{"lines":[1,10],"what":[8,9],"pin":null,"in":null,"out":null},"marks":[],"first":559,"scopes":[["E","Stats",null,"public",14,14,[14,18],126,null,-1,0,[]],["f","mean",["_"],"public static",15,15,[15,58],18,null,0,0],["f","mean",["_"],"public static",20,20,[20,56],20,null,0,8],["f","variance",["_"],"public static",22,22,[22,62],26,null,0,0],["f","quantile",["_","_"],"public static",29,29,[29,75],36,[28,28],0,0],["f","auroc",["scores","labels"],"public static",40,40,[40,74],50,[38,39],0,0],["f","ranks",["_"],"public static",53,53,[53,61],65,[52,52],0,0],["f","spearman",["_","_"],"public static",67,67,[67,73],70,null,0,0],["f","pearson",["_","_"],"public static",72,72,[72,72],86,null,0,0],["f","slope",["_"],"public static",89,89,[89,60],101,[88,88],0,0],["f","cohenKappa",["_","_"],"public static",104,104,[104,71],117,[103,103],0,0],["f","welchZ",["_","_"],"public static",120,120,[120,71],125,[119,119],0,0],["S","SplitMix64",null,"public",129,129,[129,58],141,[128,128],-1,0],["i","init",["seed"],"public",132,132,[132,30],132,null,12,8],["f","next",[],"public mutating",134,134,[134,42],140,null,12,0]],"text":"//\n//  Stats.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The handful of summary statistics the benches, the trajectory module and the reports\n//        use: mean, quantiles, AUROC, Pearson, Spearman, ranks, Cohen's κ, Welch's z.\n//\n\nimport Foundation\n\npublic enum Stats {\n    public static func mean(_ values: [Double]) -> Double {\n        guard !values.isEmpty else { return 0 }\n        return values.reduce(0, +) / Double(values.count)\n    }\n\n    public static func mean(_ values: [Float]) -> Float { Float(mean(values.map(Double.init))) }\n\n    public static func variance(_ values: [Double]) -> Double {\n        guard values.count > 1 else { return 0 }\n        let m = mean(values)\n        return values.reduce(0) { $0 + ($1 - m) * ($1 - m) } / Double(values.count - 1)\n    }\n\n    /// Linear-interpolated quantile of `values` at `q` in [0, 1]. Sorts a copy.\n    public static func quantile(_ values: [Double], _ q: Double) -> Double {\n        guard !values.isEmpty else { return 0 }\n        let sorted = values.sorted()\n        let position = min(max(q, 0), 1) * Double(sorted.count - 1)\n        let lower = Int(position.rounded(.down))\n        let upper = min(lower + 1, sorted.count - 1)\n        return sorted[lower] + (sorted[upper] - sorted[lower]) * (position - Double(lower))\n    }\n\n    /// Area under the ROC curve for scores against binary labels (Mann–Whitney U with average\n    /// ranks for ties). Nil when either class is empty.\n    public static func auroc(scores: [Double], labels: [Bool]) -> Double? {\n        precondition(scores.count == labels.count)\n        let positives = labels.filter { $0 }.count\n        let negatives = labels.count - positives\n        guard positives > 0, negatives > 0 else { return nil }\n        let r = ranks(scores)\n        var positiveRankSum = 0.0\n        for index in labels.indices where labels[index] { positiveRankSum += r[index] }\n        let u = positiveRankSum - Double(positives) * Double(positives + 1) / 2\n        return u / (Double(positives) * Double(negatives))\n    }\n\n    /// 1-based ranks of `values`, ties sharing their average rank.\n    public static func ranks(_ values: [Double]) -> [Double] {\n        let order = values.indices.sorted { values[$0] < values[$1] }\n        var ranks = [Double](repeating: 0, count: values.count)\n        var i = 0\n        while i < order.count {\n            var j = i\n            while j + 1 < order.count, values[order[j + 1]] == values[order[i]] { j += 1 }\n            let average = Double(i + j) / 2 + 1\n            for k in i...j { ranks[order[k]] = average }\n            i = j + 1\n        }\n        return ranks\n    }\n\n    public static func spearman(_ x: [Double], _ y: [Double]) -> Double? {\n        guard x.count == y.count, x.count >= 3 else { return nil }\n        return pearson(ranks(x), ranks(y))\n    }\n\n    public static func pearson(_ x: [Double], _ y: [Double]) -> Double? {\n        guard x.count == y.count, x.count >= 3, x.allSatisfy(\\.isFinite), y.allSatisfy(\\.isFinite) else { return nil }\n        guard let xMin = x.min(), let xMax = x.max(), xMin < xMax, let yMin = y.min(), let yMax = y.max(), yMin < yMax else { return nil }\n        let mx = mean(x), my = mean(y)\n        var sxy = 0.0, sxx = 0.0, syy = 0.0\n        for i in x.indices {\n            let dx = x[i] - mx, dy = y[i] - my\n            sxy += dx * dy\n            sxx += dx * dx\n            syy += dy * dy\n        }\n        guard sxx > 0, syy > 0 else { return nil }\n        let r = sxy / (sxx * syy).squareRoot()\n        return r.isFinite ? min(max(r, -1), 1) : nil\n    }\n\n    /// Ordinary least-squares slope of `values` against their indices; nil below two points.\n    public static func slope(_ values: [Double]) -> Double? {\n        guard values.count >= 2 else { return nil }\n        let n = Double(values.count)\n        let mx = (n - 1) / 2\n        let my = mean(values)\n        var sxy = 0.0, sxx = 0.0\n        for (i, y) in values.enumerated() {\n            let dx = Double(i) - mx\n            sxy += dx * (y - my)\n            sxx += dx * dx\n        }\n        return sxx > 0 ? sxy / sxx : nil\n    }\n\n    /// Cohen's κ between two binary series of equal length; nil when either is constant and they agree trivially.\n    public static func cohenKappa(_ a: [Bool], _ b: [Bool]) -> Double? {\n        guard a.count == b.count, !a.isEmpty else { return nil }\n        let n = Double(a.count)\n        var agree = 0.0, aTrue = 0.0, bTrue = 0.0\n        for (x, y) in zip(a, b) {\n            if x == y { agree += 1 }\n            if x { aTrue += 1 }\n            if y { bTrue += 1 }\n        }\n        let po = agree / n\n        let pe = (aTrue / n) * (bTrue / n) + (1 - aTrue / n) * (1 - bTrue / n)\n        guard pe < 1 else { return nil }\n        return (po - pe) / (1 - pe)\n    }\n\n    /// Welch's z (the t statistic with large-sample normal reading) for mean(a) − mean(b); nil below two per side.\n    public static func welchZ(_ a: [Double], _ b: [Double]) -> Double? {\n        guard a.count >= 2, b.count >= 2 else { return nil }\n        let se = (variance(a) / Double(a.count) + variance(b) / Double(b.count)).squareRoot()\n        guard se > 0 else { return nil }\n        return (mean(a) - mean(b)) / se\n    }\n}\n\n/// SplitMix64: a small, seedable generator for sampling and seeded draws, the same stream everywhere.\npublic struct SplitMix64: RandomNumberGenerator, Sendable {\n    private var state: UInt64\n\n    public init(seed: UInt64) { state = seed }\n\n    public mutating func next() -> UInt64 {\n        state &+= 0x9E37_79B9_7F4A_7C15\n        var z = state\n        z = (z ^ (z >> 30)) &* 0xBF58_476D_1CE4_E5B9\n        z = (z ^ (z >> 27)) &* 0x94D0_49BB_1331_11EB\n        return z ^ (z >> 31)\n    }\n}\n"},{"path":"Sources/BraidCore/Support/TOMLSubset.swift","lines":193,"bytes":7570,"header":{"lines":[1,11],"what":[8,10],"pin":null,"in":null,"out":null},"marks":[],"first":574,"scopes":[["E","TOMLValue",null,"public",15,15,[15,43],49,null,-1,0,["string","integer","float","bool","strings"]],["v","string",null,"public",22,22,[22,31],22,null,0,8],["v","integer",null,"public",23,23,[23,29],29,null,0,0],["v","float",null,"public",30,30,[30,30],36,null,0,0],["v","bool",null,"public",37,37,[37,27],37,null,0,8],["v","strings",null,"public",38,38,[38,34],38,null,0,8],["v","rendered",null,"",40,40,[40,25],48,null,0,0],["E","TOMLSubset",null,"public",51,51,[51,23],193,null,-1,0,[]],["E","Failure",null,"public",52,52,[52,67],60,null,7,0,["line"]],["v","description",null,"public",55,55,[55,39],59,null,8,0],["f","parse",["_"],"public static",65,65,[65,64],86,null,7,0],["f","render",["_"],"public static",88,88,[88,62],100,null,7,0],["f","value",["_","_","_"],"public static",102,102,[102,97],104,null,7,0],["f","isBareKey",["_"],"static",106,106,[106,47],106,null,7,8],["f","stripComment",["_"],"static",108,108,[108,55],118,null,7,0],["f","parseValue",["_","line"],"static",120,120,[120,74],141,null,7,0],["f","splitTopLevel",["_"],"static",143,143,[143,58],157,null,7,0],["f","quote",["_"],"static",159,159,[159,45],171,null,7,0],["f","unquote",["_"],"static",173,173,[173,48],192,null,7,0]],"text":"//\n//  TOMLSubset.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The flat TOML subset braid.toml uses: `key = value` lines, one level of `[table]`,\n//        strings, integers, floats, booleans and arrays of strings, `#` comments. Braid is the\n//        only writer, so the reader refuses anything outside the subset rather than guessing.\n//\n\nimport Foundation\n\npublic enum TOMLValue: Equatable, Sendable {\n    case string(String)\n    case integer(Int)\n    case float(Double)\n    case bool(Bool)\n    case strings([String])\n\n    public var string: String? { if case .string(let s) = self { return s } else { return nil } }\n    public var integer: Int? {\n        switch self {\n        case .integer(let i): return i\n        case .float(let f) where f == f.rounded(): return Int(f)\n        default: return nil\n        }\n    }\n    public var float: Double? {\n        switch self {\n        case .float(let f): return f\n        case .integer(let i): return Double(i)\n        default: return nil\n        }\n    }\n    public var bool: Bool? { if case .bool(let b) = self { return b } else { return nil } }\n    public var strings: [String]? { if case .strings(let a) = self { return a } else { return nil } }\n\n    var rendered: String {\n        switch self {\n        case .string(let s): return TOMLSubset.quote(s)\n        case .integer(let i): return String(i)\n        case .float(let f): return f == f.rounded() && abs(f) < 1e15 ? String(format: \"%.1f\", f) : String(f)\n        case .bool(let b): return b ? \"true\" : \"false\"\n        case .strings(let a): return \"[\" + a.map(TOMLSubset.quote).joined(separator: \", \") + \"]\"\n        }\n    }\n}\n\npublic enum TOMLSubset {\n    public enum Failure: Error, CustomStringConvertible, Equatable {\n        case line(Int, String)\n\n        public var description: String {\n            switch self {\n            case .line(let n, let why): return \"braid.toml line \\(n): \\(why)\"\n            }\n        }\n    }\n\n    /// Tables by name (\"\" for the top level), keys in order of appearance.\n    public typealias Document = [(table: String, entries: [(key: String, value: TOMLValue)])]\n\n    public static func parse(_ text: String) throws -> Document {\n        var document: Document = [(\"\", [])]\n        var current = 0\n        for (n, raw) in text.split(separator: \"\\n\", omittingEmptySubsequences: false).enumerated() {\n            let line = stripComment(String(raw)).trimmingCharacters(in: .whitespaces)\n            if line.isEmpty { continue }\n            if line.hasPrefix(\"[\") {\n                guard line.hasSuffix(\"]\"), !line.hasPrefix(\"[[\") else { throw Failure.line(n + 1, \"only one level of table\") }\n                let name = String(line.dropFirst().dropLast()).trimmingCharacters(in: .whitespaces)\n                guard isBareKey(name) else { throw Failure.line(n + 1, \"table name \\(name) is not a bare key\") }\n                document.append((name, []))\n                current = document.count - 1\n                continue\n            }\n            guard let equals = line.firstIndex(of: \"=\") else { throw Failure.line(n + 1, \"expected key = value\") }\n            let key = String(line[..<equals]).trimmingCharacters(in: .whitespaces)\n            guard isBareKey(key) else { throw Failure.line(n + 1, \"key \\(key) is not a bare key\") }\n            let value = try parseValue(String(line[line.index(after: equals)...]).trimmingCharacters(in: .whitespaces), line: n + 1)\n            document[current].entries.append((key, value))\n        }\n        return document\n    }\n\n    public static func render(_ document: Document) -> String {\n        var out = \"\"\n        for (i, table) in document.enumerated() {\n            if !table.table.isEmpty {\n                if !out.isEmpty { out += \"\\n\" }\n                out += \"[\\(table.table)]\\n\"\n            } else if i > 0 {\n                out += \"\\n\"\n            }\n            for entry in table.entries { out += \"\\(entry.key) = \\(entry.value.rendered)\\n\" }\n        }\n        return out\n    }\n\n    public static func value(_ document: Document, _ table: String, _ key: String) -> TOMLValue? {\n        document.first { $0.table == table }?.entries.first { $0.key == key }?.value\n    }\n\n    static func isBareKey(_ s: String) -> Bool { !s.isEmpty && s.allSatisfy { $0.isLetter || $0.isNumber || $0 == \"_\" || $0 == \"-\" } }\n\n    static func stripComment(_ line: String) -> String {\n        var inString = false\n        var escaped = false\n        for (i, c) in line.enumerated() {\n            if escaped { escaped = false; continue }\n            if c == \"\\\\\", inString { escaped = true; continue }\n            if c == \"\\\"\" { inString.toggle() }\n            if c == \"#\", !inString { return String(line.prefix(i)) }\n        }\n        return line\n    }\n\n    static func parseValue(_ text: String, line: Int) throws -> TOMLValue {\n        if text == \"true\" { return .bool(true) }\n        if text == \"false\" { return .bool(false) }\n        if text.hasPrefix(\"\\\"\") {\n            guard let s = unquote(text) else { throw Failure.line(line, \"unterminated string\") }\n            return .string(s)\n        }\n        if text.hasPrefix(\"[\") {\n            guard text.hasSuffix(\"]\") else { throw Failure.line(line, \"unterminated array\") }\n            let inner = String(text.dropFirst().dropLast()).trimmingCharacters(in: .whitespaces)\n            if inner.isEmpty { return .strings([]) }\n            var items: [String] = []\n            for part in splitTopLevel(inner) {\n                guard let s = unquote(part.trimmingCharacters(in: .whitespaces)) else { throw Failure.line(line, \"arrays hold strings only\") }\n                items.append(s)\n            }\n            return .strings(items)\n        }\n        if let i = Int(text) { return .integer(i) }\n        if let f = Double(text) { return .float(f) }\n        throw Failure.line(line, \"value \\(text) is not in the subset\")\n    }\n\n    static func splitTopLevel(_ text: String) -> [String] {\n        var parts: [String] = []\n        var current = \"\"\n        var inString = false\n        var escaped = false\n        for c in text {\n            if escaped { current.append(c); escaped = false; continue }\n            if c == \"\\\\\", inString { current.append(c); escaped = true; continue }\n            if c == \"\\\"\" { inString.toggle() }\n            if c == \",\", !inString { parts.append(current); current = \"\"; continue }\n            current.append(c)\n        }\n        if !current.trimmingCharacters(in: .whitespaces).isEmpty { parts.append(current) }\n        return parts\n    }\n\n    static func quote(_ s: String) -> String {\n        var out = \"\\\"\"\n        for c in s.unicodeScalars {\n            switch c {\n            case \"\\\"\": out += \"\\\\\\\"\"\n            case \"\\\\\": out += \"\\\\\\\\\"\n            case \"\\n\": out += \"\\\\n\"\n            case \"\\t\": out += \"\\\\t\"\n            default: out.unicodeScalars.append(c)\n            }\n        }\n        return out + \"\\\"\"\n    }\n\n    static func unquote(_ s: String) -> String? {\n        guard s.count >= 2, s.hasPrefix(\"\\\"\"), s.hasSuffix(\"\\\"\") else { return nil }\n        var out = \"\"\n        var escaped = false\n        for c in s.dropFirst().dropLast() {\n            if escaped {\n                switch c {\n                case \"n\": out.append(\"\\n\")\n                case \"t\": out.append(\"\\t\")\n                default: out.append(c)\n                }\n                escaped = false\n            } else if c == \"\\\\\" {\n                escaped = true\n            } else {\n                out.append(c)\n            }\n        }\n        return escaped ? nil : out\n    }\n}\n"},{"path":"Sources/BraidCore/Support/Version.swift","lines":18,"bytes":469,"header":{"lines":[1,9],"what":[8,8],"pin":null,"in":null,"out":null},"marks":[],"first":593,"scopes":[["E","BraidVersion",null,"public",13,13,[13,25],18,null,-1,0,[]]],"text":"//\n//  Version.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The package's version string and the session-log schema version, in one place.\n//\n\nimport Foundation\n\npublic enum BraidVersion {\n    /// The CLI's `--version`.\n    public static let string = \"0.1.0\"\n    /// The session log's schema (see Record/Session/SessionLog.swift). Bumped when a line's shape changes.\n    public static let sessionSchema = 1\n}\n"},{"path":"Sources/BraidCore/Support/WorkArea.swift","lines":75,"bytes":4132,"header":{"lines":[1,15],"what":[8,12],"pin":null,"in":null,"out":[13,14]},"marks":[],"first":594,"scopes":[["S","WorkArea",null,"public",19,19,[19,44],55,null,-1,0],["i","init",["root"],"public",26,26,[26,27],26,null,0,8],["f","resolve",["environment","exists"],"public static",29,29,[30,121],35,[28,28],0,0],["v","configFile",null,"public",37,37,[37,31],37,null,0,8],["v","packs",null,"public",38,38,[38,26],38,null,0,8],["v","modelsHome",null,"public",39,39,[39,31],39,null,0,8],["v","threads",null,"public",40,40,[40,28],40,null,0,8],["v","sessions",null,"public",41,41,[41,29],41,null,0,8],["v","bench",null,"public",42,42,[42,26],42,null,0,8],["v","datasets",null,"public",43,43,[43,29],43,null,0,8],["v","logs",null,"public",44,44,[44,25],44,null,0,8],["f","pack",["sha256"],"public",46,46,[46,44],46,null,0,8],["f","thread",["_"],"public",47,47,[47,55],47,null,0,8],["f","prepare",[],"public",50,50,[50,33],54,[49,49],0,0],["S","ThreadLayout",null,"public",58,58,[58,48],70,[57,57],-1,0],["v","record",null,"public",62,62,[62,27],62,null,14,8],["v","live",null,"public",63,63,[63,25],63,null,14,8],["v","snapshots",null,"public",64,64,[64,30],64,null,14,8],["v","versions",null,"public",65,65,[65,29],65,null,14,8],["v","checkpoints",null,"public",66,66,[66,32],66,null,14,8],["f","snapshot",["hash"],"public",68,68,[68,46],68,null,14,8],["f","version",["_"],"public",69,69,[69,46],69,null,14,8],["E","DemoHomes",null,"public",73,73,[73,22],75,[72,72],-1,0,[]],["f","root",["repository"],"public static",74,74,[74,52],74,null,22,8]],"text":"//\n//  WorkArea.swift\n//  BraidCore\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: Where Braid's data lives: `BRAID_WORK_AREA`, else the T9 work area\n//        `/Volumes/T9/rao/projects/braid` when the drive is mounted, else nowhere — Braid refuses\n//        to write to the internal disk unless told where (the braid runs that filled it are why).\n//        Demo AII homes are the exception: they need hard links, which the exFAT T9 has not, so\n//        they live under the repo (`DemoHomes`).\n//  OUT:  The layout under the work area: braid.toml, packs/<sha12>/, models/huggingface/,\n//        threads/<name>/, sessions/, bench/, datasets/, logs/.\n//\n\nimport Foundation\n\npublic struct WorkArea: Sendable, Equatable {\n    public static let environmentKey = \"BRAID_WORK_AREA\"\n    public static let t9Projects = URL(fileURLWithPath: \"/Volumes/T9/rao/projects\", isDirectory: true)\n    public static let t9 = t9Projects.appendingPathComponent(\"braid\", isDirectory: true)\n\n    public var root: URL\n\n    public init(root: URL) { self.root = root }\n\n    /// The work area named by the environment or the mounted T9; nil when neither is there.\n    public static func resolve(environment: [String: String] = ProcessInfo.processInfo.environment,\n                               exists: (URL) -> Bool = { FileManager.default.fileExists(atPath: $0.path) }) -> WorkArea? {\n        if let override = environment[environmentKey], !override.isEmpty {\n            return WorkArea(root: URL(fileURLWithPath: (override as NSString).expandingTildeInPath, isDirectory: true))\n        }\n        return exists(t9Projects) ? WorkArea(root: t9) : nil\n    }\n\n    public var configFile: URL { root.appendingPathComponent(\"braid.toml\") }\n    public var packs: URL { root.appendingPathComponent(\"packs\", isDirectory: true) }\n    public var modelsHome: URL { root.appendingPathComponent(\"models\", isDirectory: true).appendingPathComponent(\"huggingface\", isDirectory: true) }\n    public var threads: URL { root.appendingPathComponent(\"threads\", isDirectory: true) }\n    public var sessions: URL { root.appendingPathComponent(\"sessions\", isDirectory: true) }\n    public var bench: URL { root.appendingPathComponent(\"bench\", isDirectory: true) }\n    public var datasets: URL { root.appendingPathComponent(\"datasets\", isDirectory: true) }\n    public var logs: URL { root.appendingPathComponent(\"logs\", isDirectory: true) }\n\n    public func pack(sha256: String) -> URL { packs.appendingPathComponent(String(sha256.prefix(12)), isDirectory: true) }\n    public func thread(_ name: String) -> ThreadLayout { ThreadLayout(root: threads.appendingPathComponent(name, isDirectory: true), name: name) }\n\n    /// Creates the directories a fresh work area needs (idempotent).\n    public func prepare() throws {\n        for directory in [packs, modelsHome, threads, sessions, bench, logs] {\n            try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)\n        }\n    }\n}\n\n/// `threads/<name>/`: the record, the snapshots by hash, the versions, the pointer to the live one.\npublic struct ThreadLayout: Sendable, Equatable {\n    public var root: URL\n    public var name: String\n\n    public var record: URL { root.appendingPathComponent(\"thread.json\") }\n    public var live: URL { root.appendingPathComponent(\"live.json\") }\n    public var snapshots: URL { root.appendingPathComponent(\"snapshots\", isDirectory: true) }\n    public var versions: URL { root.appendingPathComponent(\"versions\", isDirectory: true) }\n    public var checkpoints: URL { root.appendingPathComponent(\"checkpoints\", isDirectory: true) }\n\n    public func snapshot(hash: String) -> URL { snapshots.appendingPathComponent(String(hash.prefix(12)), isDirectory: true) }\n    public func version(_ number: Int) -> URL { versions.appendingPathComponent(String(format: \"v%04d\", number), isDirectory: true) }\n}\n\n/// Where `braid aii create` puts demo AII homes: `<repo or cwd>/aii/<name>` on APFS.\npublic enum DemoHomes {\n    public static func root(repository: URL) -> URL { repository.appendingPathComponent(\"aii\", isDirectory: true) }\n}\n"}]};
